Principio de Economía Procesal: Según Chiovenda, es la obtención del máximo resultado po
sible con el mínimo de esfuerzo. Este principio se refiere no sólo a los actos procesales sino a
las expensas o gastos que ellos impliquen. “El principio de economía procesal, como principio del
procedimiento está referido en cuanto a la esfera temporal a la prudencia con que los jueces deben llevara
cabo los actos procesales, tratando de encontrar el justo medio entre la celeridad y el respeto a las form a
lidades que resulten imprescindibles, a fin de poder solucionar adecuadamente la controversia que es de
su conocimiento.” Cas. N° 1266-2001-Üma.
7. LOS JUICIOS PARALELOS
El derecho constitucional a la libertad de información puede generar excesos que influyan
negativamente en un proceso penal en marcha. Un juicio paralelo es aquel conjunto de infor
maciones aparecidas en los medios de comunicación sobre un asunto a tratar por el órgano
judicial, generándose una valoración social del comportamiento de personas implicadas. Nos
encontramos ante un efecto perverso resultante de combinar el saludable funcionamiento
del Estado de Derecho, la publicidad judicial y la libertad de información. Este fenómeno care
