8.1. Las Sentencias interpretativas-manipulativas (Normativas): STC EXP. t t ° 004-
2004-CC/TC-LIMA
En este caso el órgano de control constitucional detecta y determina la existencia de un con
tenido normativo inconstitucional dentro de una leyó norma con rango de ley. La elaboración
de dichas sentencias está sujeta alternativa y acumulativamente a dos tipos de operaciones:
la ablativay la reconstructiva.
La operación ablativa o de exéresis consiste en reducir los alcances normativos de la ley im
pugnada “eliminando” del proceso interpretativo alguna frase o hasta una norma cuya signi
ficación colisiona con la Constitución. Para tal efecto, se declara la nulidad de las “expresiones
impertinentes”; lo que genera un cambio del contenido preceptivo de la ley.
La operación reconstructiva o de reposición consiste en consignar el alcance normativo de la
ley impugnada "agregándosele” un contenido y un sentido de interpretación que no aparece
en el texto por sí mismo.
La existencia de este tipo de sentencias se justifica por la necesidad de evitar los efectos per
niciosos que puedan presentarse en determinadas circunstancias, como consecuencia de los
vacíos legales que surgen luego de la “expulsión” de una ley o norma con rango de ley del or
denamiento jurídico.
Existe una pluralidad de sentencias manipulativo-interpretativas; a saber:
Las sentencias redactaras: Son aquellas que señalan que una parte (frases, palabras, líneas,
etc.) del texto cuestionado es contraria a la Constitución, y ha generado un vicio de ¡n-
constitucionalidad por su redacción excesiva y desmesurada.
La sentencia reductora restringe el ámbito de aplicación de la ley impugnada a algunos
de los supuestos o consecuencias jurídicas establecidas en la literalidad del texto.
