Tema 3: Sistema de justicia
Las sentencias aditivas: Son aquellas en donde el órgano de control de la constitucionali-
dad determina la existencia de una inconstitucionalidad por omisión legislativa. En ese
contexto procede a "añadir" algo al texto incompleto, para transformarlo en plenamente
constitucional. En puridad, se expiden para completar leyes cuya redacción roñica pre
senta un contenido normativo "menor” respecto al exigióle constitucionalmente. En con
secuencia, se trata de una sentencia que declara la inconstitucionalidad no del texto de la
norma o disposición general cuestionada, sino más bien de lo que los textos o normas no
consignaron o debieron consignar.
Las sentencias sustitutivas: Son aquellas en donde el órgano de control de la constitucio-
nalidad declara la inconstitucionalidad parcial de una ley y, simultáneamente, incorpora
un reemplazo o relevo del contenido normativo expulsado del ordenamiento jurídico;
vale decir, dispone una modificación o alteración de una parte literal de la ley. La parte
sustituyente no es otra que una normaya vigente en el ordenamiento jurídico.
Las sentencias exhortativas: Son aquellas en donde el órgano de control constitucional de
clara la incompatibilidad constitucional de una parte o la totalidad de una ley o norma
con rango de ley, pese a lo cual no dispone su inmediata expulsión del ordenamiento
constitucional, sino que recomienda al Parlamento para que, dentro de un plazo razona
ble, expida una ley sustitutoria con un contenido acorde a las normas, principios o valores
constitucionales.
Las sentencias estipulativas: Son aquellas en donde el órgano de control de la constitucio-
nalidad establece, en la parte considerativa de la sentencia, las variables conceptuales o
terminológicas que utilizará para analizary resolver una controversia constitucional. En
ese contexto, se describirá y definirá en qué consisten determinados conceptos.
8.2. Los precedentes
- Precedente judicial vinculante:
Se entiende por Precedente, al antecedente ya resuelto, de un caso concreto que com
parte con aquel, sim ilitud en los supuestos de hecho del que nos ocupa. Es vinculante,
aquello que ata, somete o funda algo en otra cosa. En consecuencia, creemos, que debe
entenderse como precedente vinculante, las resoluciones jurisdiccionales dictadas por
las Salas Penales de la Corte Suprema de la República que determinan y establecen de
terminados principiosy doctrina jurisprudencial.
Son decisiones contenidas en una resolución de la instancia suprema, en la que resuelve
un caso concreto, del cual se extrae criterios generales cuya observancia se exige para los
casos futuros.
El precedente judicial en el sistema del Common Law se ha desarrollado como precedente
vinculante en sentido vertical; es decir, aplicable desde la Corte Suprema (para el caso
norteamericano) hacia las cortes y juzgados inferiores de todo el sistema judicial. (STC
Exp. 3741'' 2 0 0 4 ''AA/TC. Fj.48).
