El Tribunal Constitucional ha señalado en la STC Exp. 0024- 2003-AI/TC, que “el prece
dente constitucional vinculante es aquella regla jurídica expuesta en un caso particulary
concreto que el Tribunal Constitucional decide establecer como regla general; y, que por
ende, deviene en parámetro normativo para la resolución de futuros procesos de natu
raleza homologa". Seguidamente añade que: “El precedente constitucional tiene por su
condición de tal, efectos similares a una ley. Es decir, la regla general externalizada como
precedente a partir de un caso concreto se convierte en una regla preceptiva común que
alcanza a todos los justiciables y que es opon i ble frente a los poderes públicos”.
La competencia del Tribunal Constitucional para determinar un precedente vinculante
se encuentra sustentada en el Artículo VI del Título Preliminar del Nuevo Código Proce
sal Constitucional, el cual preceptúa que: “Las sentencias del Tribunal Constitucional que
adquieren la autoridad de cosa juzgada constituyen precedente vinculante cuando así
lo exprese la sentencia, precisando el extremo de su efecto normativo, form ulando la re
gla jurídica en la que consiste el precedente. Cuando el Tribunal Constitucional resuelva
apartándose del precedente, debe expresar los fundamentos de hecho y de derecho que
sustentan la sentenciay las razones por las cuales se aparta del precedente. (...)”
8.3. La Doctrina Jurisprudencia! Vinculante
Entendida, conforme el artículo 22 de la Ley Orgánica del Poder Judicial, como los criterios
doctrinarios establecidos (por los magistrados de las Salas Especializadas de la Corte Supre
ma) dentro de un pronunciamiento jurisdiccional (precedente vinculante) y fijados como
Principios Jurisprudenciales que han de ser de obligatorio cumplim iento por los magistrados
de todas las instancias judiciales cualquiera sea su especialidad, como precedente de obliga
torio cumplimiento.
8.4. Las Sentencias Plenarias y los Acuerdos Plenarios
8.4.1. Sentencias plenarias
Son una forma cualificada de precedentes vinculantes que tratan de armonizar e im prim ir
uniformidad a los criterios de los miembros de una Sala o a las diversas salas penales de la
Corte Suprema que tienen puntos de vista disímilesy/o contradictorios sobre un determinado
tema o asunto jurídico sometido a su competencia; Cabe advertir que en el segundo inciso
del artículo 301-A del Código de Procedimientos Penales, en la que se regula que las senten
cias de la Sala Penal de la Corte Suprema, sin perjuicio de lo dispuesto en el artículo 12 de la
Ley Orgánica del Poder Judicial, constituyen precedente vinculante cuando así lo expresen las
mismas, precisando el extremo de su efecto normativo (...) “si se advierte que otra Sala Penal
Suprema u otros integrantes de la respectiva Sala Penal en sus decisiones sostuvieran criterios
discrepantes sobre la interpretación o la aplicación de una determinada norma, a instancia
de cualquiera de las Salas, de la Fiscalía Suprema en lo Penal o de la Defensoría del Pueblo
(...) convocará inmediatamente al Pleno de los Vocales de los penal de la Corte Suprema para
dictar una Sentencia Plenaria, la que se adoptará por mayoría absoluta".
