Tema 8: Sistema de justicia
8.4.2. Acuerdos plenarios
Al respecto, Franco Gonzales2 citando al doctor Castillo Alva, refiere que "los Acuerdos Plena
rios a diferencia de los Precedentes vinculantes o las Sentencias Plenarias, no ejercen y desa
rrollan fuerza vinculante alguna. En tal sentido, dichos acuerdos no pueden ser utilizados para
plantear la aplicación obligatoria de una determinada decisión, en todo caso, por medio de los
Acuerdos Plenarios se puede exhortar, formal o materialmente, a las Salas Penales de la Corte
Suprema para que adopten un precedente vinculante o una Sentencia Plenaria,afindequesu
cumplim iento se vuelva exigióle desde el punto de vista normativo”3.
En efecto, los Acuerdos Plenarios, no ejercen fuerza vinculante alguna. Tampoco se le puede
homologar a los precedentes vinculantes o a las Sentencias Plenarias, con dicho propósito,
hacer ello, no sólo confunde a los operadores del derecho, sino que trastoca nuestro sistema
normativo.
Conforme a la base legal de los Plenos Jurisdiccionales, estos no son foros que emiten decla
raciones (Acuerdos Plenarios) que contienen “doctrina legal de carácter vinculante, que de
ben ser invocados por los magistrados de todas las instancias judiciales, como precedentes de
obligatorio cumplim iento”.
Pese a ello, si procedemos a revisar el texto de la parte final de la mayoría de los Acuerdos
Plenarios, vamos advertir que los distinguidos miembros que lo conforman “precisan” en la
parte final del mismo: "Que los principios jurisprudenciales que contiene la doctrina legal
antes mencionada deben ser invocados por los jueces de todas las instancias judiciales, sin
perjuicio de la excepción que estipula el segundo párrafo del artículo 22 de la LOPJ, aplicable
extensivamente a los Acuerdos Plenarios dictados al amparo del artículo 116o del estatuto or
gánico”; esto es, se pretende equiparar a los Acuerdos Plenarios, cuya naturaleza es la de un
pronunciamiento no Jurisdiccional, con los alcances de un Precedente Vinculante, recurriendo
para ello, a la creación de nuevos términos.
8.5. Las sentencias con efecto normativo
Son resoluciones judiciales vinculantes para los tribunales inferioresosuperioresysolo proce
de cuando se trate de casos similares o idénticos en este caso los principios generales consti
tuyen pautas de interpretación.
