Derecho-jueces, gobernantes, etc.- está sometido a normas tan inviolables como las reglas
taxativamente determinadas”, agregando; “...en los casos de facultades discrecionales, el po
der no tiene prefijada su decisión por un previo precepto detallado, sino que ante cada una
de las situaciones sometidas a su jurisdicción debe determinar el precepto más justo y ade
cuado; pero debe hacerlo, de ninguna manera por capricho singular, antes bien ateniéndo
se a directrices y criterios objetivos, que son los mismos que deben ser aplicados a todos los
demás casos análogos que se presenten”4. La delimitación entre lo discrecional y lo arbitrario
no es percibida por muchas personas que ejercen poder en nuestra sociedad, es usual que se
pretenda revestir de juridicidad a una elevada cantidad de actos arbitrarios, afirmando que
la autoridad respectiva “ha actuado en uso de la facultad discrecional que la ley le otorga”. En
algunos de estos casos se confunde lo que es un criterio personal y subjetivo con el criterio dis
crecional enmarcado por el Derecho. En otros de estos casos se actúa con pleno conocimiento
de la transgresión legal que im p lica d acto arbitrario, pero se recurre a la figura de la discrecio
nal idad para arroparse respecto a los cuestionamientos que form ule el afectado.
Si bien es cierto que la mayoría de los funcionarios públicos o detentadores del poder no ne
cesariamente tienen la formación jurídica para distinguir entre lo discrecional y lo arbitrario,
también lo es que el tema pasa por una cuestión de sentido común, y además porque en las
instituciones públicas regularmente se cuenta con un área de asesoría legal, por lo tanto, no
hay excusas frente al uso indebido de la facultad discrecional.
9 . E L C O N T R O L D E L A M O T IV A C IÓ N D E L A S D E C IS IO N E S J U D IC IA L E S ¥ F IS C A L E S
En la actividad fiscal y jurisdiccional a menudo se utiliza el térm ino motivación, para referirse
a la actividad por la cual los actores jurídicos (magistrados del Poder judicial y Ministerio Pú
blico), efectúan la tarea de fundamentar sus decisiones para la resolución de controversias
jurídicas. Y ello es coherente con lo establecido por el ordenamiento jurídico nacional, que
desde su Carta Magna, establece como principioyderecho de la función jurisdiccional el de
ber de m o tiva ció n de las resoluciones Sin embargo, si bien dicha motivación garantiza que los
juecesy magistrados se someten al principio de legalidady permite a los justiciables conocer
las razones que fundamentan las decisiones, abrie n do -in clu so- la posibilidad a los recursos
correspondientes, quizá dicha acepción (motivación), adolece de una ambigüedad que puede
resultar confusa si advertimos, que la motivación parece referirse indistintamente a la “razón
para decidir" y los “motivos sobre los que se apoya la decisión”. Esta forma de expresar la exigencia
de motivación, permite pensar que probablemente el propio térm ino motivación no sea el más
idóneo para designar la fundamentación de una sentencia, o una decisión que se tome en el
ámbito de la administración de justicia.
Motivar, es expresar los motivos; y los motivos no son necesariamente razones justificatorias.
Un motivo parece ser en principio la causa psicológica por la que una acción tiene lugar. Por
ejemplo, cabe decir que ju lio mató a Pedro movido por los celos, pero resulta extraño decir
que ju lio quitó la vida a Pedro justificado por los celos. Los celos explican la acción asesina de
julio, pero no la justifican. Del mismo modo, en rigor, al procesado (y a la teoría estándar de la
