1. DERECHO ADMINISTRATIVO DISCIPLINARIO
El poder disciplinario de la administración consiste en la facultad que tiene ésta para evaluar
la conducta funcional de los servidores civiles y, de ser el caso, aplicar las sanciones correspon
dientes, según la gravedad de la falta, mediante la observancia del proceso administrativo
que establece la norma sobre la materia. Dicho proceso debe guardar las garantías del debido
proceso, como presunción de inocencia, derecho a ser escuchado y a aportar pruebas, legali
dad, igualdad ante la ley, etc.
El Derecho Disciplinario se refiere al sistema ordenado de normas jurídicas materiales y pro-
cedimentales que regulan la potestad pública de establecer faltas y sanciones disciplinarias
a los servidores públicos. Se diferencia del Derecho Administrativo Sancionador por cuanto
éste se refiere a las faltas y sanciones administrativas que se imponen a los administrados que
sin ser servidores públicos contravienen el ordenamiento jurídico administrativo. El Derecho
Disciplinario al ser una rama especial del Derecho Administrativo se sustenta también en el
principio de legalidad, por lo que este derecho pretende garantizar la vigencia de las normas
jurídicas administrativas.
El bien jurídico protegido en el proceso disciplinario es el buen funcionamiento de la admi
nistración pública.
Son cuatro los elementos del poder disciplinario de la administración.
a. Sujetos:
- Sujeto activo: Es quien ejerce el poder de sancionar. Lógicamente que siendo de princi
pio, compete en general, al jerarca, salvo que el derecho positivo disponga otra cosa. Se
gún el Decreto legislativo N°276, corresponde al titu larde l pliego tomar la decisión sobre
la sanción a imponer. En cambio, de acuerdo a lo establecido por el Decreto Supremo N°
023-2011- PCM, corresponde al Tribunal del Servicio Civil la decisión de la sanción.
- Sujeto Pasivo: Es siempre un funcionarioy/o servidor público, porque sin vínculo laboral
funcional es inconcebible el ejercicio del poder sancionador.
b. Objeto: Es la aplicación de una medida disciplinaria, una sanción.
c. Motivo: Es la existencia de hechos que pueden perjudicar la marcha del servicio público.
d. Fin: Es la tutela del orden jurídico administrativo.
La determinación del motivo y del fin de un acto es determinante para considerar si el acto
tiene, o no, carácter disciplinario. Por ejemplo, un acto disponiendo un traslado de un fun
cionario y/o servidor público atendiendo al motivo y al fin puede ser dictado como sanción o
