1.1. La responsabilidad administrativa» civil y penal
Se entiende como responsabilidad a las consecuencias de las acciones u omisiones que debe
asumir un funcionario público en el ejercicio de sus funciones, en el ejercicio de sus funciones
los servidores y funcionarios públicos pueden incurrir en tres tipos de responsabilidad: res
ponsabilidades administrativa funcional, civil y penal.
La 9na disposición final de la Ley N° 27785- Ley Orgánica del Sistema Nacional de Control y de
la Contraloría General de la República, define las responsabilidades administrativa funcional,
civily penal:
Responsabilidad administrativa funcional, es aquella en laque incurren los servidores y fun
cionarios por haber contravenido el ordenamiento jurídico adm inistrativoy las normas inter
nas de la entidad a la que pertenecen, se encuentre vigente o extinguido el vínculo laboral
o contractual al momento de su identificación durante el desarrollo de la acción de control.
Incurren también en responsabilidad administrativa funcional los servidores y funcionarios
públicos que en el ejercicio de sus funciones, desarrollaron una gestión deficiente.
Responsabilidad civil, este tipo de responsabilidad infringen los servidores y funcionarios pú
blicos quienes por su acción u omisión, en el ejercicio de sus funciones, hayan ocasionado un
daño económico al Estado. Para que se configure la responsabilidad civil, es necesario que el
daño económico ocasionado se haya dado por incumpliendo a sus funciones, por dolo o por
culpa. Sobre el resarcimiento al Estado la norma expresa que ésta es de carácter contractual
y solidaria, y la acción prescribe a los diez años de ocurridos los hechos que generaron daño
económico a la Entidad.
Responsabilidad penal, incurren los servidores y funcionarios públicos, al ejercer sus funciones
han realizado un acto u omisión tipificado como delito. Al originarse una responsabilidad de
esta naturaleza, la administración pública tiene el derechoy la obligación de acudiral Ministerio
Público con la finalidad de que este organismo como titular de la acción penal, solicite la inter
vención del juez penal para que, en su momento, el sujeto activo del acto delictivo repare el daño
causado y sea sancionado con la medida coercitiva que determine el Código Penal.
Los tres tipos de responsabilidad encuentran plena justificación, dado que la comisión de
faltas puede no solo afectar el funcionamiento de la administración, en cuyo caso cabe la
responsabilidad administrativa, sino también causar perjuicio económico, dando lugar a la
responsabilidad civil y, finalmente, constituir conducta dolosa, con que se configura el tipo
penal que corresponda.
Las consecuencias civiles, administrativas o penales de la responsabilidad de las autoridades
son independientes y se exigen de acuerdo a lo previsto en su respectiva legislación.
1.2. Autonomía de responsabilidades
La autonomía de responsabilidades supone la coexistencia o concurrencia de dos o más res
ponsabilidades, en tanto que cada una de ellas, llámese administrativa funcional, penal o civil,
