UBILEX
tienen fundamentos y bienes jurídicos que proteger de diferente naturaleza, generando que
cada una sea valorada, calificada u materia de resolución por distintas autoridades que ejer
cen potestad sancionadora.
La autonomía de responsabilidades está reconocida en el A rt 264.1o del TUO de la Ley del
Procedimiento Administrativo General- D.S. 004-2019-]US, el cual establece que "Las conse
cuencias civiles, administrativas o penales de la responsabilidad de las autoridades son in
dependientes y se exigen de acuerdo a lo previsto en su respectiva legislación”. Asimismo, el
Artículo 4 9 ° de la Ley N° 27785, modificada por la Ley N° 29622, establece que “La responsa
bilidad administrativa funcional es independiente de las responsabilidades penales o civiles
que pudieran establecerse por los mismos hechos, en tanto los bienes jurídicos o intereses
protegidos son diferentes”.
2. PROCEDIMIENTO ADMINISTRATIVO SANCIONADOR
Un sector de la doctrina define el poder sancionador dado a la Administración como aquel en
virtud del cual “pueden imponerse sanciones a quienes incurran en la inobservancia de las acciones u
omisiones que le son impuestas por el ordenamiento normativo administrativo, o el que sea aplicable por
la Administración Pública en cada caso’P
El procedimiento administrativo sancionador es entendido, en primer término, como el con
junto de actos destinados a determinar la existencia de responsabilidad administrativa, esto
es, la comisión de una infracción y la consecuente aplicación de una sanción. Dicho procedi
miento constituye, además, una garantía esencial y el cauce a través del cual los administra
dos, a quienes se les imputan la comisión de una infracción, hacen valer sus derechos funda
mentales frente a la Administración Pública.
El procedimiento sancionador garantiza que la actuación de la Administración se lleve a cabo
de una manera ordenada y orientada a la consecución de un fin y respetando un mínimo de
garantías para el administrado.
2.1. Principios del procedimiento administrativo sancionador
El artículo 248 del TUO de la Ley N° 27444 recogen principios que rigen el ejercicio de la po
testad sancionadora de las entidades públicas. Entre estos principios se cuentan los siguien
tes: legalidad, debido procedimiento, razonabilidad, tipicidad, irretroactividad, concurso de
infracciones, continuación de infracciones, causalidad, presunción de licitud, culpabilidad y
non bis in Ídem. Estos principios se aplican, de manera adicional, a los principios generales pre
vistos en el artículo IV del Título Preliminar del TUO de la Ley N° 27444-
i) Principio de Legalidad.- El Principio de Legalidad ha sido incorporado por el legislador
en el inciso 1 del artículo 248o de la Ley N° 27444, al establecer que “sólo por norma con ran
go de ley cabe atribuir a las entidades la potestad sancionadora y la consiguiente previsión de las
consecuencias administrativas que a título de sanción son posibles de aplicara un administrado, las
que en ningún caso habilitarán a disponer la privación de libertad”. A nivel constitucional está
