Tema 9: Responsabilidades adm inistrativas y penales
consagrado en el literal d) del numeral 24 del artículo 2, dispone: "Nadie será procesado ni
condenado por acto u omisión que ai tiempo de cometerse no esté previamente calificado por la ley,
de manera expresa e inequívoca, como infracción punible; ni sancionado con pena no prevista en la
ley”.
Aun cuando se trata de una previsión enfocada en el ámbito del Derecho Penal (en aten
ción a la unidad del derecho sancionador estatal), esta disposición también constituye
una garantía para el ejercicio de la potestad sancionadora en el ámbito del derecho ad
ministrativo.
El Tribunal Constitucional (STC Exp. N °i i 82-2005-PA/TC» FJ. 14)ha señalado que la apli
cación del principio de legalidad impide que se pueda atribuir la comisión de una falta o
aplicar una sanción administrativa cuando esta no se encuentre previamente determina
da en la ley. En ese sentido, dicho principio abarca una doble exigencia:
i) Exigencia de carácter formal: Implica la exigenciay existencia de una norma legal o
norma con rango de ley; y,
i i) Exigencia de carácter material: Implica la predeterminación normativa de las con
ductas infracto ras y de las sanciones correspondientes.
En síntesis, podemos afirmar que el principio de legalidad tiene como exigencias
específicas: la existencia de una ley (leyscripta); que esta ley sea anterior a la conduc
ta reprochable (ley previa); y, que esta ley incluya preceptos jurídicos con suficiente
grado de certeza (lex certa), de manera tal que sea posible prever la responsabilidad
y la eventual sanción e aplicable a un caso concreto2.
ii) Principio de Tipicidad.- Conforme a ley, este principio consiste en que "Solo constituyen
conductas sancionares administrativamente las infracciones previstas expresamente en normas
con rango de ley mediante su tipificación como tales, sin admitir interpretación extensiva o analo
gía. Las disposiciones reglamentarias de desarrollo pueden especificar ograduar aquellas dirigidas
a identificarlas conductas o determinar sanciones, sin constituir nuevas conductas sanciona bles a
las previstas legalmente, salvo los casos en que la ley o Decreto Legislativo permita tipificar infrac
ciones por norma reglamentaria.
A través de la tipificación de infracciones no se puede imponer a los administrados el
cumplim iento de obligaciones que no estén previstas previamente en una norma legal o
reglamentaria, según corresponda.
En la configuración de los regímenes sancionadores se evita la tipificación de infracciones
con idéntico supuesto de hecho e idéntico fundamento respecto de aquellos delitos o fal
tas ya establecidos en las leyes penales o respecto de aquellas infracciones ya tipificadas
en otras normas administrativas sancionadoras”3.
El Tribunal Constitucional considera a la tipicidad o taxatividad como una de las manifes
taciones del principio de legalidad respecto de los límites que se imponen al legislador
2 Guía práctica sobre el procedimiento administrativo sancionador. Ministerio de justicia y Derechos Humanos, junio
2017. p. 15.
3 Inciso 4 artículo 248 TUO de la Ley 27444-
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN I
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 184 of 1506 --

UBILEX
penal o administrativo, a efectos de que las prohibiciones (que definen sanciones) estén
redactadas con un nivel de precisión suficiente que permita a cualquier ciudadano de
formación básica, comprender sin dificultad lo que se está proscribiendo bajo amenaza
de sanción en una determinada disposición legal. El criterio del Tribunal Constitucional
es, en ese sentido, el de considerar que la tipicidad constituye la precisa definición de la
conducta que la ley considera como falta4.
El principio de tipicidad alude al grado de predeterminación normativa de los comporta
mientos típicos proscribiendo supuestos de interpretación extensiva o analógica, lo cual
significa que solo cabe castigar un hecho cuando este se encuentre precisamente defi
nido y se tenga claramente definida su penalidad. Conforme a su naturaleza, el principio
de tipicidad no se encuentra sujeto a una reserva de ley absoluta, pues en determinadas
situaciones podría ser complementado a través de los reglamentos respectivos5.
En ese sentido, si bien el inciso 4 del artículo 248 del TUO de la Ley N° 27444 establece
que solo constituyen conductas sancionables las infracciones previstas en normas con
rango de ley sin adm itir interpretación extensiva o analogía, seguidamente admite la po
sibilidad de que mediante reglamentos se especifique o gradúe disposiciones dirigidas a
identificar infracciones o determinar sanciones (siemprey cuando no constituyan nuevas
conductas sancionables a las previstas en la ley). Asimismo, dicha disposición establece
que mediante ley o Decreto Legislativo es posible habilitar la tipificación de infracciones
por norma reglamentaria.
Cabe indicar que no cualquier colaboración reglamentaria se encuentra permitida por la
norma, pues solo se admite aquella que se encuentra alineada con lo previsto en la ley
y no sobrepasen los límites naturales que le son permitidos. Asimismo, considerando
que existen casos en los que resulta imposible que en instrumentos legales se recojan las
conductas sancionables para el ejercicio de la potestad sancionadora, la norma establece
que la ley o decreto legislativo pueden habilitar la tipificación de infracciones por norma
reglamentaria.
Al respecto, el Tribunal Constitucional ha señalado que “...las sanciones administrativas pue
den estar contenidas en reglamentos, siempre que así lo habilite expresamente la Ley que asigna
competencias sancionadoras al ente administrativo correspondiente. En el presente caso, dicho
requisito se cumple, dado que los artículos 51 y 58 de la Ley Orgánica del Ministerio Público, han
delegado la tipificación de las sanciones en el Reglamento de Organizacióny Funciones de la Fiscalía
Suprema de Control Interno del Ministerio Público." STC Exp. N° 3485-2012-AA/TC. Voto emiti
do por los magistrados Ramos Núñezy Blume Fortini. FJ. 2.
Finalmente, con el propósito de evitar la sobre criminalización de determinadas conduc-
tasy la afectación al principio non bisin ídem, el inciso 4 del artículo 248 del TUO de la Ley
N° 2 7 44 4 prevé que se debe evitar la tipificación de infracciones con idéntico supuesto de
hecho e idéntico fundamento respecto de aquellos delitos o faltas establecidos en leyes
penales o infracciones tipificadas en otras normas administrativas sancionadoras.
