Tema 9: Responsabilidades adm inistrativas y penales
ii i) Principio del Debido Procedimiento.- El principio del debido procedimiento, en el ám bi
to del derecho administrativo sancionados ha sido concretizado en el inciso z del artículo
248 del TUO de la Ley N° 27444 en los siguientes términos:” No se pueden imponer sanciones
sin que se haya tramitado el procedimiento respectivo, respetando las garantías del debido proce
dimiento. Los procedimientos que regulen el ejercicio de la potestad sancionadora deben establecer
la debida separación entre la fase instructora y la sancionadora, encomendándolas a autoridades
distintas”,
El principio del debido procedimiento tiene su origen en el principio del debido proceso,
éste no solo tiene alcance jurisdiccional, sino que se proyecta a otros ámbitos del que
hacer público, como el administrativo. Nuestro Tribunal Constitucional, apoyado en la
jurisprudencia internacional ha establecido que: “(...) no sólo los principios materiales
del derecho sancionador del Estado son aplicables al ámbito del derecho administrativo
sancionadory disciplinario. También lo son las garantías adjetivas que en aquél se deben
de respetar. En efecto, es doctrina consolidada de este Colegiado que el derecho recono
cido en el inciso 3) del artículo 139o de la Constitución no sólo tiene una dimensión, por
así decirlo, "judicial”, sino que se extiende también a sede “administrativa” y, en general,
como laCorte Interamericanade Derechos Humanos lo ha sostenido, a “cualquier órgano
del Estado que ejerza funciones de carácter materialmente jurisdiccional, (la que) tiene la
obligación de adoptar resoluciones apegadas a las garantías del debido proceso legal, en
los términos del artículo 8o de la Convención Americana.” (Caso Tribunal Constitucional
del Perú, párrafo 71). Y es que, sostiene la Corte Interamericana, en doctrina que hace suya
este Tribunal Constitucional, “si bien el artículo 8o de la Convención Americana se titu la
Garantías Judiciales, su aplicación no se lim ita a los recursos judiciales en sentido estricto,
sino al conjunto de requisitos que deben observarse en las instancias procesales, a efectos
deque las personas puedan defenderse adecuadamente ante cualquiertipo de acto ema
nado del Estado que pueda afectar sus derechos.”(Párrafo 69). “(...) Cuando la Convención
se refiere al derecho de toda persona a ser oída por un “juez o tribunal competente” para la
“determinación de sus derechos", esta expresión se refiere a cualquier autoridad pública,
sea administrativa, legislativa o judicial, que a través de sus resoluciones determine dere-
chosy obligaciones de las personas.” (Párrafo 71) [La Corte ha insistido en estos postulados
en los Casos Baena Ricardo, del 2 de febrero de 2001 (Párrafos 124-127), e Ivcher Bronstein,
del 6 de febrero de 2001 (Párrafo 105)]6.
Asi, todo ejercicio de la potestad administrativa debe observar la Ley del Procedimiento
Administrativo General, ley marco que regula la actuación administrativa. Al respecto, el
artículo IV del Título Preliminar, consagra, entre otros, el derecho al debido procedimien
to, que garantiza que los administrados gocen de derechos tales como el de exponer sus
argumentos, de ofrecery producir pruebasy obtener una decisión m otivaday fundamen
tada en el derecho. Según doctrina atinentes, dicho principio tiene tres niveles concurren
tes de aplicación, el primero de los cuales se refiere al debido proceso como derecho al
procedimiento adm inistrativoy supone que: “(...) todos los administrados tienen el dere
cho a la existencia de un procedimiento administrativo previo a la producción de las de-
