iv) Principio de Razonabilidad.- El principio de razonabilidad se encuentra regulado en el
inciso 3 del artículo 248 del TUO de la Ley N° 2 7 4 4 4 , en los siguientes términos: “Las auto
ridades deben prever que la comisión de la conducta sancionable no resulte más ventajosa para el
infractor que cumplir las normas infringidas o asumir la sanción. Sin embargo, las sanciones a ser
aplicadas deben ser proporcionales al incumplimiento calificado como infracción, observando los
siguientes criterios que se señalan a efectos de su graduación:
a) El beneficio ilícito resultante por la comisión de la infracción;
b) La probabilidad de detección de la infracción;
c) La gravedad del daño al interés públicoy/o bien jurídico protegido;
d) El perjuicio económico causado;
e) La reincidencia, por la comisión de la misma infracción dentro del plazo de un (1) año
desde que quedó firme la resolución que sancionó la primera infracción.
f) Las circunstancias de la comisión de la infracción; y
g) La existencia o no de intencionalidad en la conducta del infractor”.
Si bien se trata del principio de «razonabilidad», es necesario dejaren claro que su conte
nido se encuentra vinculado directamente con el principio de proporcionalidad, esto es,
con la adecuación aplicable entre la gravedad del hecho constitutivo de la infracción y la
sanción aplicada. En ese sentido, es posible afirm ar que el legislador peruano ha asumido
el contenido material del principio de proporcionalidad denominándolo razonabilidad.
El Tribunal Constitucional ha sostenido que si bien la doctrina suele hacer distinciones
entre el principio de proporcionalidad y el principio de razonabilidad (como estrategias
para orientar al juzgador hacia una decisión que no sea arbitraria sino justa) prima facie
es posible establecer sim ilitud entre ambos principios, toda vez que una decisión que se
adopta en el marco de convergencia de dos principios constitucionales no será razona
ble cuando no respete el principio de proporcionalidad. El principio de proporcionalidad,
gestado originariamente en la doctrina alemana como principio incluido en uno más
general de «prohibición de exceso», constituye un criterio constitucional que informa la
actividad de los poderes públicos que es susceptible de restringir, lesionar o lim itar de
alguna forma los derechos individuales de los ciudadanos. De ahí que, conforme lo señala
el Tribunal Constitucional, sea en el seno de la actuación de la Administración donde el
principio de proporcionalidad cobra especial relevancia debido a los márgenes de dis
creción con que inevitablemente actúa para atender las demandas de una sociedad en
constante cambio. Sobre ello, también debe tomarse en cuenta la importancia de la pre
sencia de cláusulas generales e indeterminadas, como el interés general o el bien común,
