Tema 9: Responsabilidades adm inistrativas y penales
que deben ser compatibilizadas con otras cláusulas o principios igualmente abiertos a la
interpretación, como son los derechos fundamentales o la propia dignidad de las perso
nas7.
De esta forma, se establece un límite para la actuación represiva de las autoridades ad
ministrativas que solo podría ser llevada a la práctica cuando resulte estrictamente ne
cesaria, idónea y proporcionada para obtener los objetivos que persigue. Desde esta
perspectiva, cuando los fines buscados con la adopción de dichas normas puedan ser
conseguidos a través de medidas alternativas manifiestamente menos gravosas, habrá
de imponerse la utilización de estas últimas8.
v) Principio de irretroactividad.- El principio de irretroactividad está regulado en el inciso 5
del artículo 248 del TUO de Ley N° 2 7 4 4 4 , señala: “Son aplicables las disposiciones sanciona-
doras vigentes en el momento de incurrir el administrado en la conducta a sancionar, salvo que las
posteriores le sean más favorables. Las disposiciones sancionadoras producen efecto retroactivo en
cuanto favorecen al presunto infractor o al infractor, tanto en lo referido a la tipifcación de la infrac
ción como a la sanción y a sus plazos de prescripción, incluso respecto de las sanciones en ejecución al
entraren vigor la nueva disposición”.
Este principio, que se deriva del artículo 103 de la Constitución, establece la imposibilidad
de imponer sanciones cuando la norma que las tipifica no hubiera estado en vigor en el
momento de la comisión de la infracción.
La doctrina señala que el principio de irretroactividad de las normas sancionadoras se
fundamenta en el principio de seguridad jurídica, es decir, en la necesidad de conocer en
todo momento qué conductas son reprochables y qué grado de reproche se establece a
través de la sanción concreta. Dicho principio también se encuentra vinculado al derecho
fundamental a la legalidad (como garantía formal y material) por el que las normas san
cionadoras no pueden desplegar efectos retroactivos in peius. En ese sentido, el principio
de irretroactividad involucra que, por regla general, corresponde aplicar las normas san
cionadoras vigentes en el momento de la configuración de la infracción administrativa.
No obstante, este principio contiene una excepción importante, la cual se configura cuan
do la norma posterior resulta más favorable para el administrado.
Mediante el artículo 2 del Decreto Legislativo N° 1272 se modificó el principio de irre
troactividad a fin de precisar los supuestos respecto de los cuales se podría configurar su
excepción, es decir, la aplicación retroactiva de una norma posterior más favorable. Estos
supuestos son los siguientes:
Tipificación de la infracción más favorable.
Previsión de la sanción más favorable. Incluso respecto de aquellas sanciones que se
encuentran en ejecución al entrar en vigor la norma nueva.
Plazos de prescripción más favorables.
