Como se puede apreciar, la nueva regulación del principio de irretroactividad no hace
más que detallar los alcances de la retroactividad benigna, precisando que esta podrá ser
aplicada para la tipificación de la infracción, determinación de plazos de prescripción, así
como para la previsión de las sanciones administrativas (incluso cuando estas se encuen
tren en fase de ejecución) .9
vi) Principio de concurso de infracciones.- La Ley señala que: "Cuando una misma conducta
califique como más de una infracción se aplicará la sanción prevista para la infracción de mayor
gravedad, sin perjuicio que puedan exigirse las demás responsabilidades que establezcan las leyes”
Inciso 6 artículo 248 TUO de la Ley 27444-
En el ámbito del derecho administrativo sancionador es posible que se presenten casos
en los que una misma conducta o hecho califique como más de una infracción adminis
trativa. En dichos casos se puede aplicar diferentes opciones teóricas para determinar la
sanción que corresponde aplicar. Si se elimina la acumulación material (suma de las pe
nas atribuidas a todos y cada uno de los delitos cometidos por la misma acción) restarían
fundamentalmente 2 posibilidades, estas son: i) la absorción de la pena, lo cual implicaia
elección de la pena más grave entre todas las que entran enjuego a la vista de los delitos
cometidos; o, ii) la exasperación (o aspiración) de la pena, la cual implica escoger la más
grave y además elevar o intensificar su contenido, aunque sin llegar, naturalmente, a la
suma de todas ellas1011. En el caso peruano se ha optado por la primera posibilidad.
vii) Principio de continuación de infracciones.- El principio de continuación de infracciones
se encuentra enunciado en el inciso 7 del artículo 248 del TUO de la Ley N° 2 7 4 4 4 : "Para
determinar la procedencia de la imposición de sanciones por infracciones en las que el administra
do incurra en forma continua, se requiere que hayan transcurrido por lo menos treinta (30) días
hábiles desde la fecha de la imposición de la última sanción y que se acredite haber solicitado al
administrado que demuestre haber cesado la infracción dentro de dicho plazo. Las entidades, bajo
sanción de nulidad, no podrán atribuir el supuesto de continuidady/o la imposición de la sanción
respectiva, en los siguientes casos: a) Cuando se encuentre en trámite un recurso administrativo
interpuesto dentro del plazo contra el acto administrativo mediante el cual se impuso la última
sanción administrativa, b) Cuando el recurso administrativo interpuesto no hubiera recaído en acto
administrativo firme, c) Cuando la conducta que determinó la imposición de la sanción administra
tiva original haya perdido el carácter de infracción administrativa por modificación en el ordena
miento, sin perjuicio de la aplicación de principio de irretroactividad a que se refiere el incisos.”
La infracción continuada puede ser definida como, en palabras del maestro español Ale
jandro Nieto, como "(...) la realización de acciones u omisiones que infrinjan el mismo o semejan
tes preceptos administrativos, en ejecución de un plan preconcebido (...)’ni, o al profesor argentino
