Tema 9: Responsabilidades adm inistrativas y penales
Daniel Maljar, quien la define como “el mantenimiento de una situación ilícita en tanto no sea
alterada mediante una conducta contraria por parte del autor de la infracción (...)”n .
En este mismo orden de ideas, se haya la jurisprudencia internacional del Tribunal de
Justicia de la Comunidad Europea1213, para quien “(...) el concepto de infracción continuada (...),
implica, en cualquier caso, una pluralidad de comportamientos infractores, o de actos de ejecución
de una sola infracción, reunidos por un elemento subjetivo común
Cabe indicar que este principio aplica frente a una conducta ilícita que no constituye un
acto aislado y concreto sino una actividad perdurable y constante. Dicho en otros térm i
nos, se trata de una conducta reiterada por una voluntad duradera en la que no se da
situación concursal alguna, sino una progresión unitaria con repetición de actos14.
El supuesto de infracción continuada exige que se hayan cometido varias acciones u om i
siones que infrinjan el mismo precepto y que el autor actúe en ejecución de un plan pre
concebido o aprovechando idéntica ocasión. Para considerar que existe unidad de hecho
(o de acción en sentido amplio) se requiere que en un breve periodo de tiem poy de forma
sucesiva se reitere la misma acción típica guiada por un propósito único. De esta manera,
el requisito del plazo establecido en la norma implica que un distanciamiento de espacio
y tiempo considerable entre unay otra acción puede dificultar, si no impedir, la refundi
ción de todas ellas en una sola que sea creadora de un único castigo15.
viii) Principio de Causalidad de la responsabilidad.- Por el principio de causalidad, la respon
sabilidad debe recaer en quien realiza la conducta omisiva o activa constitutiva de infracción san-
cionable. (Inciso 8 del Artículo 248 del TUO de la Ley 2 7 44 4 °) •
La norma exige el principio de personalidad de las sanciones, entendida como, que la
asunción de la responsabilidad debe corresponder a quien incurrió en la conducta pro
hibida por la ley, y, por tanto no podrá ser sancionado por hechos cometidos por otros
(por ejemplo, la responsabilidad por un subordinado, o imputar responsabilidad a un in
tegrante del cuerpo colectivo que no voto o salvo su voto) o por las denominadas respon
sabilidades en cascada aplicables a todos quienes participan en una proceso decisional.
Por ello, en principio, la administración no puede hacer responsable a una persona por
un hecho ajeno, sino solo por los propios. Asimismo, implica que para la aplicación de la
sanción resulta condición indispensable que la conducta del administrado satisfaga una
relación de causa-efecto respecto del hecho considerado infracción; y que además, haya
sido idónea para producir la lesión y no tratarse de los casos de fuerza mayor, hecho de
tercero o la propia conducta del perjudicado.16
Este principio conecta con otro bastante debatido en el derecho administrativo sancio-
nador: el de culpabilidad del infractor. A falta de norma, en nuestro derecho ha sido ¡n-
