traducido jurisprudencial mente por el Tribunal Constitucional como una exigencia para
ejercer legítimamente la potestad sancionadora. En efecto, nuestro Tribunal ha estable
cido: “(...) Por lo que hace al primer motivo, es decir, que la sanción se justifique (...) es lícito que el
Tribunal se pregunte si es que en un Estado constitucional de derecho es válido que una persona sea
sancionada por un acto ilícito cuya realización se imputa a un tercero. La respuesta no puede ser
otra que (...): un límite a la potestad sancionatoria del Estado está representado por el principio de
culpabilidad. Desde este punto de vista, la sanción, penal o disciplinaria, solo puede sustentarse en
la comprobación de responsabilidad subjetiva del agente infractor de un bien jurídico. En ese sentido,
no es constitucionalmente aceptable que una persona sea sancionada por un acto o una omisión de
un deber jurídico que no lesea imputable”17.
ix) Principio de presunción de licitud.- Por el principio de presunción de licitud, más cono
cido como presunción de inocencia, las entidades deben presumir que los administrados han
actuado apegados a sus deberes mientras no cuenten con evidencia en contrario. (I nciso 9 del Artí
culo 248 del TUO de la Ley 27444o).
Conforme a esta presunción de inocencia, de corrección o de licitud, las autoridades de
ben presumir que los administrados han actuado apegados a sus deberes mientras no
cuenten con evidencia en contrario y así sea declarada mediante resolución administra
tiva firme. Dicha presunción cubre al imputado durante el procedimiento sancionador,
y se desvanece o confirma gradualmente, a medida que la actividad probatoria se va
desarrollando, para finalmente definirse mediante al acto administrativo final del pro
cedimiento. La presunción sólo cederá si la entidad puede acopiar evidencia suficiente
sobre los hechosy su autoría, tener seguridad que se han producido todos los elementos
integrantes del tipo previsto,y un razonamiento lógico suficiente que articule todos estos
elementos formando convicción.
Conceptual mente esta presunción significa un estado de certeza provisional por la que el
imputado adquiere los siguientes atributos a ser respetados por todos durante el proce
dimiento:
a) A no ser sancionado sino en virtud de pruebas que generen convicción sobre la res
ponsabilidad del administrado y siempre que hayan sido obtenidas legítimamente.
Un administrado no puede ser sancionado sobre la base de una inferencia, de una
sospecha, por falta de apersonamiento o por la no absolución de los cargos, por más
razonable o lógica que pueda ser el planteamiento mental seguido por la autori
dad18. Adicionalmente, las pruebas de cargo que fundamentan la decisión adminis
trativa deben haber sido obtenidas legítimamente y con las garantías del control y
17 Fundamento recaído en la sentencia del Exp. N.° 2868-2004-AA/TC.
18 El Tri bunal Constitucional ha declarado q ue “El derecho de presunción de inocencia garantiza que toda persona no sea
sancionada si es que no existe prueba plena que, con certeza, acredite su responsabilidad, administrativa o judicial, de los
cargos atribuidos. Evidentemente se lesiona ese derecho a la presunción de inocencia tanto cuando se sanciona, pese a no
existir prueba plena sobre la responsabilidad del investigado, como cuando se sanciona por actos u omisiones en los que el
investigado no tuvo responsabilidad. Siendo tal la situación en la que se sancionó al recurrente, este Tribunal estima que se
ha acreditado la violación del derecho a la presunción de inocencia" (STC No. 2868-2004-AA/TC)
