b) A que no se le imponga la carga de probar su propia inocencia, ya que corresponde
la actividad probatoria a la administración. De un lado, ratifica que en materia san-
cionadora la carga de la prueba recae en la Administración, por lo que compete a
las autoridades identificar, atraer al expediente y actuar la evidencia suficiente que
sustente desestimar la presunción, quedando incluso el administrado liberado de
actuar aquella prueba que lo pueda auto incriminar20. Pero del otro, este principio
conlleva a que en el procedimiento sancionadorse actúen cuando menos una m íni
ma actividad probatoria sobre los hechos a analizar, no bastando las declaraciones
o afirmaciones de los denunciantes o terceros-aún bajo presunción de veracidad-
para desvirtuar la presunción de corrección, ni los descargos del imputado2122. En ese
sentido, es correcto lo afirmado por el Tribunal Constitucional respecto a que “Toda
sanción,ya sea penal o administrativa, debe fundarse en una mínima actividad probatoria de
cargo, es decir, la carga de la prueba corresponde al que acusa; éste debe probar el hecho por el
que acusa a una determinada persona, proscribiéndose sanciones que se basen en presuncio
nes de culpabilidad. Así, la presunción de inocencia (Constitución, Art. z°, 24.e) constituye un
límite al ejercicio de la potestad sancionatoria del Estado, en sus diversas manifestaciones”12.
c) A un tratam iento como inocente, a lo largo del procedimiento sancionador, por lo
que a los imputados deben ser respetados en todos sus derechos subjetivos, como
son al honor, la buena reputación, la dignidad, etc. En tanto la resolución no se dicte
y alcance firmeza, la presunción aplica y protege al administrado, por lo que el com
portamiento de la autoridad, sus actuaciones, e incluso la de los terceros (por ejem
plo, denunciantes) debe considerar que la persona no puede ser señalada como cul
pable ni como imputado procesado. Aun el imputado debe poseer la garantía de
ser reconocidos en su dignidad por la colectividad. Por ello, quedan delimitadas las
posibilidades de dictar medidas cautelares en contra del administrado, o publicitar
innecesariamente la apertura del procedimiento sancionador y a cualquier acción
que importe una apariencia de condena previa al administrado.
