d) A la absolución en caso de insuficiencia probatoria o duda razonable sobre su cul
pabilidad. (Si la evidencia actuada en el procedimiento administrativo sancionador
no llega a formar convicción de la ilicitud del acto y de la culpabilidad del adminis
trado, se impone el mandato de absolución implícito que esta presunción conlleva
{in dubio pro reo). En todos los casos de inexistencia de prueba necesaria para destruir
la presunción de inocencia, incluyendo la duda razonable, obliga a la absolución del
administrado).
x) Principio de culpabilidad.- Señala el inciso 10 del artículo 248 del TUO de la Ley 27444
que: “La responsabilidad administrativa es subjetiva, salvo los casos en que por ley o decreto legis
lativo se disponga la responsabilidad administrativa objetiva”.
En aplicación del principio de culpabilidad, la responsabilidad administrativa tiene nece
sariamente carácter subjetivo, a excepción de los casos en q ue por ley o decreto legislativo
se disponga la responsabilidad administrativa objetiva. Ello implica que la entidad pú
blica con potestad sancionadora se encuentra obligada acreditar la responsabilidad sub
jetiva (dolo o culpa) como elemento indispensable para la imputación de una infracción
administrativa.
La incorporación del principio de culpabilidad en el ámbito del procedimiento adminis
trativo sancionador constituye una de las grandes novedades de la modificación operada
mediante el artículo 2 del Decreto Legislativo N°i272, pues antes de ello, la ley del proce
dimiento administrativo general parecía haber optado poruña responsabilidad eminen
temente objetiva que solo exigía la culpabilidad entendida como principio de persona
lidad de las infracciones y de responsabilidad por el hecho (principio de causalidad) no
exigiendo el dolo o la culpa como requisito para aplicar la sanción23.
Conviene tom ar en cuenta que, aun cuando no contaba con reconocimiento expreso en
la normativa administrativa, el principio de culpabilidad fue reconocido a nivel jurispru
dencial por el Tribunal Constitucional como una exigencia para ejercer legítimamente la
potestad sancionadora. Así se puede advertir en la Sentencia del 3 de enero de 2003 re
caída en el Expediente 0010-2002-AI/TC, la cual en su fundamento 64 señala lo siguiente:
«El principio de culpabilidad es una garantía y al mismo tiempo un límite a la potestad punitiva del
Estado; por consiguiente, la aplicación del artículo 2 ° del Decreto Ley N ° 25475 queda supeditada a
que, al infringirse los bienes jurídicos seña lados por la norma penal, ello se haya realizado con inten
ción del agente. (...)»
En la misma línea, en la Sentencia del 24 de noviembre de 2004 recaída en el Expediente
2868-2004''AA/TC (fundamento 21), el Tribunal Constitucional reconoce expresamente
que las sanciones solo pueden sustentarse en la comprobación de la responsabilidad
subjetiva del agente infractor: «...es lícito que el Tribunal se pregunte si es que en un Estado cons
titucional de derecho es válido que una persona sea sancionada por un acto ilícito cuya realización
se imputa a un tercero. La respuesta no puede ser otra que la brindada en la STC 0010-2002-AI/TC:
un límite a la potestad sancionatoria del Estado está representado por el principio de culpabilidad.
23 Guía práctica sobre e! procedimiento administrativo sancionador. Ministerio de Justicia y Derechos Humanos. Junio
2017. p. 27.
