Tema 9: Responsabilidades adm inistrativas y penales
Desde este punto de vista, la sanción, penal o disciplinaria, solo puede sustentarse en la compro
bación de responsabilidad subjetiva del agente infractor de un bien jurídico. En ese sentido, no es
constitucionalmente aceptable que una persona sea sancionada por un acto o una omisión de un
deber jurídico que no lesea imputable. (...)»u
xi) Principio de Non Bis In Idem.- Por el principio del non bis in ídem, “no se podrán imponer suce
siva o simultáneamente una pena y una sanción administrativa por el mismo hecho en los casos en
que se aprecie la identidad del sujeto, hechoy fundamento. Dicha prohibición se extiende también a
las sanciones administrativas, salvo la concurrencia del supuesto de continuación de infracciones a
queserefi ere el inciso 7” (Inciso 11 del artículo 248o del TUO de la Ley 27444).
El principio non bis in Ídem es entendido en nuestro ordenamiento jurídico como una pro-
hibición de doble castigo por una misma acción que se considera antijurídica. El Tribunal
Constitucional peruano ha señalado que el non bis in Ídem es un principio que se encuen
tra implícito en el derecho al debido proceso previsto en el inciso 3 del artículo 139 de la
Constitución Política del Perú. El derecho a no ser juzgado o sancionado dos veces por los
mismos hechos se encuentra previsto también en el artículo 147 del Pacto Internacional
de Derechos Civiles y Políticos y el artículo 8.4 de la Convención Americana de Derechos
Humanos. Sentencia del 14 de abril de 2007 recaída en el Expediente Noi583-2007-PA/TC;
primer párrafo del fundamento jurídico 10.
