En los casos en los que no concurra esta triple identidad (bastando que no exista uno de estos
tres elementos analizados) sí corresponderá imponer una o más sanciones (pena o sanción
administrativa) por cada una de las conductas infractoras que se hayan configurado, salvo la
concurrencia del supuesto de continuación de infracciones27.
3. DELITOS COMETIDOS POR FUNCIONARIOS PÚBLICOS
Funcionario público o servidor público28: Se consideran funcionarios o servidores públicos:
i . Los que están comprendidos en la carrera administrativa.
z. Los que desempeñan cargos políticos o de confianza, incluso si emanan de elección po
pular.
3. Todo aquel que independientemente del régimen laboral en que se encuentre, mantiene
vínculo laboral o contractual de cualquier naturaleza con entidades u organismos del Es
tado y que en virtud de ello ejerce funciones en dichas entidades u organismos.
4. Los administradores y depositarios de caudales embargados o depositados porautoridad
competente, aunque pertenezcan a particulares.
5. Los miembros de las Fuerzas Armadasy Policía Nacional.
6 . Los demás indicados por la Constitución Políticay la ley.
7. Los funcionarios o servidores públicos extranjeros, comprende a cualquier persona con
vínculo de cualquier naturaleza con entidades u organismos de un Estado extranjero
(incluyendo empresas estatales), así como a quienes ejerzan funciones en organismos
internacionales, conforme a lo dispuesto en el art. 425-A del C.P.
3.1. Prevaricato
Descripción normativa.- El delito de prevaricato se encuentra tipificado en el artículo 418odel
Código Penal, cuyo tenor es el siguiente: “El Juez o el Fiscal que dicta resolución o emite dictamen,
manifiestamente contrarios al texto expresoy claro de la ley, o cita pruebas inexistentes o hechos falsos, o
se apoya en leyes supuestas o derogadas, será reprimido con pena privativa de la libertad no menor de tres
ni mayor de cinco años. Asimismo, el Juez o el Fiscal que, incumpliendo dolosamente sus deberes funcio
nales, ordena o dispone la libertad de una persona detenida en flagrancia parla Policía Nacional del Perú
o detenida por arresto ciudadano por la comisión de delitos cuya pena privativa de libertad es mayor de 05
años, será reprimido con pena privativa de libertad no menor de 08 ni mayor de 72 años".
27 Guía práctica sobre el procedimiento administrativo sancionador. Ministerio de justicia y Derechos Humanos, junio
2 0 17 . p. 3 1.
28 Artículo 425 C.R
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 195 of 1506 --

Tema 9: Responsabilidades adm inistrativas y penales
Cuestiones preliminares.- El delito de prevaricato es, una Infracción del funcionario de la ma
gistratura en contra del Estado. Pero además supone un agravio en contra de la sociedad. El Juez
está obligado a actuar según derecho en ejercicio de funciones que desempeña en nombrey por
encargo del Estado, y la ofensa cometida lesiona la dignidad con que está investido quien actúa
como magistrado encargado de asegurar el orden normativo del Estado, pero la falta que pudie
ra cometer en esta competencia al actuar como agente del Estado, además, tiene el carácter de
una contravención contra la tutela jurisdiccional que garantiza el Estado a la Sociedad.
Los alcances del agravio en relación con la garantía de la tutela jurisdiccional puede com
prender, en consecuencia, las diversas dimensiones que ella cubre tales como el acceso a la
jurisdicción, el derecho a que se dicte una sentencia motivada y sustentada en derecho, el
pronunciamiento sobre el fondo de la pretensión o del asunto legal cuestionado, el derecho
a los recursos legales, el derecho a la ejecución de lo juzgado, el derecho a la inamovilidad o
intangibilidad de los pronunciamientos judiciales.
En cuanto a los tipos de prevaricato, precisa que la doctrina reconoce «el prevaricato de dere-
choy el prevaricato de hechos. En el primer caso, se trata del juez o fiscal que a sabiendas, dicta
resolución o emite dictamen contrarios al texto expreso y claro de la ley o se apoya en leyes
supuestas o derogadas. En cuanto al prevaricato de hecho, debe entenderse que el juez o fiscal
invoca hechos falsos cuando ellos no existen exactamente, cuando no aparecen constando en
los autos que resuelve29».
Bien jurídico protegido
El bien jurídico protegido radica en la legalidad del cumplim iento de los actos funcionales
referidos a la función de los jueces y fiscales. En tanto que los magistrados pueden responder
por sus actos funcionales también en la vía civil o disciplinaria, lo que se castiga en la vía penal
son los incumplimientos más graves de los deberes jurisdiccionales.
El delito de prevaricato recae únicamente en resoluciones o decisiones que violen la normati-
vldad, constituyan un menoscabo grave a la imparcialidad y eficacia de la administración de
justicia y, consecuentemente, sean de alcance e interés jurídico importante en los derechos
subjetivos de los justiciables.
Para Sebastián Soler el delito de prevaricato tutela, si bien genéricamente la administración
de justicia, también la rectitud, la legalidad y la honestidad en el cumplim iento de los actos
en que consiste la actividad de administrar justicia.
Conducta típica
Tipicidad objetiva.- En principio, la acción delictiva es de carácter instantáneo y se concreta
en el acto jurisdiccional ordenado o dispuesto por la autoridad jurisdiccional. El acto jurisdic
cional agraviante puede realizarse por acción o por omisión. Este es un delito de resultado,
porque se configura como un acto jurisdiccional material en que se concreta la ilicitud. Es la
acción u omisión negligente o imperfecta la que ocasiona el resultado, pero en sí misma la
prevaricación, como con el delito de homicidio, es sancionada por el daño ocurrido contra el
bien jurídico protegido en el tipo delictivo.
29 REÁTEGUI SÁN CH EZ, james. Estudios de Derecho Penal. Parte especial. Lima.- jurista Editores, 2009, p. 542.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES 195

-- 196 of 1506 --

UBILEX
Siendo un delito de resultado, se valora la acción o la omisión en función de la lesión causada
en el bien jurídico. Por lo tanto lo que se sanciona es el daño efectivo cometido a través del acto
de prevaricación. Hay pena por la lesión específica o concreta contra el derecho a la tutela ju
risdiccional, el mismo que ocurre y es causado mediante el ejercicio inadecuado, negligente o
incompetente de la función jurisdiccional. El resultado es consecuencia de la acción u omisión
impropia en el cumplimiento defectuoso o imperfecto de la función jurisdiccional.
El delito de prevaricato puede consistir en una acción cuyo resultado efectivo se advierte en
cuatro distintos tipos de situaciones. La primera previsión es que la acción u omisión de un
juez o fiscal se configure como un acto consistente en resolución o dictamen manifiesta
mente contrario a una norma expresa. La segunda, es que el acto del juez o fiscal constituya
en la cita de una prueba inexistente. La tercera, que el acto del juez o fiscal sea una cita de
un hecho falso. La cuarta, es que la acción u omisión se refiera a la referencia invocada a una
ley supuesta o derogada.
En cualquiera de los cuatro supuestos de la acción, la conducta penada es la producción de un
resultado contrario al bien por cuya tutela es responsable el magistrado. Es una acción con
traria al deber que está obligado a cumplir un funcionario que, en nombre del Estado, tiene
la misión funcional de proteger jurisdiccionalmente cualquier bien jurídico sobre el que le co
rresponda pronunciarse. Y es, una acción que, siendo inherente al debery función elemental
del magistrado realizar conforme a derecho según corresponde a la naturaleza de la función
jurisdiccional, configuray consiste en una acción antijurídica. La acción del magistrado es una
acción contraria a derecho.
Las m o d a lid a d e s en la s q u e d ic h a a c c ió n se m a n if ie s t a se e n t ie n d e n to d a s r e fe rid a s a a cto s
d e c a r á c t e r ju r is d ic c io n a l, a c to s c u m p lid o s en e je r c ic io d e la f u n c ió n ju r is d ic c io n a l, d u r a n t e el
e je r c ic io d e la f u n c ió n ju r is d ic c io n a l, o c o n o c a s ió n d e l e je r c ic io d e la f u n c ió n ju r is d ic c io n a l,
s ie m p r e q u e e n c u a lq u ie r a d e d ic h o s c a s o s se a fe c te e n c u a lq u ie r f o r m a la p r o t e c c ió n o t u t e la
ju r is d ic c io n a l p o r la q u e so n r e s p o n s a b le s lo s m a g is t r a d o s a n t e la c o m u n id a d .
El artículo 418oCP distingue dos aspectos o situaciones. En una primera línea de cobertura, se
encuentran los actos que consisten en resoluciones o dictámenes manifiestamente contrarios
al texto expreso y claro de la ley; y en una segunda, de carácter más general, en la que los ac
tos no están relacionados con resultados relacionados a resoluciones dictadas o dictámenes
emitidos, sino con la simple producción de cualquier otro tipo de acto jurisdiccional en el que
citen pruebas inexistentes, hechos falsos, o se sustenten en leyes supuestas o derogadas.
Los alcances del tipo penal, por lo tanto, en cuanto a la acción sancionada, son más amplios
en el segundo grupo de actos. En el primero se prevé exclusivamente aquellos actos jurisdic
cionales que se concretan en una resolución judicial, o en un dictamen fiscal. En relación con
este tipo de productos jurisdiccionales se exige que el resultado consista en una resolución o
dictamen manifiestamente contrarios al texto expreso y claro de la ley. En todas las otras mo
dalidades de acción tipificadas la referencia no se extiende a las resoluciones o dictámenes,
y por lo tanto cubre cualquier otro tipo de acto que en el ejercicio de la función jurisdiccional
tuviera las características resaltadas y, por lo tanto, consista en cita de pruebas inexistentes,
hechos falsos, o se sustenten en leyes supuestas o derogadas.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 197 of 1506 --

Tema 9; Responsabilidades adm inistrativas y penales
Es importante reparar que, en cualquier caso, el delito de prevaricato, aun cuando no lo refiera
explícitamente el artículo 418 CP debe entenderse referido a la comisión u omisión de actos
jurisdiccionales contrarios a la ley. No lo son cualesquier otro tipo de acto que, en el ejercicio de
la función de un magistrado, no tenga el carácter de jurisdiccional. Lo que castiga el delito de
prevaricato no es cualquier acto de un funcionario responsable por la tutela jurisdiccional de
la colectividad, sino sólo aquellos actos en los que tal tutela se concrete. Por lo tanto, debiera
entenderse que quedan al margen de la cobertura del delito los actos normativos o adminis
trativos que no estén directamente vinculados ni que afecten el desempeño de la función juris
diccional. Todo otro acto, normativo o administrativo, mediante el cual se afecte directamente
el desempeño efectivo de la función jurisdiccional sí estaría incluido en el marco del tipo de
acción cubierta por el delito de prevaricato.
Una últim a cuestión es la relativa a la posibilidad de que el delito de prevaricato consista, se
gún el artículo 418o CR en una conducta omisiva. Según lo prevé el precepto de esta norma lo
que se sanciona es que se concrete el debido cumplim iento de la función jurisdiccional.
Esto es, la acción correcta, concreta y manifiesta, que se advierte y aparece tangiblemente en
el desempeño de la función en nombre y por cuenta del Estado. De la acción impropia o in
satisfactoria del magistrado en el ejercicio se infiere que se om itió cumplirla diligentemente.
Sin embargo, el delito de prevaricato no sanciona la omisión en general, sino la performance
defectuosa o insuficiente del deber del funcionarial en ejercicio de la función jurisdiccional.
Por esta razón, aunque no sea de fácil sustentación, es posible incurrir en delito de prevaricato
cuando se produce la omisión en el deber de invocar o aplicar la norma relevante o pertinente,
cuando esta existe pero no se registra su reconocimiento ni existencia en la resolución o dicta
men. De ahí que quepa pues la acción cuando se invocay aplica una norma que no rige o rige
impropiamente los supuestos de hecho. Pero, recíprocamente, cabe la omisión cuando se deja
de invocar o aplicar la norma idónea cuando ésta existey se la ignora o desconoce.
La inobservancia de la jurisprudencia, así sea vinculante, no constituye delito de Prevaricato
normativo, por cuanto no tiene la categoría de ley; y dicho delito se comete sólo cuando
la resolución judicial es contraria al texto expreso y claro de una ley. En todo caso, el apar
tam iento de la doctrina jurisprudencial o de un precedente vinculante, daría lugar a una
investigación de carácter disciplinario, mas no configura el delito de Prevaricato normativo.
Apelación N° 03-2016, Arequipa. Sala Penal Permanente de la Corte Suprema de la Repú
blica. Consid.14.
Tipicidadsubjetiva: El tipo penal de prevaricato es un delito especial propio, en el sentido que
requiere una especial cualificación en el sujeto activo (ha de ser Juez o Fiscal), se trata de cual
quier persona que integre en forma permanente (titular) o coyuntural el Poder Judicial o M i
nisterio Público; no se comete a título de culpa, lo que significa que no basta el descuido ni la
negligencia para que sea materia de imputación, sino que el tipo legal exige como condición
s''me qua non-, el dolo, entendiéndose este como el conocimiento y voluntad de la realización
de todos los elementos del tipo objetivo. Apelación N° 02-2014-Lambayeque. Consid.4. Sala
Penal Permanente de la Corte Suprema de la República.
