Modalidad agravada: Agregada a través de la Ley N° 32i82(Pub. 11.12.24), al respecto el Dr
Edwar García Navarro30 señala que: “1. Se trata de una modalidad agravada del prevaricato-en
cualquiera de sus modalidades: derecho, hecho y pruebas-, por lo que, para su configuración
típica, no basta simplemente en verificar la liberación si es que esta no es producto de una
decisión del juez o del fiscal (i) manifiestamente contrario al (ii) texto claro y expreso de la
Ley. Por ende, no se trata de cualquier liberación, sino de una realizada en torno a estos dos
requisitos típicos que, de hecho, en anteriores modificaciones al referido artículo, han venido
acomplejado su ti picidad. 2. Sobre el componente “incumplimiento sus deberes funcíonaria-
les”, aun si la intención fue siquiera darle al tipo penal una fachada de legitimidad, se pierde
porsu innecesaridad, puesto que, al serel prevaricato, un delito de infracción de deber propio,
es evidente que el sujeto activo ha de incumplir sus deberes funcionales, que, en el caso con
creto, se entenderá en el control procesal de ladetención porflagranciaoel arresto ciudadano.
Lo mismo podríamos decir de la inclusión “dolosamente”, cuando se sabe perfectamente su
implícita exigencia conforme al artículo 12 del Código Penal. El desconocimiento de la siste
matización de los tipos penales nos lleva a estos agregados redundantes. 3. Ahora bien, la in
clusión de la figura penal gravosa desequilibra los injustos de los prevaricatos por privación de
libertad. En el artículo 419 se tipifica la denominada “detención ilegal”, esto es, cuando el juez
maliciosamente o sin motivo legal, ordena la detención o no otorga la libertad. Este delito es
sancionado con pena privativa de libertad no menor de dos ni mayor de cuatro años. Frente a
ello, el segundo párrafo del artículo 418 se presenta como su contrapartida con una penalidad
que prácticamente la triplica. Entonces, nótese que el mensaje sobrecriminalizador del legis-
