Culpabilidad- En cuanto a este aspecto que incide sobre el conocimiento de la antijuridicidady
la exigencia del comportamiento requerido por el orden jurídico, se tiene que es más complicado
porque siendo Juez o Fiscal por su nivel de conocimiento la exigencia es mayor, salvo que haya ac
tuado bajo error de prohibición esto es creer que lo que ha realizado no constituye delito, con sus
modalidades invencibles que excluyen la responsabilidad penal o vencible que atenúa la pena.
Autoría y participación.- Sobre este aspecto se puede establecer autoría mediata si ha existido
detrás de una resolución un agente que haya planeado la emisión de la misma pero no participe
en ella por razones formales pero siendo este es un delito especial el sujeto activo debe ser Juez
o Fiscal. El autor inmediato es el firmante de la resolución. La intervención criminal podría darse
en un colegiado que se pone de acuerdo para em itir la resolución con visos de prevaricación sin
embargo quien tendría mayor responsabilidad en la comisión del ilícito sería el ponente pues es
quien presenta al colegiado el proyecto de resolución. En una sentencia serán responsables los
jueces que la firman y quedará exonerado quien haya emitido un voto particular31.
Tentativa y consumación.- La doctrina mayo ritan a considera que no hay tentativa en esta cla
se de delitos toda vez que se le considera como uno de peligro abstracto. Según Ezaine Chávez
es un delito de consumación instantánea con el dictado de la resolución o la emisión del dic
tamen y no es necesario que cause ejecutoria ni que sea revocada o anulada por otro juez, no
que haya causado algún resultado dañoso32.
3.2. Abuso de autoridad
Descripción normativa.- El delito de abuso de autoridad se encuentra tipificado y sancionado
en el artículo 376odel Código Penal de la siguiente manera: «El funcionario público que, abusando
de sus atribuciones, comete u ordena, en perjuicio de alguien, un acto arbitrario cualquiera, será reprimi
do con pena privativa de libertad no mayor de tres años.
Si los hechos derivan de un procedimiento de cobranza coactiva, la pena privativa de libertad será no
menor de dos ni mayor de cuatros años.»
El abuso de autoridad es asociado comúnmente al uso de un poder otorgado por la posesión
de un cargo o función, pero de tal forma que este uso no está dirigido a cumplir las funciones
atribuidas a ese cargo, sino a satisfacer intereses personales del individuo que lo ejerce.
Bien jurídico protegido.
El bien jurídico que se pretende tutelar es el correcto funcionamiento de la Administración Pú
blica, en consecuencia, esta norma obliga al funcionario público a realizar sus actos en función
a los dispositivos legales que fijan y delimitan sus funciones y marco de atribuciones.
«El delito de abuso de autoridad tiene como objeto jurídico de tutela penal el interés público,
en el sentido que las funciones de las que están investidos los funcionarios no sean utilizadas
