- Abuso de autoridad condicionando ilegal mente la entrega de bienes y servicios.-
El a rtíc u lo 3 7 6 °-A del C ó d ig o Penal re g u la otra m o d a lid a d de a b u so de a u to rid a d cu a n d o
la c o n d u c ta está o rie n ta d a , de fo rm a a rb itra ria , a la d is trib u c ió n de b ie n e s o la p restació n
de se rv icio s d e stin a d o para ap o yo so c ia l, de la s ig u ie n te m a n e ra :
“El que, valiéndose de su condición de funcionario o servidor público, condiciona la distribución de
bienes o la prestación de servicios correspondientes a programas públicos de apoyo o desarrollo so
cial, con la finalidad de obtener ventaja políticay/o electoral de cualquier tipo en favor propio o de
terceros, será reprimido con pena privativa de libertad no menor de tres ni mayor de seis años e inha
bilitación conforme a los incisos i y z del artículo 36odel Código Penal.”
C o m o se d e sp re n d e d e la d isp o sic ió n n o rm a tiv a , lo p e c u lia r de esta m o d a lid a d de ab u so
de a u to rid a d es q u e el fu n c io n a rio p ú b lic o tie n e c o m p e te n c ia en el á m b ito de p ro g ra
m a s p ú b lico s de a y u d a so c ia l, e stan d o d e n tro de su s fu n c io n e s la d is trib u c ió n de bienes
o p re sta ció n de se rv icio s; no o b stan te, el su je to in frin g ie n d o su s fu n c io n e s d e s tin a los
b ie n e s o se rv icio s a sectores e sp e cífic o s de la p o b la c ió n con la f in a lid a d de o b te n e r u na
v e n ta ja p o lític a (apoyo p o p u lar) y /o electo ral (cap tació n de votos) de c u a lq u ie r tip o en
favor p ro p io (e lecció n o reelecció n del cargo p ú b lico ) o de terceros (apoyo al líd e r d el par
tid o p o lítico , y a sea electo en e je rcicio de g o b ie rn o o c a n d id a to p o lítico ).
- Abuso de autoridad condicionado al otorgamiento de derechos sobre inmuebles.-
F in a lm e n te , el a rtíc u lo 3 76 °-B del C ó d ig o Penal tip ific a la m o d a lid a d de a b u so de a u to ri
d a d c u a n d o el fu n c io n a rio o se rv id o r p ú b lic o o to rg a ile g ítim a m e n te d e re ch o s so b re in
m u e b le s de d o m in io p ú b lic o o p rivad o
“El funcionario público que, en violación desús atribuciones u obligaciones, otorga ilegítimamente dere
chos de posesión o emite títulos de propiedad sobre bienes de dominio público o bienes de dominio privado
estatal, o bienes inmuebles de propiedad privada, sin cumplir con los requisitos establecidos porta norma-
tividad vigente, será reprimido con pena privativa de libertad, no menor de cuatro ni mayor de seis años.
Si el derecho de posesión o título de propiedad se otorga a personas que ilegalmente ocupan o usur
pan los bienes inmuebles referidos en el primer párrafo, la pena privativa de libertad será no menor
de cinco ni mayor de ocho años”.
Si se otorgan sobre bienes, zonas o áreas consideradas o declaradas como intangibles, inalienables o
imprescriptibles, alrededor del perímetro de los establecimientos penitenciarios, la pena privativa de
libertad será no menor de cinco ni mayor de ocho años.
La pena privativa de libertad será no menor de seis ni mayor de diez años, si se otorgan a personas
que ilegalmente ocupan o usurpan los bienes o zonas referidas en el tercer párrafo”
