1 .1 .1. C o h e c h o pasivo propio.-El a rtíc u lo 393° del C ó d ig o Penal tip ific a y s a n c io n a d d e lito
de co h e c h o p asivo p ro p io de la s ig u ie n te m a n e ra : "El funcionario o servidor público que
acepte o reciba donativo, promesa o cualquier otra ventaja o beneficio, para realizar u omitir
un acto en violación de sus obligaciones o el que las acepta a consecuencia de haber faltado a
ellas, será reprimido con pena privativa de libertad no menor de cinco ni mayor de ocho años e
inhabilitación conforme a los incisos! y 2 del artículo 36 del Código Penal y con ciento ochenta
a trescientos sesenta y cinco días-multa.
El funcionario o servidor público que solicita, directa o indirectamente, donativo, promesa o
cualquier otra ventaja o beneficio, para realizar u omitir un acto en violación de sus obligacio
nes o a consecuencia de haber faltado a ellas, será reprimido con pena privativa de libertad no
menor de seis ni mayor de ocho años e inhabilitación conforme a los incisos! y 2 del artículo 36
del Código Penal y con trescientos sesenta y cinco a setecientos treinta días-multa.
