blico en el marco de actividades económicas internacionales, a saber:
“Funcionario o servidor público extranjero45 que acepta, recibe o solicita, directa o indirec
tamente, donativo, promesa o cualquier otra ventaja o beneficio, para realizar u om itir un
acto en el ejercicio de sus funciones Oficiales, en violación de sus obligaciones, o las acepta
como consecuencia de haber faltado a el las, para obtener o retener un negocio u otra venta
ja indebida, en la realización de actividades económicas internacionales, será reprimido con
pena privativa de libertad no menor de cinco ni mayor de ocho años; inhabilitación, según
corresponda, conforme a los incisos i, 2 y 8 del artículo 36; y, con trescientos sesenta y cinco
a setecientos treinta días-multa.”
Cohecho pasivo propio en el ejercicio de la función policial o penitenciaria
Contenido en el artículo 395-A del Código Penal, que prescribe: "El miembro de la Policía
Nacional o del Sistema Penitenciario que acepta o recibe donativo, promesa o cualquier otra ventaja
o beneficio, para sí o para otro, para realizar u omitir un acto en violación de sus obligaciones deriva
das de la función policial o penitenciaria, o el que las acepta a consecuencia de haber faltado a ellas,
será sancionado con pena privativa de libertad no menor de seis ni mayor de doce años e inhabilita
ción conforme a los incisos 1 ,2_y 8 del artículo 36.
El miembro de la Policía Nacional o del Sistema Penitenciario que solicita, directa o indirectamente,
donativo, promesa o cualquier otra ventaja o beneficio, para realizar u omitir un acto en violación de
sus obligaciones derivadas de la función policial o penitenciaria, o a consecuencia de haber faltado a
ellas, será reprimido con pena privativa de libertad no menor de seis ni mayor de diez años e inhabi
litación conforme a los incisos1, z y 8 del artículo 36 del Código Penal.
El miembro de la Policía Nacional o del Sistema Penitenciario que condiciona su conducta funcional
a la entrega o promesa de donativo o cualquier otra ventaja o beneficio, será reprimido con pena
privativa de libertad no menor de ocho ni mayor de doce años e inhabilitación conforme a los incisos
i,2 y 8 del artículo 36 del Código Penal”,
En esta modalidad de cohecho pasivo propio el sujeto activo del delito debe ser una per
sona que tiene la condición o cualidad de miembro de la Policía Nacional o del Sistema
Penitenciario.
1.1.2. Cohecho pasivo impropio
El artículo 394° del Código Penal tipificay sanciona el delito de cohecho impropiode lasiguiente
manera: "El funcionario o servidor público que acepte o reciba donativo, promesa o cualquier otra ventaja
o beneficio indebido para realizar un acto propio de su cargo o empleo, sin faltar a su obligación, o como
consecuencia delya realizado, será reprimido con pena privativa de libertad no menor de cuatro ni mayor de
seis años e inhabilitación conforme a los incisos! y 2 del artículo 36 del Código Penaly con ciento ochenta a
trescientos sesentay cinco días-multa.
El funcionario o servidor público que solicita, directa o indirectamente, donativo, promesa o cualquier
otra ventaja indebida para realizar un acto propio de su cargo o empleo, sin faltara su obligación, o como
consecuencia del ya realizado, será reprimido con pena privativa de libertad no menor de cinco ni mayor
