Tema 9: Responsabilidades ad m inistrativas y penales
de ocho años e inhabilitación conforme a los incisos! y 2 del artículo 36 del Código Penaly con trescientos
sesenta y cinco a setecientos treinta días-multa.”
El delito de cohecho pasivo impropio tipificado en el artículo trescientos noventa y cuatro del
Código Penal, se configura, cuando el agente— funcionario o servidor público— solicita a
otro una promesa o cualquier otra ventaja indebida para practicar un acto propio de su cargo,
siendo por ello un delito especial, cuyo bien jurídico tutelado— en palabras del profesor Ma
nuel Abanto Vásquez— consiste en el correcto funcionamiento de la Administración Pública,
entendiéndose por solicitar, al “acto de pedir, pretender, requerir una entrega o promesa de
entrega ilícita, que hace el funcionario o servidor a alguien indeterminado con quien se ha
lla vinculado por un acto de oficio”, no siendo necesario para que se configure el delito que
el receptor del delito acceda o entregue lo solicitado, que como se ha dicho puede ser una
promesa, la misma que consiste en un donativo o ventaja que se hará efectiva en un futuro
determinado, haciéndolo con la finalidad de practicar un acto propio de su cargo y sin infrin
gir o menoscabar sus funciones, — a su vez, el profesor Fidel Rojas Vargas considera que “el
comportamiento activo de solicitar [implica que] el delito se consume con la petición (delito
de actividad) dirigida al sujeto que proveerá el donativo, la promesa o la ventaja”— , por lo
que, esta modalidad delictiva no admite la tentativa. R. N. 4130-2008, Ejecutoria Suprema del
29.01.2010.
Bien jurídico protegido
El bien jurídico que se busca proteger con la tipificación de este delito es la gratuidad o no
venalidad de la función pública46, dado que cuando se trata de un cohecho pasivo impropio
no se pone en peligro alguno el servicio público, pues el acto realizado o por realizar es lícito,
propio del cargo del funcionario.
«El bien jurídico genérico es el correcto,transparente ynorm a! funcionam ientodela adm inistran
ción pública. Mientras que respecto ai bien jurídico específico, en la: doctrina se rían planteado:
hasta tres posiciones:
1) Tutelar los deberes que nacen del cargo, función o atribuciones con la consiguiente fidelidad
hacia la administración pública a la que están obligados funcionarios y servidores públicos.
2) Tutelar el principio de imparcialidad en el desenvolvimiento de las funciones y servicios por
parte de los sujetos públicos, pues sus decisiones deben adoptarse sin interferencias.
3) Tutelar los actos de oficio de la compraventa de prestaciones efectuadas por particulares: u otros funcio
narios o servidores públicos.
Dé lo que se advierte, que las posiciones referidas resumen visiones distintas del bien jurídico específico que pre
tende tutelar el tipo penal. [Salinas Siccha, Ramiro. Delitos contra la Administración pública. Segundaiedición Limar
Grijley, 2077, p. 486], Considerando este colegiado que el bien jurídico específico tutelado en este tipo penal está
referido no solo a la tutela de los deberes que nacen del cargo o función, sino también a cautelar el principio de
imparcialidad en el cumplimiento de las funciones de los sujetos públicos».47
46 De La MATA BARRANCO, Norberto ]. Op. cit. pp. 92-95.
