Tipicidad subjetiva:
El tipo penal exige que la conducta del autor sea realizada con dolo, es decir, que el funcionario
o servidor publico haya actuado con conocimientoy voluntad de estar realizando la tipicidad
objetiva del delito.
«Todas las modalidades que recoge el tipo penal son de comisión netamente dolosa, no cabe
la posibilidad de ser cometido por negligencia o culpa del funcionario o servidor público. El
dolo supone que el funcionario o servidor público conozca su proceder indebido [y], sin em
bargo, voluntariamente procede. Solo es posible dolo directo, no es posible que alguna con
ducta de cohecho pasivo impropióse materialice por medio de dolo eventual. El agente desde
el primer momento sabey conoce que acepta o recibe la entrega de donativo, promesa o cual
quier otra ventaja o beneficio para realizar un acto al que está obligado a efectuar de acuerdo
con sus funcionesy atribuciones del cargo o empleo que desempeña al interior de laadm inis-
tración pública». Exp. 00086-2011-7, sentencia em itida p o r la Sala Penal de Apelaciones de la Corte
Superior de Lima el 18 de setiembre de 2012.
«El cohecho se encuentra dentro de los tipos dolosos porque existe el conocimiento y la vo
luntad necesarios para el pacto ilícito. Así tenemos que el elemento subjetivo que motiva al
funcionario es la oferta o promesa, en tanto que al corruptor le motiva la obtención de un be
neficio representado por la realización de un acto o por la abstención de otro». Exp. 05-2002,
sentencia emitida por la Sala Penal Especial de la Corte Suprema el 3 de junio de 2008.
Modalidad en función al sujeto activo:
Cohecho pasivo impropio en el ejercicio de la función policial y penitenciaria
Contenido en el artículo 395-B del Código Penal, que prescribe.- “El miembro de la Policía Na
cional o del Sistema Penitenciario que acepte o recibe donativo, promesa o cualquier otra ventaja o
beneficio indebido para realizar u o m itir un acto propio de su función, sin faltar a su obligación, o
como consecuencia del acto ya realizado u omitido, será reprimido con pena privativa de la libertad
