no menor de cuatro ni mayor de siete años e inhabilitación conforme a los incisosi, z y 8 del artículo
36. El miembro de la Policía Nacional o del Sistema Penitenciario que solicita, directa o indirecta
mente, donativo, promesa o cualquier otra ventaja indebida para realizar u o m itir un acto propio
de su función, sin fa lta ra su obligación, o como consecuencia del acto ya realizado u omitido, será
reprimido con pena privativa de libertad no menor de cinco ni mayor de ocho años e inhabilitación
conforme a los incisos1, z y 8 del artículo 36.”
1=1.3. Cohecho pasivo específico
El artículo 395o del Código Penal agrava la pena privativa de libertad del delito de cohecho
pasivo cuando la conducta sea realizada por un Magistrado, Árbitro, Fiscal, Perito, Miembro
de Tribunal Adm inistrativo o cualquier otro análogo a los anteriores acepte o solicite dona
tivo, promesa o cualquier otra ventaja o beneficio, a sabiendas que es hecho con la finalidad
de influir o decidir en asunto sometido a su conocimiento. Estamos frente a un tipo penal
de cohecho pasivo propio de carácter específico, de rancio abolengo decimonónico, anacróni
co y casuístico, a saber: "El Magistrado, Árbitro, Fiscal, Perito, Miembro de Tribunal A dm inistrativo o
cualquier otro análogo a los anteriores que bajo cualquier modalidad acepte o reciba donativo, promesa
o cualquier otra ventaja o beneficio, a sabiendas que es hecho con el fin de in flu ir o decidir en asunto so
metido a su conocimiento o competencia, será reprimido con pena privativa de libertad no menor de seis
ni mayor de quince años e inhabilitación conforme a los incisos 1y 2 del artículo 36 del Código Penal y con
ciento ochenta a trescientos sesenta y cinco días-multa.
El Magistrado, Árbitro, Fiscal, Perito, Miembro de Tribunal Adm inistrativo o cualquier otro análogo a
los anteriores que bajo cualquier modalidad solicite, directa o indirectamente, donativo, promesa o cual
quier otra ventaja o beneficio, con el fin de in flu ir en la decisión de un asunto que esté sometido a su co
nocimiento, será reprimido con pena privativa de libertad no menor de ocho ni mayor de quince años e
inhabilitación conforme a los incisos 7y 2 del artículo 36 del Código Penaly con trescientos sesenta y cinco
a setecientos días-multa.”
El tipo penal contiene un elemento subjetivo distinto del dolo, expresado en el término “a sa
biendas”. Esto es, que el sujeto actúa con plenitud de conocimiento de las pretensiones im
plícitas en las medidas corruptoras y, pese a ello, solicita o recibe. Esto es obviamente un caso
de doble venalidad del sujeto activo, pues lesiona el deber de probidad funcional y puede no
acceder a la pretensión al momento de resolver50.
1.1.4. Corrupción pasiva de auxiliares jurisdiccionales
El artículo 396o del Código Penal sanciona las conductas pasivas de cohecho cuando el autor
tenga la calidad de secretario judicial, relator, especialista, auxiliar jurisdiccional o cualquier
otro análogo a los anteriores, a saber: “Si en el caso del artículo 39 5, el agente es secretario judicial,
relator, especialista, auxiliar jurisdiccional o cualquier otro análogo a los anteriores, será reprimido con
pena privativa de libertad no menor de cinco ni mayor de ocho años e inhabilitación conforme a los incisos
ly z d e l artículo 36 del Código Penaly con ciento ochenta a trescientos sesenta y cinco días-multa.”
50 ROJAS VARGAS, Fidel; Op. dt., pp. 362-365.
210 BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y N O M B R AM IEN TO DE JUECES Y FISCALES

-- 211 of 1506 --

Tema 9: Responsabilidades adm inistrativas y penales
La penalidad disminuida se explica por la naturaleza menor del injusto penal, para la valora
ción político-penal peruana, cuando el hecho es cometido por un colaborador jurisdiccional
del juez. El menoro inexistente poderde decisión desecretariosy auxiliares no lesionael bien
jurídico protegido en la magnitud que sí hacen los actos de los funcionarios contemplados en
el artículo 395o del Código Penal51.
1.2. Cohecho activo
1.2.1. Cohecho activo genérico
Descripción normativa.- El artículo 397° del Código Penal tip ifica y sanciona la modalidad bá
sica del cohecho activo de la siguiente manera: ‘‘El que, bajo cualquier modalidad, ofrece, da o pro
mete a un funcionario o servidor público donativo, promesa, ventaja o benefcio para que realice u omita
actos en violación de sus obligaciones, será reprimido con pena privativa de libertad no menor de cuatro
ni mayor de seis años-jnhabilitación, según corresponda, conforme a los incisos 1,2 y 8 del artículo 36; y,
con trescientos sesenta y cinco a setecientos treinta días-multa.
El que, bajo cualquier modalidad, ofrece, da o promete donativo, ventaja o beneficio para que el funcio
nario o servidor público realice u omita actos propios del cargo o empleo, sin faltara su obligación, será
reprimido con pena privativa de libertad no menor de tres ni mayor de cinco años-jnhabilitación, según
corresponda, conforme a los incisos 1, z y 8 del artículo 36; y, con trescientos sesenta y cinco a setecientos
treinta días-multa.”
Bien jurídico protegido.- La identificación del bien jurídico protegido en el delito de cohecho
activo dependerá de la modalidad delictiva que cometa el autor52:
a) Si el autor entrega la ventaja a un funcionario para que realice u omita un acto en viola
ción de sus obligaciones el bien jurídico protegido será la “imparcialidad” en la función
pública.
b) Si el autor entrega la ventaja a un funcionario para que realice un acto propio de su cargo,
el bien jurídico protegido será la “gratuidad” o no “venalidad” de la función pública.
Debe tenerse presente que, en esta figura delictiva, se protegen los bienes jurídicos antes
mencionados solo frente a conductas de peligro, pues sobre el particular no pesa la obligación
de resolver con i m parcial idad o sin abuso del cargo. El cohecho activo es un delito que pone en
peligro la “imparcialidad” o el "ejercicio no abusivo del cargo público", porque favorece que el
funcionario público que recibe la “coima” o soborno atente directamente contra ellos.
Conducta típica.-
