i Responsabilidades adm inistrativas y penales
provechooen el deotra persona, para que dicho servidor o funcionario público realice uom ita
actos propios de su cargo o empleo, en violación de sus obligaciones o sin faltar a su obligación
para obtener o retener un negocio u otra ventaja indebida en la realización de actividades
económicas o comerciales internacionales. Con la nueva redacción de este artículo, este delito
se convierte en un delito especial ya que: i) el sujeto activo podrá ser cometido por personas
naturales que tengan nacionalidad peruana o que ejerzan la representación de una persona
jurídica domiciliada en el Perú; 2) el destinatario del soborno podrá ser cualquier funcionario
o servidor público extranjero. Así tenemos: “El que, teniendo la nacionalidad peruana ola represen
tación de una persona jurídica domiciliada en el Perú, bajo cualquier modalidad, ofrezca, otorgue o pro
meta directa o indirectamente a un funcionario o servidor público extranjero donativo, promesa, ventaja
0 beneficio indebido que redunde en su propio provecho o en el de otra persona, para que dicho servidor o
funcionario público realice u omita actos propios de su cargo o empleo, en violación de sus obligaciones o
sin fa lta r a su obligación para obtener o retener un negocio u otra ventaja indebida en la realización de
actividades económicas o comerciales internacionales, será reprimido con pena privativa de la libertad no
menorde cinco años ni mayor de ocho años; inhabilitación, según corresponda, conforme a los incisos1, z y
8 del artículo 36;y, con trescientos sesentay cinco a setecientos treinta días-multa”.
1 =2.2= Cohecho activo específico
El artículo 398odel Código Penal sanciona: “El que, bajo cualquier modalidad, ofrece, da o promete do
nativo, ventaja o beneficio a un Magistrado, Fiscal, Perito, Árbitro, Miembro de Tribunal adm inistrativo o
análogo con el objeto de influir en la decisión de un asunto sometido a su conocimiento o competencia, será
reprimido con pena privativa de libertad no menorde cinco ni mayor de ocho añosfmhabilitación, según co
rresponda, conforme a los incisos 1, z y 8 del artículo 36;y, con trescientos sesentay cinco a setecientos treinta
días-multa. Cuando el donativo, promesa, ventaja o beneficio se ofrece o entrega a un secretario, relator,
especialista, auxiliar jurisdiccional, testigo, traductor o intérprete o análogo, la pena privativa de libertad
será no menorde cuatro ni mayor de ocho añosfmhabilitación, según corresponda, conforme a los incisos1,
2 ,3 y 4 d e l artículo 36;y, con trescientos sesentay cinco a setecientos treinta días-multa.
Si el que ofrece, da o corrompe es abogado o forma parte de un estudio de abogados, la pena privativa de
libertad será no menorde cinco ni mayor de ocho añosfmhabilitación, según corresponda, conforme a los
incisos 2 ,3 ,4 y 8 del artículo 3 6 ;y, con trescientos sesentay cinco a setecientos treinta días-m ulta.”
Se admiten dos modalidades de cohecho activo en relación a la calidad del agente que se bus
ca corromper, tenemos:
Modalidad simple.- El sujeto activo es cualquier particularque busca que el magistrado di rec-
cione su decisión sobre un asunto sometido a su conocimiento o competencia funcionarial,
pudiendo presentarse los siguientes supuestos i) que el objetivo buscado por el sobornante
sea lograr decisiones a su favor conforme a derecho ii) que sea para obtener una decisión a
su favor contrariando el derecho y ¡ii) que el funcionario realice un acto procesal con espe
cial prontitud o incluso antes del plazo legal iv) que el agente público realice un acto pro
cesal mucho después del plazo legal v) que el funcionario no realice u omita hacer un acto
funcional y vi) que el efecto buscado sea simplemente buscar resultados perjudiciales a la
otra parte conforme o contra derecho, iv) (Rojas Vargas, 2016, p.338).
BALOTARIO DESARROLLADO PARA LOS EXAMENES ESCRITOS DE SELECCION
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 214 of 1506 --

UBILEX
«Los comportamientos típicos que configuran las modalidades de cohecho activo especí
fico son: ofrece, da, promete o corrompe a un Magistrado, Fiscal, Perito, Árbitro, Miembro
de Tribunal Administrativo o análogo; o a un secretario, relator, especialista auxiliar, tes
tigo, traductor o intérprete o análogo, con donativos promesas, ventaja o beneficio. El ob
jetivo de dichas acciones típicas es influir en la decisión de un asunto sometido a conoci
miento o competencia del sujeto público. El verbo “ofrece” define una acción de propuesta
u ofertamiento [sic] unilateral que en el caso del cohecho activo específico parte de un
sujeto indeterminado [...] hacia el sujeto pasivo especificado con el objeto de influir en su
decisión. Así, la acción del sujeto activo se vincula con la conducta de tales sujetos pasi
vos, que en un ámbito de perfecta bilateralidad acepta el medio corruptor en el contexto
de la finalidad planteada por el agente [...] En el acto de ofrecerse pone de manifiesto un
compromiso de dación o entregao de prestación que asume el sujeto indeterminado, sin
que ello suponga que efectivamente se entrega o concede medio corruptor al sujeto pú
blico o a un tercero según la indicación de dicho sujeto, o que este se vea forzado a cumplir
o incumplir sus actos funcionales o de servicio [...]. Con el verbo “da” se define un acto de
entrega material, por parte del sujeto activo, y otra de recepción, por el sujeto público, lo
cual es indicativo de que nos encontramos ante un delito de resultado, en el que no basta
el ofrecimiento, es más, no es el ofrecimiento elemento típico de esta modalidad, vista
ex post podría considerarse que entregas fallidas hagan radicar en el ofrecimiento o los
intentos de entrega, fases de tentativa. Es bueno tom ar en cuenta que pese a tratarse de
acciones alternativas en determinados casos pueden concurrir tanto una acción de en
trega como una de ofrecimiento, como cuando el donativo que el agente “da" es parte de
los que debe todavía completar más adelante; o bien se entrega un donativo en dinero,
bienes muebles o inmuebles y se pacta en dicho acto (de entrega) o con antelación una
ventaja futura consistente, por ejemplo, en ascensos laborales. Aunque el subtipo bajo
análisis no prevé la modalidad “promete”, siendo abierta la posibilidad de configurarse,
conviene analizarla. Así, a diferencia de las acciones anteriores es un comportamiento di
rigido a futuro en cuanto a la concreción del donativo o ventaja. Tal acción supone el pac
to o acuerdo establecido entre los sujetos concurrentes en la acción típica [...] de entrega
o concesión futura del donativo o ventaja respectivamente y de la recepción, es decir, del
negociamiento [sic] que hacen los agentes del acto de función o empleo, al igual que en
las anteriores modalidades. La promesa puede jugar aquí el papel de una suerte de condi
cionamiento colocado a la entrega del donativo o la concesión de la ventaja-beneficio [...]
Las tres acciones desvaloradas penalmente en el contexto del cohecho activo (ofrecer, dar
o prometer) son de fronteras abiertas, al emplear la norma penal la frase complementaria
“bajo cualquier modalidad”, es decir, directa o indirectamente; en este últim o caso bajo
estándares de suficiente inequivocidad [sic] y direccionamiento de la conducta típica, de
modo escrito u oralmente. Cuando el subtipo analizado utiliza el verbo corrompe, lo que
está haciendo es generalizar una conducta de manera inadecuada, pues igual corrompe
el abogado o un tercero cuan do "ofrece” que cuando “da” el medio corruptor al funcionario
o servidor público [Rojas Vargas, Fidel. Delitos contra la Administración pública. Cuarta
edición. Lima: Grijley, 2007, pp. 741-742 y 523]». Exp. 37-2006, sentencia emitida por la
Primera Sala Penal Especial de la Corte Superior de Justicia de Lima el 11 de febrero de
2010.
