Tema 9: Responsabilidades adm inistrativas y penales
M odalidad agravada,- Respecto a esta conducta típica, el tipo penal impone un estatus
especial sobre el sujeto activo, es decir, el agente delictual deberá tener el estatus profe
sional de abogado o sin serlo ocurre que forma parte de un estudio de abogados que ló
gicamente patrocina o tiene un asunto pendiente de decisión con el funcionario público
a quien se pretende corromper, esta agravante convierte al cohecho activo en un delito
especial propio ante la condición especial que se requiere identificar.
El delito es doloso. El sujeto activo dirige su comportamiento a un objetivo determinado.
El dolo requerido es el dolo directo para el sujeto indeterminado. En el caso del compor
tamiento de los sujetos especiales resulta suficiente el dolo eventual. Así, en el caso del
abogado, por tratarse de un sujeto activo especial, bastará verificar que actuó con dolo
eventual. Exp. 37-2006, sentencia emitida por la Primera Sala Penal Especial de la Corte
Superior de Justicia de Lima el 11 de febrero de 2010.
4. NEGOCIACIÓN INCOMPATIBLE 0 APROVECHAMIENTO INDEBIDO DE CARGO
Descripción normativa.- El delito de negociación incompatible se encuentra tipificado y san
cionado en el artículo 399odel Código Penal de lasiguiente manera: “El funcionario o servidor pú
blico que indebidamente en forma directa o indirecta o por acto simulado se interesa, en provecho propio
o de tercero, por cualquier contrato u operación en que interviene por razón de su cargo, será reprimido
con pena privativa de libertad no menor de cuatro ni mayor de seis años e inhabilitación conforme a los
incisos! y 2 del artículo 36 del Código Penal y con ciento ochenta a trescientos sesenta y cinco días-m ulta”.
El delito de negociación incompatible o aprovechamiento indebido de cargo tiene como verbo
rector del tipo penal el término interesar, que significa''atañer1,''concern ir1,''incumbir'',''comprome
ter'' o ‘importar algo1y, por ello, se destina nuestra voluntad a conseguirlo u obtenerlo; es decir,
este importar o interesares en un contrato u operaciones que realizad Estado con terceros con
la finalidad de obtener un provecho económico indebido en su‘favor o a favor de otros".
El interesarse indebidamente debe entenderse como un desdoblamiento en el actuar del
agente del delito de negociación incompatible, pues, dentro del contexto del contrato u ope
ración en el que interviene, el agente actúa como funcionario representante de la administra
ción pública; pero, a la vez, representa intereses particulares, con los cuales pretende sacar un
provecho personal o a favor de tercero, y es precisamente este últim o lo que denota el carácter
económico de su accionary que implica una probable afectación del patrimonio de la adm i
nistración pública.
Bien Jurídico protegido.- El bien jurídico que se busca proteger mediante la tipificación de la
conducta antes señalada es el correcto funcionamiento de la Administración Pública frente
al interés privado de sus agentes; es decir, los funcionarios o servidores públicos que pueden
anteponersus intereses al de la administración.
En los delitos contra la administración pública, se busca una protección funcional de la mis
ma, no como objeto en sí, sino coma organización que debe cumplir fines trascendentes de
servicio públicoy resolución de problemas colectivos. En el caso del tipo penal de negociación
incompatible se parte del hecho que, en efecto, como primera línea de protección se encuen
tra la funcionalidad de la administración pública, cuya eficiencia y eficacia se ve vulnerada por
