Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 216 of 1506 --

UBILEX
la actuación irregular del funcionario o servidor público que se interesa en el procedimiento
en curso, pero ello en modo alguno significa que el objeto jurídico específico de protección sea
el patrimonio del Estado RN 677-70 i 5, Lime], Sala P enal Perm anente de la C orte Suprem a de la
República 17.05.20 ¡7 4 £ qsq P u ro m d iv s )
Conducta típica
Tipicidad objetiva.- El delito de negociación incompatible, previsto en el artículo 399 del Códi
go Penal, es una modalidad de corrupción, por lo mismo la conducta del agente debe poseer
esa orientación y no una simple irregularidad o anomalía administrativa; debiendo para ello
cum plircon las exigencias del tipo penal, los cuales pasamos a detallar:
a) intervenir por razón del cargo: la vinculación funcional, es decir, el funcionario o servidor
público posee facultades o competencia para intervenir, en contratos u operaciones por
razón de su cargo, puesto o empleo en la administración pública, ello supone que:
i) es inherente al ámbito de su competencia ser parte en el contrato u operación;
i i) es el llamado a intervenir por ley, reglamento o mandato legítimo;
b) indebidamente interesarse directa o indirectamente o por acto simulado, en provecho
propio o de tercero, el interesarse indebidamente es volcar sobre el negocio de que se
trate una pretensión de parte no administrativa: querer que ese negocio asuma una de
terminada configuración en interés particular del sujeto o hacer mediar en él, propug
nándolos, intereses particulares o de terceros, admitiendo tres modalidades de comisión
directa (implica que el sujeto activo personalmente pone de manifiesto sus pretensiones
particulares, en cualquier momento de la negociación^, indirecta (es hacerlo, en el contra
to u operación a través de otras personas) o por acto simulado (es realizarlo aparentando
que se trata de intereses de la administración pública cuando en realidad son particula
res o personales); Así lo reitera el RN. N°264i-20ii-Lambayeque(FJ. 3): “las modalidades de
comisión de este ilícito pueden ser-, i)Directamente, cuando el sujeto activo personalmente pone de
manifiesto sus pretensiones particulares indebidas al participar como funcionario en un contrato u
otra operación estatal; ii) Indirectamente, cuando el agente se interesa en el contrato u operación
a través de otras personas que pueden ser particulares u otros funcionarios o servidores públicos;
y,iii) Por acto simulado, en este supuesto los contratos u operaciones se realizan con empresas que
simulan tener una titu la rid a d o representatividad distintas cuando realmente son de propiedad del
agente o están vinculadas a éste; es decir, se aparenta un accionaren concordancia con los intereses
de la administración pública cuando en realidad se están haciendo prevalecer de manera oculta in
tereses privados o particulares."
c) el objeto del interés del funcionario o servidor público: el contrato u operación, dada la
naturaleza de los actos que interviene, el interés ilícito del funcionario o servidor público
reviste naturaleza económica, mientras que los contratos u operaciones en los que in
terviene el funcionario o servidor a nombre del Estado pueden ser de naturaleza diversa
(económica, cultural, servicios, etc.); y,
d) requiere el dolo directo, lo cual se aprecia con mayor énfasis en las hipótesis de interven
ción simulada, donde el sujeto activo despliega actos de astucia o engaño a la administra
ción pública.
6 BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 217 of 1506 --

Tema 9: Responsabilidades adm inistrativas y penales
Con respecto al elemento típico del interés la CAS. N° 841-2015- Ayacucho señala-, "Trigésimo
cuarto-. El delito de negociación incompatible presenta dos elementos típicos-. A. El interés indebido sobre
un contrato u operación que debe estar a cargo del funcionario público. Este elemento típico sintetiza la
tipicidad objetiva. B. Debe existir un interés de obtener un provecho propio o para un tercero. Este ele
mento típico pertenece a la tipicidad subjetiva y se constituye como un elemento subjetivo de trascen
dencia interna. Trigésimo quinto.- Con relación al prim er elemento típico, el elemento central es el interés.
Es posible que existan dos tipos de intereses que puede tener el funcionario: uno debido y uno indebido.
En el prim er caso, el funcionario exterioriza su deseo de un cabal cumplimiento de sus funciones en el
segmento del poder que se encuentra administrando, por lo que su idea es en todo momento beneficiara
la administración pública.
El segundo tipo de Interés es el que forma parte de la conducta incriminada: el interés inde
bido. Por interés indebido se entiende a aquella situación en que el funcionario tiene un interés que no
es el procurar un beneficio para la administración pública, por el contrario, este deberes dejado de lado
expresamente por él. A l tratarse de un delito de corrupcióny entenderse al delito de negociación incom
patible en el marco de los delitos de corrupción de funcionarios, resulta claro que el deber quebrantado
es la adecuada gestión del patrim onio estatal. El funcionario se encuentra en un conflicto de intereses al
actuar, por un lado, tiene el deber de procurar el beneficio de la institución a la que pertenece y por otro el
m axim izarel interés (propio o de un tercero). La vía a través de la cual este interés indebido se manifiesta
es de forma directa, indirecta o a través de un acto simulado. El objeto sobre el cual ha de recaer el interés
indebido es el contrato u operación en la que interviene por razón de su cargo. Trigésimo sexto-. El segundo
elemento es la búsqueda de un provecho propio o de un tercero como consecuencia del quebrantamiento
del deber institucional; además del dolo, para tener por acreditada la conducta típica, de presentarse este
elemento subjetivo. Ésta es la motivación por la cual el funcionario se interesa en el contrato. Al respecto,
como ya señalamos, no es necesario que el tercero sea quien se beneficie de la contratación, dado que el
tipo penal adm ite la posibilidad (por su redacción abierta) de que un tercero que no sea el contratante,
pueda ser el beneficiado.
El provecho implica el beneficio que va a recibir el funcionario público (cuando es para sí), el tercero, o
ambos, como consecuencia de la celebración del contrato o de la operación a cargo del funcionario.”
El término interés indebido, se debe entender como todo acto dirigido a anteponer el interés
propio o de un tercero a los que se patrocina en nombre del Estado en un contrato o negocio, pro
moviendo así un beneficio irregular para sí mismo o para un tercero. En consecuencia, cuando
un funcionario o servidor público, por razón de su cargo, participa en una contratación o negocio
a nombre del Estado, tiene la obligación de desempeñarse en dicho procedimiento en forma
diligente e imparcial. Si lo que busca el agente activo con su intervención irregulares beneficiarse
a sí mismo o a un tercero, defrauda la confianza que se le ha conferido; tal actitud y conducta
merece ser sancionado penalmente al ¡ncurriren el delito de negociación incompatible.Cas. 18-
2 0 iy ju n ín . Sala Penal Transitoria de la Corte Suprema de la República. 24.07.2019.
Tipicidad subjetiva: el delito de negociación incompatible es netamente doloso, por tanto, no
cabe la comisión por culpa. La configuración subjetiva de la conducta ilícita requiere o exige
que el funcionario o servidor público actúe con conocimiento de que tiene el deber de lealtad
y probidad de celebrar contratos o real izar operaciones en representación, y a favor del Estado;
no obstante, voluntariamente actúa evidenciando interés particular con el firm e objetivo de
