Autoría y participación.- El tipo penal de negociación incom patible-delito de comisión exclu
sivamente doloso- en principio admite participación, la cual para ser considerada tal -confor
me nuestro ordenamiento jurídico- es necesariamente de carácter doloso. Es decir, los inter-
vinientes considerados como cómplices del delito, deberán haber actuado con conocimiento
de que se estaba anteponiendo los intereses particulares al de la administración pública en
beneficio propio o de un tercero. El concepto de dolo que se considera a efectos de demostrar
la Imputación subjetiva -sea del autor o cómplice- es uno de carácter normativo; es decir, la
prueba buscará determinarsi el sujeto, según el rol que ocupaba en el contexto concreto, tenía
o no conocimiento de que la acción que realizaba era constitutiva de un delito, si contribuía o
no a la comisión de un ¡lícito.
5. TRÁFICO DE INFLUENCIAS
Descripción normativa.- El delito de tráfico de influencias se encuentra tipificado y sancionado
en el artículo 400odel Código Penal de la siguiente m a n e r a El que, invocando oteniendo influencias
reales osimuladas, recibe, hace dar o prometer para sí o para un tercero, donativo o promesa o cualquier otra
ventaja o beneficio con el ofrecimiento de interceder ante un funcionario o servidor público que ha de cono
cer, esté conociendo o haya conocido un caso judicial o administrativo, será reprimido con pena privativa de
libertad no menor de cuatro ni mayor de seis añosfmhabilitación, según corresponda, conforme a los incisos
2,3, 4 y 8 del artículo 36;y con ciento ochenta a trescientos sesenta y cinco días-multa.
Si el agente es un funcionarlo o servidor público, será reprimido con pena privativa de libertad no menor
de cuatro ni mayor de ocho años; inhabilitación,según corresponda, conforme a los incisos 1, 2 y 8 del
artículo 36; y, con trescientos sesenta y cinco a setecientos treinta días-m ulta.”
En la descripción legal citada se advierte una agravante especial en el segundo párrafo que
convierte este delito en uno de infracción al deber funcional.
El delito de tráfico de influencias, resulta ser un atentado, aunque lejano contra la imparciali
dad del funcionarioy el carácter público de la función (Abanto Vásquez), el prestigioy el regular
funcionamiento de la Administración Pública, específicamente la administración de justicia ju
risdiccional o administrativa (Rojas Vargas), nos encontramos ante un delito de peligro, donde la
influencia sobre el funcionario público no tiene que darse necesariamente para la consumación
