Sujetos del delito.- «El citado delito, previstoy sancionado por el artículo cuatrocientos del Código Pe
nal, tiene como elementos típicos (a) al traficante de influencias— que Incluso, como en el presente caso,
es un funcionario público— [sujeto activo]; (b) al Estado, en tanto los comportamientos descritos en el
tipo legal tienen que ver con el funcionamiento de la Administración Pública, con la necesidad de que esta
goce de confianza de los administrados para desarrollar normalmente y con transparencia sus activida
des en aras de la afirmación de la garantía constitucional de igualdad [sujeto pasivo]; (c) la invocación de
influencias del sujeto activo en cuanto se tiene capacidad para demandar ayuda a un funcionario público,
entendida como la capacidad — posibilidad de orientar la conducta ajena en una dirección determina
da [medio delictivo]; (d) el ofrecimiento de in flu ir en funcionarios que han conocido o están conociendo
un caso judicial o administrativo, esto es, realización sucesiva o simultánea de actos de intercesión o de
intermediación, [prestación del agente];y, (e) la obtención de beneficios, sean patrimoniales o no p a tri
moniales [H urtado Pozo, José, «interpretacióny aplicación del artículo cuatrocientos del Código Penal del
Perú: delito llamado de Tráfico de Influencias». En Anuario de Derecho Penal «interpretación y Aplicación
de la Ley Penal». Lima: Fondo Editorial de la Pontificia Universidad Católica del Perú y Universidad de
Friburgo, 2006, pp. 268-289]». Exp. AV-06-2006, sentencia emitida por la Sala Penal Especial
de la Corte Suprema de Justicia el 21 de mayo de 2007.-
Bien Jurídico protegido.- "El [tráfico de influencias] constituye una figura autónoma, prote
giendo como bien jurídico específico la imparcialidad u objetividad en el ejercicio de la fun
ción pública, si bien se admite siguiendo posiciones de la doctrina que se constituye en un
adelanto de la barrera de protección penal [...]” Exp. 023-2001, Sala Penal Especial de la Corte
Superior de Justicia de Lima. 10.11.2004.
“El delito de tráfico de influencias es un delito que afecta la imparcialidad funcionarialy el ca
rácter público de la función, de suerte que cuando se trata de “influencia real» el sujeto pasivo
es tanto el funcionario en quien se va a ejercer influencia cuanto la Administración Pública. Es
un tipo penal instantáneo, de simple actividad, de resultado corto y de tendencia. Exige una
conducta precisa, con independencia de que la misma forme parte o no de un plan delictivo
que lleva a la constatación de una empresa crim inal”. Cas. 683-2018, Nacional. Sala Penal Per
manente de la Corte Suprema de la República. 17.07.2019.
Conducta típica.-
Tipicidad objetiva:
a) Invocar influencias reales o simuladas: La influencia es la capacidad-posibilidad de orientar la
conducta ajena en una dirección determinada, utilizando ascendientes de distinto origen y
naturaleza sobre el influenciado. En tal sentido, invocar influencias es, en una interpretación
