(© «El delito de tráfico de influencias exige que el sujeto activo invoque influencias reales o simuladas - n o se
requiere el ejercicio efectivo de la influe ncias- [,.J».R. N, 2218-2005, Ejecutoria Suprema del JOde abril de 2006.
b) Ofrecimiento de interceder ante funcionario o servidor público que ha de conocer, esté
conociendo o haya conocido un caso judicial o administrativo: La finalidad de invoca
ción de influencias hecha al interesado se expresa en la propuesta lanzada por el sujeto
activo del delito de interceder o intermediar directamente (actuar o pedir a nombre del
interesado) ante funcionario o servidor público que ha de conocer, esté conociendo o haya
conocido un caso judicial o administrativo. Interceder es intervenir a favor del interesado,
actuar por él, es brindarle una válvula de aparente o probable inicio de solución a sus ur
gencias en vía administrativa o jurisdiccional, obviamente en un contexto de ilegalidad,
en tanto no es esa la formalidad ni la materialidad que plantea el derecho. El funcionario
o servidor sobre quien el traficante de influencias va a interceder tiene que tratarse nece
sariamente de un funcionario o servidor que tenga bajo su competencia el conocimiento
o procesamiento de un caso judicial (en sentido lato, para incluir incluso a los casos del
fuero m ilitar) o administrativo. Quedan, pues, fuera del tipo los funcionarios o servidores
que carezcan de facultades jurisdiccionales en sentido amplio (no referido sólo a jueces,
sino también a fiscales), así como en general todos aquellos otros funcionarios o servi
dores públicos. El momento de la intercesión ofrecida puede referirse a cualquier etapa del
proceso, no necesariamente sólo el período del fallo (caso judicial o administrativo en
trámite); o a un período posterior (caso judicial o administrativo que haya conocido el
funcionario o servidor público), también ha previsto un adelantamiento de la oportuni
dad de la comisión del delito cuando introduce la frase «ha de conocer», lo cual admite en-
tendery abarcar cursos probabi lísticos considerados en el sentido de la norma penal, esto
es cuando el funcionarlo o servidor público aún no tiene el caso judicial o administrativo
bajo su conocimiento o esfera concreta de ámbito funcional.
