«El tipo penal requiere la concurrencia de diversos actos ejecutivos a) invocación de influen
cias; elemento que alude a lo que iradidonalm enie se conoce corno "venta de humo" y con
el cual se inicia la conducta típica; b) Ofrecimiento ele interceder, a favor del interesado:ante,
funcionario o servidor público que esté conociendo o haya conocido un caso judieial o admh
nistrativo; se trata de un acto intermedio de parte del traficante de influencias, que permite el
pacto entre este y el interesado, cj Recibir, dar o prometer donativo, promesa o cualquier ven-:
taja por parte del interesado; o hacerse dar o prometer donativo, promesa o cualquier ventaja
por parte del traficante. La presencia de estos verbos rectores cierra la iipicidad de la figura legal que se anali
za. Ellos expresan el pacto —entre el traficante que oferta sus influencias y el interesado que procura un bene
ficio inmediato o mediato de índole procesal o procedimenial. El delito se ha consumado al haberse producido
la entrega del donativo, la promesa de donativo o cualquier otra ventaja para que el traficante interceda por
este último a nivel de influencias ante los funcionarlos señalados por la norma penal. El provecho económico
percibido o hecho prometer por el sujeto activo del delito puede ser para el mismo o de un terceroE sp. 00172-
2011, sentencia emitida por la Sala Pena! de Apelaciones de fa Corle Superior ríe Jmtieia de Urna el 25 de abdi ds 2013.
c) Recibir, hacer dar o prometer para sí o un tercero, donativo promesa o cualquier ventaja
o beneficio: La presencia de estos verbos rectores cierra la tipicidad de la figura legal de
tráfico de influencias. Ellos expresan que el pacto-entre el traficante que oferta sus reales
o simuladas Influencias y el interesado que procura un beneficio inmediato o mediato
de índole procesal o procedlmental- ha llegado a su fase ejecutiva final: es decir, el delito
se ha consumado al haberse producido la entrega del donativo, la promesa de donativo
o cualquier otra ventaja (el precio que el interesado tiene que pagar) para que el trafi
cante interceda por éste últim o a nivel de influencias ante los funcionarios señalados en
la norma penal. A la oferta lanzada con la invocación de Influencias y el ofrecimiento de
Interceder por parte del traficante le sucede la contraprestaclón económica o patrimonial
en sentido amplio o con mayor extensión cualquier ventaja, que otorga el Interesado.
Como se observará, la norma penal ha hecho uso de mecanismos que son propios de los
delitos de corrupción (donativos, ventajas), lo cual está denotando la naturaleza del ¡líci
to penal como un delito de corrupción, donde el provecho o beneficio tiene connotación
económlcay estrecha vinculación con el donativo, pero se extiendey abre hacia formas no
necesariamente patrimoniales en las ventajas (o como señala la norma penal «cualquier ven
taja»). En el caso del tráfico de influencias mediante promesa, la norma penal está aludien
do a la posibilidad de provecho económico a través de la concreción futura del donativo. La
redacción legal de la figura en estudio no incluye como un componente material típico que
el traficante de influencias haya llevado a la práctica el ofrecimiento, o que se haya consegui
do el propósito buscado con la Intercesión. Ocurra o no, el delito ya se ha consumado.
El provecho económico percibido o hecho prometer por el sujeto activo del delito puede
ser para él mismo o para un tercero. El término «tercero» es de significado amplio, abier
to (familiares, amigos, allegados, otros funcionarios o servidores, etc.), al tratarse de un
delito contra la administración pública, la norma jurídica no ha enfatizado el contenido
cuantitativo del donativo, la promesa de donativo o la ventaja, por lo mismo la recepción
o entrega de donativo de mínima o gran significancia será por Igual suficiente para con
figurar delito. No obstante, queda a criterio del juez la estimación del caso a efectos de
determinar la pena con base a criterios de proporcionalidad, tomando en cuenta también
la cantidad del monto pecuniario o la sign¡ficativldad de la ventaja.
