sentencia emitida per eí Segundo Juzgado Unipersonal de Urna ai 22 de marzo de 2013,
í f j «[...] es necesario precisar que la conducta típica exigida al agente, en el delito de tráfico de influencias, es la
de recibir, hacer dar o prometer para sí o para otro (por parte del interesado en el ejercicio de la influencia a su
favor) donativo o promesa o cualquier otra ventaja. El tipo no exige en forma alguna que el agente o "traficante
de humo" (como se le denomina en doctrina) entregue o prometa beneficio alguno al funcionario influenciado,
incluso el tipo penal, ni siquiera exige que la influencia o el vínculo entre el traficante de humo y el funcionario
público exista, ante lo cual, mal puede exigirse que el funcionario haya participado en la entrega de dinero
que alega el procesado, a fin de constituir el ilícito atribuido al procesado«. R, N. 2214-2004, Ejecutoria Suprema
emitida eí 27 de enero de 2005.
(3.) «En todo caso, la promesa o ventaja a la que hace referencia el artículo cuatrocientos del Código Penal,
es decir el pacto entre el comprador y el vendedor de influencias, sobre la dación de una ventaja, dádiva o
promesa de ofrecimiento, no debe presumirse ni inferirse [...] En el delito de Tráfico de Influencias debe mediar
un nexo causal entre la invocación de la influencia por parte del intermediario y la entrega de la contrapres
tación (dádiva, donación, o ventaja) por parte del interesado. Es decir que lo que motiva al interesado a dar la
contraprestación al vendedor de influencias es justamente la invocación que de estas el traficante efectuó".
Exp. 017-2001 sentencia emitida por la Sala Penal Especial "8" de la Corle Superior Justicia de Lima al 9 de julio da 2003.
Tipicidad subjetiva: El tráfico de influencias es un delito inminentemente doloso, siendo el
caso que se exige el conocimiento y voluntad del autor al momento de realizar los elementos
de tipicidad objetiva.
Agravante en razón a la calidad especial: el delito de tráfico de influencias puede ser come
tido por cualquier persona, no exigiendo calidad especial alguna en el autor, solo se quiere
que pueda invocar o tenga influencias reales o simuladas para interceder ante un funcionario
público que haya conocido, conozca o hade conocer un caso judicial o administrativo. No obs
tante, el segundo párrafo del artículo 400o del Código Penal sanciona con una pena agravada
cuando el traficante de influencia tenga la calidad de funcionario público, debido al mayor
menoscabo que se produce contra el correcto funcionamiento de la Administración Público
(Probidad en el ejercicio del cargo público).
«[Salinas Siccha, Ramiro. Delitos contra la Administración pública. Lima: Grijley, 2009, p. 567] En
el delito de Tráfico de Influencias, el sujeto activo es indeterminado, es decir, puede ser cualquier
persona, no obstante, si el sujeto activo tiene posición de garante respecto de la Administración
de Justicia, al ser un Magistrado del Poder Judicial, esto constituye una circunstancia agravante
