[..] Si ei agente tiene la condición de funcionario o servidor público al momento de desarrollar la conducta
punible, aparece la agravante tipificada en el último párrafo del articulo 400 del Código Penal. En tal sentido, a
efectos de materializarse la agravante no es necesario que el agente esté en pleno ejercicio de sus funciones
encomendadas al interior de la administración pública [...] el tipo penal solo exige verificar que ei sujeto público,
traficante al momento de cometer el delito, tenga la condición de funcionario o servidor público-, Exp. ÚG4G5-
2011, sentencia emitida por a! Ssguntlo Juzgado Unipersonal ds Lima d 22 de marzo de 2013.
Autoría y participación: «el tráfico de influencias es un tipo penal común de intervención ne
cesaria al tratarse de un delito de encuentro, porque constata la concurrencia de sujetos: el
traficante, el interesado y otros intervinientes de ser el caso. Si bien existen posiciones a favory
en contra de la punibilidad de los títulos de participación— instigadory cómplices— , el Cole
giado considera que tal intervención es posible y corresponderá establecer en cada caso con
creto los límites de la responsabilidad penal. [...] La intervención del interesado en el caso que
nos ocupa se sustenta en la teoría de la intervención delictiva (injusto de intervención). Tanto
el autor como el partícipe acceden al tipo penal de la parte especial por el aporte al hecho
principal común y la vinculación al injusto, ello conforme al “principio de accesoriedad”, toda
vez que los dispositivos 23, 2 4 y 25 del Código Penal se refieren a la intervención en el “hecho
punible”. Principio que se compatibiliza con el de “autorresponsabilidad", según el cual cada
persona es responsable penalmente por su propia conducta, ya que no se puede im putara un
sujeto lo que hace responsable a otra persona. Interpretación que a criterio del Colegiado no
infringe el principio de legalidad. [...] Por otro lado, el cómplice no solo requiere la aceptación
de la invocación de la influencia real y del ofrecimiento de interceder por parte del traficante,
sino la compra de los mismos mediante la promesa de donativo. El aporte no solo se mide por
la contribución fáctica del cómplice primario (contenido en reuniones, acuerdos, suministro
de información, llamadas telefónicas, correos electrónicos, audios y videos, etc.) que constituye
un referente o una pauta de valoración, sino también, en un sentido jurídico-normativo, como
quebrantar las expectativas inherentes al rol o comportamiento (imparcialidady objetividad) del
funcionario que tiene conocimiento del caso administrativo a través de un traficante ante determi
nado organismo del Estado». Exp. 00193-2012, sentencia emitida porta Sala Penal de Apelaciones
de la Corte Suprema el 18 de julio de 2013.
Tentativa y consumación: el tráfico de influencias es un delito de encuentro porque exige de
la intervención de dos o más sujetos. Por un lado, el agente que ofrece influencias y, por otro,
el que las compra. Sin embargo, este últim o no responderá como autor, sino como cómplice o
instigador. Este delito se consuma cuando se realiza el acuerdo de intercesión, esto es cuando
el comprador de influencias o interesado acepta el ofrecimiento de influencias del traficante
a cambio de dar un beneficio de cualquier índole. No se requiere que el traficante interceda
efectivamente ante el funcionario público competente para el caso, basta solo con el acuerdo
entre vendedory comprador de influencias.
