6 . R É G IM E N D E S A N C IO N E S P E N A L E S
El artículo 28o del Código Penal establece las siguientes clases de pena, a saber:
"Artículo 28 - Las penas aplicables de conformidad con este Código son:
- Privativa de libertad;
- Restrictivas de libertad;
- Limitativas de derechos; y
Multa."
6.1. Pena privativa de libertad
Consiste en el internamiento del responsable penal en un centro penitenciarlo para que cum
pla con la sanción impuesta por el Juez en la sentencia condenatoria. El artículo 29o del Códi
go Penal establece que la pena de privación de libertad puede ser temporal de una duración
mínima de dos díasy máxima de trein tay cinco años; o, indefinida, llamada también cadena
perpetua.
Por otro lado conforme al artículo 29-AC.P, el condenado podrá acceder a la pena de vigilancia
electrónica personal en caso: I) se le haya Impuesto una sentencia condenatoria no menor de
cuatro ni mayor de diez años de pena privativa de libertad, ii) hayan sido condenadas y que
hayan sido beneficiadas con algún beneficio penitenciario, conversión de pena en ejecución
o cualquier otra medida de liberación anticipada como mecanismo de monitoreo,y iii) de de
litos culposos previstos en el Código Penal con pena no menor de cuatro años. El cómputo de
aplicación por día será igual a un día de privación de libertad y se ejecutará en el dom icilio o
lugar que señale, a partir del cual se determinará su radio de acción, itinerario de desplaza
miento y tránsito. El condenado estará sujeto a vigilancia electrónica personal para cuyo cum
plimiento el juez fijará las reglas de conducta que prevé la ley, así como todas aquellas reglas
que considere necesarias a fin de asegurar la Idoneidad del mecanismo de control.
Para Imponer la pena de vigilancia electrónica personal, el Juez debe valorar las condiciones,
previamente acreditadas, de vida personal, laboral, fam iliar o social, de la persona condenada
con un Informe psicológico y social elaborado por el Consejo Técnico del INPE. Es importante
resaltar que la norma señala que hay prioridad cuando se presentan algunas circunstancias:
a) Los mayores de 65 años.
b) Los que sufran de enfermedad grave, acreditada con pericia médico legal.
c) Los que adolezcan de discapacidad física permanente que afecte sensiblemente su capacidad de des
plazamiento.
