No procede imponer la pena de vigilancia electrónica personal para: i) personas condenadas
por delito doloso, siempre que sean consideradas como reincidentes o habituales, ii) aquellos
cuyo internamiento sea consecuencia de la revocatoria previa de la pena de vigilancia electró
nica personal, iii) aquellos cuyo internamiento sea consecuencia de la revocatoria de alguna
pena alternativa a la privativa de libertad, iv) aquellas personas procesadas o condenadas por
los delitos de organización criminal, terrorismo y lavado de activos, d) aquellos cuyo interna
miento sea consecuencia de la revocatoria de un beneficio penitenciario o conversión de penas
en ejecución de condena, salvo si esta fuera por el delito Omisión de prestación alimentaria.
6.2. Pena restrictiva de la libertad
El artículo 30o del Código Penal define la pena restrictiva de libertad como aquella sanción de
expulsión del país aplicable a los extranjeros luego de haber cumplido la pena privativa de
libertad por la comisión de un delito o la concesión de un beneficio penitenciario que acortada
la sanción, quedando prohibido su reingreso al país.
Finalmente, la disposición normativa establece que en el caso de expulsión por concesión de
beneficios penitenciarios, el Perú mantiene jurisdicción exclusiva sobre la condena impuesta.
6.3. Penas limitativas de derechos
En términos generales, las penas limitativas de derechos consisten la suspensión en el ejerci
cio de determinados derechos, obligaciones de hacer o la realización de trabajos a favor de la
comunidad. El artículo 31o del Código Penal establece las clases de penas limitativas de dere
chos, a saber:
"1, Prestación de servicios a la comunidad;
2. Limitación de días libres; e
3. Inhabilitación/’
Las penas limitativas de derechos previstas en los dos primeros incisos del artículo 31ose aplican
como autónomas cuando están específicamente señaladas para cada delito y también como
sustitutivas o alternativas de la pena privativa de libertad, cuando la sanción sustituida a criterio
del Juez no sea superior a 05 años. La duración de las penas de prestación deservicios a la comu
nidad y limitativa de días libres se fijará, cuando se apliquen como sustitutivas de la pena priva
tiva de libertad, de acuerdo con las equivalencias establecidas en el artículo 52odel Código Penal.
Prestación de servicios a la comunidad: Esta pena obliga al condenado a trabajos gratuitos
en entidades asistenciales, hospitalarias, escuelas, orfanatos, otras instituciones similares u
obras, ya sean públicos o privados. Los servicios son asignados, en lo posible, conforme a las
aptitudes del condenado, debiendo cumplirse en jornadas de diez horas semanales, entre los
