bajo habitual.
El condenado puede ser autorizado para presta restos servicios en los días hábiles semanales, com
putándose la jornada correspondiente. Esta pena se extiende de diez a ciento cincuenta y seis jor
nadas de servicios semanales, salvo disposición distinta de la ley.
Limitación de días libres: Esta pena obliga al condenado a permanecer los días sábados, do
mingos y feriados, hasta por un máximo de diez horas semanales, a disposición de una insti
tución pública o privada para participar en programas educativos, psicológicos, de formación
laboral, cultural o social.
Esta pena se extiende de diez a ciento cincuentay seis jornadas de limitación semanales, salvo
disposición distinta de la ley. Durante este tiempo, el condenado recibe orientacionesy realiza
actividades adecuadas e idóneas para su rehabilitación y formación.
Inhabilitación: La pena de inhabilitación puede ser impuesta porel juez como principal o ac
cesoria, produciendo las medidas establecidas en el artículo 36odel Código Penal, a saber:
