En caso que la inhabilitación sea principal, la misma se extenderá de seis meses a diez años,
salvo los supuestos de incapacidad definitiva a que se refieren los numerales 6 , 7 y 9 del artícu
lo 36 y los supuestos del artículo 426 del Código Penal; en el artículo 4-A del Decreto Ley 25475
yen los artículos 1,2,3 y 4 del Decreto Legislativo 1106. Por otro lado, la inhabilitación accesoria
se Impondrá cuando el hecho punible cometido por el condenado constituya un abuso de
autoridad, de cargo, de profesión, oficio, poder o violación de un deber Inherente a la fundón
pública, comercio, Industria, patria potestad, tutela, cúratela, o actividad regulada por ley; y se
extiende por igual tiempo que la pena principal.
Finalmente, la pena de inhabilitación referida a la suspensión, cancelación o incapacidad de
finitiva para obtener autorización para conducir cualquier tipo de vehículo se podrá aplicar
como pena accesoria en los delitos culposos de tránsito.
6.4. Multa
El artículo 40odel Código Penal define la multa como aquella pena que obliga al condenado a
pagar al Estado una suma pecuniaria fijada en días-multa, cuyo Importe equivale a su ingreso
diario y se determina atendiendo a su masa patrimonial (rentas, remuneraciones, nivel de
gasto y demás signos exteriores de riqueza).
La pena de multa se extenderá de diez a trescientos sesentay cinco día-multas, salvo disposición
distinta de la Ley, siendo el importe de cada día-multa un valorascendente entre el veinticinco al
cincuenta por ciento del ingreso diario del condenado cuando viva exclusivamente de su trabajo.
La multa fijada en la sentencia deberá ser pagada dentro de los diez días posteriores a dicha
diligencia; sin embargo, a pedido del condenando y de acuerdo a las circunstancias, el Juez
podrá perm itir que el pago se efectúe en cuotas mensuales. El cobro de la m ulta se podrá
efectuar mediante el descuento de la remuneración del condenado cuando se aplica aisla
damente o cuando se aplica acumulativamente con pena lim itativa de derechos o fuere con
cedida la suspensión condicional de la pena. El descuento no debe incidir sobre los recursos
indispensables para eísustento del condenadoy su familia.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 228 of 1506 --

S. LA TEORÍA DEL CASO
1. im portancia
Podemos decir, de plano, que la teoría del caso no es más que la labor de subsumir los hechos
(teoría fáctica) dentro de la norma legal aplicable a los mismos (teoría jurídica) conforme a
los elementos de convicción recopilados (teoría probatoria), de modo que permitan construir
una historia con significado penal relevante.
Naturalmente, la teoría del caso no solo se utilizada para construiry sustentar una responsa
bilidad penal, sino también para perseguir una absolución.
Si se llega a una coincidencia importante o significativa de los elementos necesarios para sus
tentar una condena o una absolución se puede decir que se tiene una teoría del caso.
Entonces, la teoría del caso se convierte en la postulación que cada parte presenta al órgano
jurisdiccional para que la asuma como una verdad jurídica, y será el juez quien, finalmente,
admita una y solo una teoría del caso, la cual plasmarán en su decisión final.
2. La teoría del caso
Desde nuestra perspectiva, la teoría del caso se constituye en una herramienta metodológica
que permite la conjunción de las hipótesis fáctica, jurídica y probatoria que manejan el fiscal y
el defensor respecto de un caso concreto.
Los hechos que cada parte han reconstruido mediante la prueba obtenida son subsumidos o
encuadrados de las normas penales aplicables a cada caso concreto, de modo que puedan ser
sustentados ante el juez y le permitan tom ar una decisión.
Siendo así, la teoría del caso está compuesta por tres niveles de análisis fundamentales: la
teoría de los hechos o teoría fáctica, la teoría jurídica o teoría del derecho aplicable al casoy la
base probatoria o teoría probatoria.
La relación que existe entre estos tres elementos de la teoría del caso es de continuidad: de
primera mano deben apreciarse y ubicarse los hechos (teoría fáctica) que tienen relevancia
penal; en segundo lugar, estos hechos se encuadran dentro de las normas penales aplicables
(teoría jurídica y labor de subsunción); finalmente, contrastamos esos hechos con los elemen
tos de prueba o simplemente la prueba (teoría probatoria) que se ha obtenido; así, cada ele
mento, típico de la historia será demostrado por otro elemento de convicción.
La teoría del caso no se vislumbra, construye o comienza a desarrollar en el momento de la
audiencia del juicio o de la etapa intermedia (control de acusación), sino desde la misma in
vestigación preliminar.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 229 of 1506 --

Tema 10: Litigación ora''
Efectivamente, desde el primer momento en que el fiscal o la defensa reciben la noticia crim i
nal, ambos están en posición (y obligación) de iniciar lo que será el borrador de su teoría del
caso.
Las pruebas que vayan acopiando irán perfilando esa idea, hasta hacerla tomar cuerpo de hi
pótesis; entonces, deberán ir añadiendo y desechando elementos de tal forma que, cuando
llegue al juicio, el litigante deberá haber acopiado todos los elementos probatorios que de
mostrarán su hipótesis fáctica y jurídica, los cuales serán muy importantes en la preparación
del caso.
3. Teoría de! caso y subsunción
Ya se ha dicho que, en suma, la teoría del caso no es más que una labor de subsunción, de
encuadre; cada norma jurídico penal expone una hipótesis fáctica; esa previsión de hechos
contiene elementos puntuales, circunstancias que exige, de tal forma que el fiscal o el abo
gado defensor deben sustentar sus hechos (su historia) en una norma penal (ley, o artículo
del Código Penal) y, con los elementos de convicción obtenidos, actuados o realizados, se de
muestre una u otra. Así, podemos afirmar que:
Los hechos que se sostienen pero que no son subsumibles dentro de una norma penal, no
constituyen un caso penal sino una historia, puray simple.
Los hechos subsumibles dentro del tipo penal, pero sin prueba, conllevan a que se tenga
una buena historia delictiva, pero no demostrable.
Y, si los hechos son subsumibles dentro del tipo y además se cuenta una buena prueba
suficiente que los respalden, se concluye en que se tienen un caso.
4. La teoría fáctica
La teoría fáctica se materializa en la reconstrucción de los hechos que el fiscal o el abogado
llegan a conocer; es la formación de una historia, de un suceso histórico determinado, ya sea
que le son narrados por los interesados o involucrados (la víctima al fiscal, y el imputado al
abogado defensor), por la noticia criminal o por el acopio de entrevistas y documentación pro
batoria.
Por ello, la Investigación es la que debe agotar la búsqueda de elementos probatorios (ele
mentos de convicción) de cargo o de descargo, los cuales sustentarán la hipótesis del litigante
(fiscal o abogado defensor).
Con cada elemento de convicción (con cada prueba) se debe form ar una historia, en la cual
se conjuguen hechos, personajes, acciones, instrumentos u objetos con los que se realizan,
circunstancias de tiempo, m odoy lugar; todo en una secuencia cronológica, para su cabal en-
tendlm lentoy corroboración.
Cada hecho (que forma parte de la historia que pretenden sustentar el fiscal o la defensa) se
presentará siempre por partes, a veces sin ningún tipo de orden; las narraciones de los pri
meros testigos, agraviados o imputados, serán ambiguas, oscuras, con lagunas, inconclusas,
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES 2

-- 230 of 1506 --

UBILEX
desordenadasy hasta no creíbles, a veces; cada litigante debe lograr una historia creíbley de
mostrable, con secuencias históricas lógicas.
En el caso del acusador (fiscal), buscará demostrar que existe una acción prevista en un tipo
penal, corroborando los diversos requisitos del delito mediante la historia que el ofendido, la
evidencia física o los testigos le van narrando.
La defensa, por su parte, debe buscar en la historia del adversario cuáles piezas faltan, cuya
ausencia hace inverosímil o imposible el hecho, o lo hacen cierto, pero no logran poner a su
defendido en la escenay desarrollando la acción ilícita.
5. Aplicación de la teoría del caso
El fiscal, al construir su teoría del caso, para posteriormente presentarla y sustentarla, deberá
saber de antemano qué prueba necesitará (teoría probatoria); deberá estudiar y conocer los
requisitos técnicos del tipo penal o del delito específico que va a imputar o de las normas que
va a utilizar (teoría jurídica) a la hora de presentar su historia (teoría fáctica), a fin de que el
juez o tribunal capte que se le está presentando una relación de hechos ilícitos atribuibles a
una o varias personas, debidamente concatenados y probados (teoría del caso).
Para presentar el caso ante el juez o jurado, el litigante debe proveerse de:
Una posición firme sobre la teoría del caso, lo que supone la conjunción de la teoría fácti
ca y teoría jurídica;
Un caudal probatorio (elementos de convicción) acopiado en la fase de investigación que
sostenga la posición asumida, lo que se resume en la teoría probatoria;
Un interrogatorio y contrainterrogatorio eficientes, debidamente planificados y previsi
bles, que se realizarán en la audiencia de juicio oral;
Una conclusión o argumentación final que concatena o asocia todos los elementos ante
riores y los presenta organizadamente como una historia verosímil y debidamente proba
da en cada extremo pertinente.
6. La teoría del caso y la prueba
Construida la teoría del delito, el paso siguiente es organizar la prueba de tal forma que la
soportey sea suficiente al momento en que se presente.
Para ello, la evidencia se puede organizar por clases:
6.1. Evidencia personal o testimonial
Son los testigos y peritos; conlleva al interrogatorio directo para los testigos y peritos ofrecidos
por la parte, y contrainterrogatorio para los testigos y peritos ofrecidos por parte la contraria.
6.2. Evidencia documental
Se materializaen los documentos, entendidos como cualquiersuperficiequesoporte un men
saje comunicante: fotografías, planos, pictografías, fórmulas comerciales (cheques, facturas,
letras), fórmulas legales (escrituras públicas, testimonios de escritura pública).
BALOTARIO DESARROLLADO PARA LOS EXAMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 231 of 1506 --

Tema 10: Litigación oral
6.3. Evidencia real
Entendiendo que la palabra “real” proviene del latín res, que significa “cosa”, se constituye en la
evidencia compuesta por cosas, o sea, por objetos: cuchillos, armas, lesión visible en el cuerpo.
Por su fuerza demostrativa, la evidencia se puede clasificaren dos tipos, según:
6.3.1. Evidencia directa
Tiene por función establecer la existencia del hecho en forma inmediata, como ocurre cuando
se actúa la prueba testimonial, que está dada por el testigo que vio la realización de la acción
típica matar, falsificar, librar el cheque sin fondos, el desapoderamiento, la usurpación.
6.3.2. Evidencia indirecta o circunstancial
En materia de evidencia real, está dada por el rastro de sangre; en materia de evidencia de
mostrativa, está dada por la fotografía del vehículo donde consta el hundimiento de la puerta
cuyo testigo indica que fue a causa de las patadas del ofensor. En materia de evidencia testi
monial, sería el caso del testigo que oyó un grito, volvió a very pudo constatar que el ofendido
estaba herido en el sueloy había varios sujetos, de los cuales uno tenía un cuchillo en la mano.
Esta evidencia es indirecta porque el testigo no presenció la acción típica sino su momento
inmediato posterior.
Los principios que rigen el orden de presentación de testigos:
Principio de orden cronológico.
Principio de primacíay novedad.
Principio de testimonio más creíble.
Principio del testigo más creíble.
Principio de adecuación al tipo de tribunal.
7. Sinopsis de la teoría del caso
¿Para qué sirve la teoría del caso?
Es el medio ideal para:
Dirigir la investigación.
Planificar, direccionary ejecutar la práctica de pruebas en el juicio.
Tener un concepto claro de la importancia de cada prueba.
Eliminar la prueba superfluae innecesaria.
Determinar la forma en que se realizan los interrogatorios.
Preparar los contrainterrogatorios en el juicio.
Preparar los alegatos.
Características de la teoría del caso
Tiene que ser lógica.
Tiene que ser creíble.
