II. EL INTERROGATORIO
El interrogatorio tiene la finalidad de obtener el máximo de información de un testigo y pro
bar, con ese testimonio, nuestra teoría del caso.
1. Finalidad del interrogatorio
Comencemos por una premisa fundamental: la principal oportunidad que tiene un litigante
para NARRARy PROBAR su historia, permitiéndole al juez o al tribunal revivir la versión de los
hechos de su teoría del caso, es el examen directo, o también llamado interrogatorio.
El interrogatorio o examen directo es, entonces, la actividad de extraer del testigo la informa
ción que requerimos para CONSTRUIR la historia o el trozo de historia que éste nos puede
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 233 of 1506 --

: Litigación oral
proporcionar; es la etapa en que elaboramos la mayor parte de nuestra versión de los hechos,
nuestra teoría del caso.
El examen directo nos permite RELATAR NUESTRA TEORÍA DEL CASO desde la PRUEBA CON
CRETA y no desde las puras afirmaciones del litigante (como, por ejemplo, en los alegatos de
apertura), que hasta el momento han sido sólo una promesa.
2. Objetivos del interrogatorio
Los 4 principales objetivos que el litigante debe satisfacer con la realización de un examen
directo son:
