4. Características de un interrogador efectivo
MOTIVADO
Busca que los hechos le queden claros al juez.
ALERTA
Está atento a las respuestas que proporciona el interrogado
PACIENTE
Espera calmadamente la información que quiere obtener
TIENE TACTO
Realiza preguntas y logra obtener información evitando incomodar o afectar la integridad del interrogado.
En suma, el ¡nterrogador debe demostrar que su testigo sí es una persona de confianza; asi
mismo, debe tener un conocimiento integral de la información o el tema que exponen sus
órganos de prueba; debe controlar al testigoy saberterminaroportunamente.
5. Fases del interrogatorio directo
• Introducir al testigo (generales, ocupación, etc.).
• justificar su presencia en la audiencia (si es perito sobre qué emitió dictamen; si es el
policía que realizó la detención cóm oy cuándo sucedió ésta; si vio los hechos porqué los
vio).
• Permitir que el testigo cuente la historia.
• Utilizar preguntas abiertas: ¿Qué?, ¿Cómo?,¿Cuándo?, ¿Dónde?,¿Por qué?, ¿Qué hizo des
pués?
• Utilizar preguntas temáticas: ¿Nos puede hablar del trabajo que usted desempeña?
• Utilizar preguntas de transición que son las que nos llevan a hablar de otro tema. Ejem
plo: Vamos a hablar ahora de lo que sucedió el día- Preguntas cerradas: ¿Nos puede decir
cuánto recibió de propina ese día?
