Tema 10: Litigación oral
• Demostrar nuestra teoría del caso: Qué necesito que el testigo pruebe.
• El interrogatorio tiene que ir relacionado con la exposición inicial.
• Organización y secuencia de ideas.
• Utilizar material visual: ¿Conoce usted ese lugar?¿Reconoce este lugar?
• Evitar el uso de muletillas: no útil ¡zar "gracias”, “está bien”.
• Saber term inar el interrogatorio.
6. Problemas en un interrogatorio directo
• Que el interrogado sea olvidadizo.
• No siga secuencia de hechos.
• Contesta lo que no se le pregunta.
Remedios:
• Recordarle.
• Insistir en la cronología.
• Regresara la pregunta inicial.
III. EL CONTRAINTERROGATORIO
El contraexamen se CONSTRUYE para el ALEGATO FINAL.
1. Finalidad del contrainterrogatorio
La lógica general para aproximarse al contraexamen responde a la pregunta¿qué quiero estar
en condiciones de poder decir en el alegato final?; esta pregunta determina toda la estrategia
del contraexamen.
La pregunta que el abogado litigante debe tener en mente al momento de encarar su con
traexamen no es: ¿cómo destruyo a este testigo en este acto?, sino, cosa distinta, ¿qué elemen
tos de este testigo necesito recoger o debilitar en mi alegato final?
2. Objetivos del contrainterrogatorio:
