IV. EL ALEGATO DE APERTURA
El alegato de apertura es la primera oportunidad que tiene el litigante de presentar su caso
ante el juez o tribunal; en consecuencia, debe recordarse siempre el aforismo que sostiene que
no hay una segunda ocasión de causar una primera buena impresión.
1. Lógica del alegato de apertura
El alegato de apertura debe funcionar como una hoja de ruta, una guía para que los juzgado
res, que no conocen los hechos, tomen conocimiento de cuál es la teoría del caso de cada una
de las partes y cuál es la evidencia que planean producir durante el juicio.
Se puede asemejar el alegato al tráiler o avance de una película: nos tiene que dar una idea de
qué se va a tratar la película, mostrarnos sus partes más interesantes y por supuesto nos tiene
que generar ganas de verla.
2. Contenido del alegato de apertura
No existe un único esquema para llevar adelante un alegato de aperturay hay cuestiones que
pueden o no estar, según el caso en concreto; sin embargo, sí hay secciones imprescindibles
que debe contener, a fin de que el juez o tribunal tengan un panorama integral respecto a
nuestra teoría del caso.
©
INTRODUCCIÓN
Es recomendable iniciar con una introducción que exponga una síntesis de toda aquella información más re
levante que vamos a querer que los jueces conozcan y comprendan, la misma que está contenida en nuestra
teoría del caso; por ello, esta introducción debe ser clara y ordenada.
©PRESENTACIÓN DE HECHOS Y PRUEBA
Seguidamente, se adelantan los hechos que serán materia de controversia, y la prueba que se va a utilizar para
demostrar cada uno de ellos; para ello, debemos se debe recordar que los jueces no conocen el caso, por ello
resultará de vital importancia una adecuada descripción de las circunstancias de tiempo, modo y lugar que:
i[Qde.áíqn;al;heóhófj!©y£;!oi:©s®
IDENTIFICACIÓN DE LOS INTERVINIERES EN EL CASO
Es importante que, en este primer momento de contacto con los jueces, se identifique a las personas que in
tervinieron en el hecho que es materia del caso, recordando que cada persona tiene sus propias características
y atributos que permite distinguirlas de otras,
Se puede incluir, además, en el alegato de apertura, la existencia de determinados elementos necesarios para;
una condena o una absolución; no es el momento de discutir cuestiones dogmáticas de derecho, tampoco,
para repetir el contenido de normas jurídicas, que son bien conocidas por los jueces, sino de adelantar alguna,
cuestión central que se va a desarrollar en el juicio y va a servir de base para peticionar una absolución o la;
