Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 239 of 1506 --

Tema 10: Litigación oral
3. Qué no hacer en un alegato de apertura
©
ÍÍG ES EL MOMENTO DE ¡lEAUZAñ ARGilPffiNTáCiO^ES
Siendo que el alegato de apertura es una presentación del caso, no es correcto que el litigante se adentre a ex
poner o sustentar argumentaciones sobre la responsabilidad o irresponsabilidad del acusado; esto lleva a una
confusión de momentos y espacios, puesto que las argumentaciones están reservadas para el final del juicio
©
NO ES LA OPORTUNIDAD DE REALIZAR UN DISCURSO POLÍTICO O EMOCIONAL
Muchas veces se comete el error de pretender, en el alegato de apertura, sustentar posiciones extrañas al caso,
como son alegaciones de carácter político o expresar sentimientos; esto es un grave error, porque simplemen
te llevará que los jueces que recién toman contacto con el caso, vean tal situación como una grave debilidad
probatoria del litigante.
En el juicio hablan las pruebas, por ello, al momento de iniciar ia participación del litigante, ios jueces deben
apreciar a un agente seguro y firme en su base probatoria, y no a un personaje que se limita a opinar lo que
cree que ocurrió.
MO SE DEBE EXAGERAR LA PRUEBA CON LA QUE SE CUENTA
Si el litigante promete más de lo que tiene, simplemente perderá credibilidad rápidamente; el tribunal no va a
ver con buenos ojos a quien prometió mucho más de lo que puede dar.
NO AHONDAR EN DETALLES
El alegato de apertura es una presentación del caso, no una alegación sobre lo probado y no probado; eso
corresponde al final del juicio, al alegato de clausura. Si ei litigante ahonda demasiado en detalles, ello puede
ser utilizado por la parte contraria para organizar sus pruebas u órganos de pruebas, de tal forma que se con
tradiga directamente esos detalles.
V. EL ALEGATO DE CLAUSURA
El alegato de clausura no sirve para salvar un mal juicio, sino para demostrara los juzgadores
porqué la prueba desarrollada o actuada en el plenario avala nuestra teoría del caso; es el
momento de ensambla todas las piezas del rompecabezas.
1. ¿Qué es un alegato de clausura?
El alegato de clausura se constituye en el acto más importante de la litigación, ya que es la
oportunidad que tienen las partes de argumentar sobre la prueba producida; la argumenta
ción es una exigencia, puesto que es el momento en que se va a valorar toda la prueba rendida
durante el debatey se va a demostrar al juez o tribunal por qué debe prevalecer la teoría del
caso que se sostiene.
Un buen alegato de clausura es la consecuencia de un buen juicio, de un debate fructífero y
previamente planificado; no hay posibilidad de salvar un mal juicio con un alegato de clausu
ra, por más que sea extraordinario.
