i. PRINCIPIOS DEL TÍTULO PRELIMINAR DEL CÓDIGO CIVIL
El Título Preliminar contiene normasy principios que inspiran al derecho peruano, pues a pe
sar de estar ubicado en el Código Civil (C.C.), su alcance normativo va más allá del derecho
privado, donde en rigor debería pertenecer.
PRINCIPIO DE LA DEROGACION DE LA LEY
Artículo I.- La derogación se produce por declaración expresa, por incompatibilidad entre la
nueva ley y la anterior o cuando la materia de ésta es íntegramente regulada por aquélla.
Por la derogación de una ley no recobran vigencia las que ella hubiere derogado.
COMENTARIO
El artículo comentado precede en el tiempo al artículo 103 de la Constitución, como sus an
tecedentes de los Códigos de 1936 (artículo 1) y de 1852 (artículo VI), ha optado por el vocablo
derogary no el de abrogar, como indicativa de la extinción de la vigencia temporal de las nor
mas. El uso del vocablo, la Carta Políticay el Código Civil lo hacen extensivo a toda modalidad
de supresión de la vigencia de una norma legal. La derogación puede sertotal o parcial, según
la norma derogatoria esté referida a la totalidad de la norma que viene a derogar o solo a uno
o más de sus aspectos, pero no a su totalidad. En ambos casos, como lo hemos ya indicado,
la norma comentada, integra los vacíos respecto de la problemática que se presenta cuando
la norma derogatoria no declara de manera explícita la norma que viene a derogar o cuando
la nueva norma genera una colisión con la norma vigente. Esta problemática, que cautivó la
atención de la doctrina, dio lugar a que se trazara una distinción entre derogación expresa y
derogación tácita.
La derogación expresa es la que se produce por la “declaración expresa” de la nueva ley. Aquí no
se genera problema constituyendo una sana políticay una buena técnica legislativa, que las
nuevas normas legales que van a entrar en vigor hagan una referencia explícita a las que van
a ser derogadas. La derogación tácita es la que resulta de la nueva norma que no tiene “decla
ración expresa" pero que colisiona con la que se encuentra en vigencia. A esta derogación se
refiere la norma en comentario cuando hace mención a que la derogación se produce “por
incompatibilidad entre la nueva leyy la anterior o cuando la materia de ésta es íntegramente
regulada por aquélla”.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 244 of 1506 --

UBILEX
El últim o párrafo del artículo I, que venimos comentando, precisa y enfatiza el efecto de la
derogación y, sin antecedente en nuestra codificación civil, ha receptado como norma general
la no reviviscencia de la norma derogada al preceptuar que “por la derogación de una ley no
recobran vigencia las que ella hubiere derogado”. De este modo, la norma derogada queda
con su vigencia definitiva extinguida, salvo que la norma que venga a derogar a la derogante
disponga que recobre su vigencia
EJERCICIO ABUSIVO DEL DERECHO
Artículo II.- La ley no ampara el ejercicio ni la omisión abusivos de un derecho. Al demandar
indemnización u otra pretensión, el interesado puede solicitar las medidas cautelares apropia
das para evitar o suprimir provisionalmente el abuso.
El abuso del derecho es un principio general del Derecho que, como toda institución jurídica,
atraviesa por dos momentos, uno fisiológico y el otro patológico. En el momento fisiológico,
el abuso del derecho debe ser entendido, junto con la buena fe, como un límite intrínseco
del mismo derecho subjetivo (Ruiz Serramalera, Carcia Amigo, Diez-Picazo, Gullón, Breccia,
Bigllazzi Gerinatoll, Busnelli, entre otros) y ahí sí cabría su estudio dentro de la Teoría General
del Derecho (como lo sostiene Fernández Sessarego). En cambio, en el momento patológico,
el abuso del derecho se asimila, bien a los principios de la responsabilidad civil (cuando se
produce un daño o hay amenaza del mismo) o bien a las reglas de la ineficacia (cuando nos
encontramos frente a una pretensión procesal abusiva) (Cambara).
El abuso del derecho, en tanto principio general, es un instrumento del cual se vale el opera
dor jurídico para lograr una correcta y justa administración de justicia. Es aquí donde juega
un rol decisivo la labor creativa y prudente del juez que, debe estar atento a reconocer nuevos
intereses existenciales y patrimoniales, enfrentando audazmente modelos legislativos que
los pretenden inmovilizar.
APLICACIÓN DE LA LEY EN EL TIEMPO
Artículo III.- La ley se aplica a las consecuencias de las relaciones y situaciones jurídicas exis
tentes. No tiene fuerza ni efectos retroactivos, salvo las excepciones previstas en la Constitu
ción Política del Perú.
El artículo III del T.P aloja dos principios: la irretroactividad de la norm ay la aplicación inme
diata de la ley. La irretroactividad es un principio general por el que se pone límite temporal
a la aplicación de la nueva ley. Así, en principio, el Derecho considera injusto aplicar una ley
nueva a actos que fueron realizados en el momento en que dicha ley no existía, y que por
consiguiente no podía ser conociday mucho menos acatada. Esta norma ha encontrado lugar
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 245 of 1506 --

Tema 1: Temas com unes a la especialidad: Civil, Familia y Comercial
entre los denominados derechos fundamentales, habiendo sido recogida también por nues
tra Constitución (art. 103), lo que a su turno da lugar a interponer acción de amparo cuando se
transgreda este derecho.
Si bien en línea de principio está vedado a nuestro legislador otorgarle efectos retroactivos a
la ley, no le está prohibido otorgarle a la antigua ley efectos ultractivos, es decir, la aptitud que
tiene la norma no solo de regular los efectos producidos durante su vigencia, sino también
sobre aquellos que se realicen cuando ya tenía vigencia la nueva norma, por originarse en un
hecho que tuvo lugar bajo el imperio de la antigua ley.
Conforme a lo normado en el art. III del T.R en nuestra legislación:
a) Tanto la irretroactividad como la aplicación inmediata de la ley son dos principios legales
que en nuestro ordenamiento tienen estatus constitucional.
b) Estos principios noson necesariamente antagónicos,y porel contrario se complementan.
c) En línea con lo anterior, en nuestro Derecho la ley no opera retroactivamente, por lo tanto,
los hechos y efectos que se suscitaron con la antigua ley no podrán ser normados por la
nueva, salvo la excepción establecida en la propia Constitución.
d) Si los efectos se producen cuando ya se encuentra en vigencia la nueva ley, pero éstos han
tenido su origen en relaciones jurídicas surgidas al amparo de la anterior normatividad,
se recurrirá al principio de aplicación inmediata de la ley, con lo que tales efectos serán
gobernados por la nueva ley.
e) Cuando se trata de efectos continuados que han tenido origen en una relación jurídica
surgida bajo el imperio de la anterior ley, pero dichos efectos se desarrollan también
cuando ya se encuentra vigente la nueva ley, se recurrirá al principio de aplicación inme
diata de la ley.
f) Si la relación jurídica surgió con la anterior ley, pero sus efectos fueron supeditados a la
realización de una condición suspensiva, cumplida esta condición los efectos se regirán
por la nueva ley.
g) No obstante haberse proscrito en nuestro sistema la irretroactividad, no ha acontecido lo
mismo con la ultractividad, lo que permite a discreción del legislador que ciertas normas
puedan mantener aplicación pese a estar vigente la nueva norma.
APLICACIÓN ANALÓGICA DE LA LEY
Artículo IV.- La ley que establece excepciones o restringe derechos no se aplica por analogía.
En relación a las normas generales, tenemos que mirar atentamente la cultura jurídica del
medio y tom aren cuenta cuáles son las normas jurídicas que en ella se consideran normas ge
nerales, por sí mismas (igualdad de sexos) o mientras no sean alteradas (grados de parentesco
con reconocimiento jurídico).Lo contrario a dichas normas generales serán normas de excep-
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 246 of 1506 --

UBILEX
ción y, éstas, deberán tener una aplicación que llamada como “no análoga” por este artículo,
nosotros la consideramos como aplicación interpretativa estricta.
El artículo IV del T.P prohíbe la aplicación por analogía de la ley que establece excepciones o
restringe derechos. Aquí la palabra ley no debe entenderse en el sentido estricto de norma
aprobada por el Poder Legislativo y promulgada por el Ejecutivo. Ni siquiera solo norma con
rango de ley para incluirá los decretos legislativos y de urgencia. En efecto, sería absurdo que
las normas con rango de ley no puedan ser aplicadas de esta manera pero sí lo pudieran ser
los decretos y resoluciones. Aquí, en consecuencia, tenemos que tom ar la palabra ley en el
sentido de norma jurídica de origen legislativo.
Tener en cuenta que este artículo no solo prohíbe que se aplique la analogía. También está
en su ratio legis prohibir la interpretación extensiva. Por consiguiente, debería estar redactado
del modo siguiente: "La norma legislativa que establece excepciones o restringe derechos se
aplica estrictamente, es decir, ni por interpretación extensiva ni por analogía”.
LA AUTONOMIA PRIVADA: SUS LIMITACIONES FRENTE A LAS LEYES IMPERATIVAS Y AL ORDEN PÚBLICO
Artículo Es nulo el acto jurídico contrario a las leyes que interesan al orden público o a las
buenas costumbres.
COMENTARIO
En el caso del ejercicio del derecho privado contenido fundamentalmente, en el Código Civil
vigente; toda persona está obligada a respetar el orden público y las buenas costumbres, en
todos los convenios y en todos los actos de su competencia ya que por el ejercicio de su libre
voluntad no podrá atentar contra la regularidad social de la comunidad que está resguardada
por normas de Derecho Público el cual es el sostén del orden públicoy el que marca la línea de
las buenas costumbres. En conclusión, el Estado gobierna la comunidad nacional a través de
pluralidad de normas que en su conjunto constituyen el Derecho Público, el cual es el sustento
del orden público. El Estado al hacer uso de las leyes ante la comisión de cualquier irregulari
dad determina la inmediata intervención de la administración Pública imponiendo órdenes,
prohibicionesy sanciones atodas aquellas personas que no respetan el ordeny la regularidad
para mantener la paz y la seguridad ciudadana. Todo porque el orden público es para el de
recho privado el límite de la autonomía de la voluntad en virtud de la cual resultan nulos por
ejemplo los contratos que atenían contra el orden públicoy las buenas costumbres. Este es el
respeto al orden público sostenido porel Derecho Público a través de la Administración públi
ca, que es la que ejerce el control de la sociedad.
LEGITIMIDAD PARA OBRAR
Artículo VI.- Para ejercitar o contestar una acción es necesario tener legítimo interés económi
co o moral.
El interés moral autoriza la acción sólo cuando se refiere directamente al agente o a su familia,
salvo disposición expresa de la ley.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 247 of 1506 --

Tema 1: Temas com unes a la especialidad: Civil, Familia y Comercial
La legitim idad para obrar es entonces la posición habilitante para ser parte en el proceso; en
ese sentido, se habla de legitimidad para obrar activa para referirse a la posición habilitante
que se le exige al demandante para poder plantear determinada pretensión; y se habla de legi
tim idad para obrar pasiva para referirse a la posición habilitante que se le exige al demandado
para que la pretensión planteada en el proceso pueda plantearse válidamente contra él. Esta
posición habilitante puede estar determinada por dos situaciones distintas:
1. Por la simple afirmación que realiza el demandante de la titularidad de las situaciones
jurídicas que él lleva al proceso, en este caso estamos frente al supuesto de lo que la doc
trina conoce como legitimidad para obrar ordinaria.
2. Por la permisión legal expresa a determinadas personas a iniciar un proceso, a pesar de no
sertitulares de las situaciones jurídicas subjetivas que se llevan a él. En este caso estamos
frente a lo que la doctrina conoce como legitimidad para obrar extraordinaria.
Algunos casos de legitim idad para obrar extraordinaria que contempla el ordenamiento jurí
dico peruano son los contemplados en los artículos 1219 inciso 4) y 1987 del C.C., así como en
el artículo 82 del C.PC.
PRINCIPIO DE IURA NOVIT CURIA
Artículo Vil.- Los jueces tienen la obligación de aplicar la norma jurídica pertinente, aunque no
haya sido invocada en la demanda.
COMENTARIO
La tutela jurisdiccional efectiva es un derecho inherente a la personay como tal se convierte en
un derecho fundamental que nos faculta acudiral juez parasolicitarque resuelva un conflicto
de intereses o para que dilucide una incertidumbre con relevancia jurídica. Este derecho de la
persona está cohesionado con la obligación que tiene el juez para en el ejercicio de su función
jurisdiccional aplique el derecho que corresponda al conflicto que es motivo de solución. Esta
facultad del juez la ejercita haciendo efectivo el principio de IURA NOVIT CURIA, contendido
en el Art. Vil del T.R del Código Civil.
Se da el caso que esta norma genérica y vinculante del Derecho Civil, es concordante con el
principio Juez y Derecho que lo prevé el Art. Vil del T.R del C.RC. al imponer al juez la obliga
ción de aplicar el derecho o sea la norma pertinente al conflicto de intereses que se debate,
aunque no haya sido invocada por la parte procesal en el escrito de la demanda. Esta aseve
ración conceptual nos permite afirmar que en este principio del Derecho Procesal Civil está
insumido el principio de iura novit curia tal como se desprende del siguiente texto “EL JUEZ
DEBE APLICAR EL DERECHO QUE CORRESPONDA AL PROCESO, AUNQUE NO HAYA SIDO
INVOCADO POR LAS PARTES O LO HAYA SIDO ERRÓNEAMENTE. Sin embargo, no puede ir
más allá del petitorio ni fundar su decisión en hechos diversos de los que han sido alegados
