Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 248 of 1506 --

UBILEX
j por las partes”. Se deja de analizar la parte final del texto del principio Juez y Derecho que co-
'' rresponde porque corresponde al principio de congruencia.
VACIOS DE LA LEY Y PRINCIPIOS GENERALES DEL DERECHO
Artículo VIII.- Los jueces no pueden dejar de administrar justicia por defecto o deficiencia de la
ley. En tales casos, deben aplicar los principios generales del derecho y, preferentemente, los
que inspiran el derecho peruano.
La ley tiene vacíos, deficiencias. Sucede que la ley no puede comprenderen su formulación to
dos los innumerables casos posibles que la realidad presenta; y sin embargo, como lo expresa
el texto del artículo VIII del Título Preliminar, no le está permitido al juez dejar de administrar
justicia. Por más esfuerzos que haga el legislador a fin de contener en el supuesto de hecho
general y abstracto que constituye la ley las más variadas e imprevisibles circunstancias, inevi
tablemente su creación será superada por la realidad.
Pero el problema de los vacíos de la ley no es el reconocer que existen— pues la imperfección del
ordenamiento legal es más o menos obvia, y además admitida por la propia ley— , sino cuándo
estamos frente a un verdadero vacío legal. Para intentar solucionar este problema la doctrina ha
señalado que existen lagunas de la ley.
Los principios generales del derecho son mandatos de optimización que se caracterizan por
que pueden ser cumplidos en diversos grados y porque su cumplim iento no solo depende
de las posibilidades fácticas, sino también de las posibilidades jurídicas. El campo de las po
sibilidades jurídicas está determinado a través de principios y leyes que juegan en sentido
contrario.
Desde el punto de vista del razonamiento jurídico, las leyes guardan algunas ventajas frente
a los principios. En primer lugar, las leyes permiten ahorrartiem po a la hora de decidir, pues si
una regla es aceptada como válida, es aplicada sin más evitando tener que entrar en un pro
ceso de ponderación de razones en pro y en contra de una determinada decisión. La ley opera
por tanto, como un elemento que reduce la complejidad de los procesos de argumentación.
No obstante, si bien esto es verdad, en contrapartida los principios son superiores a las leyes
por encontrarse enunciados de manera más general, lo que les permite comprender un ma-
yornúm ero de situaciones. En este sentido, los principios tienen un mayor poder explicativo y
justificativo frente a las leyes.
PRINCIPIO DE APLICACIÓN SUPLETORIA DEL CÓDIGO CIVIL
Artículo IX.- Las disposiciones del Código Civil se aplican supletoriamente a las relaciones y
situaciones jurídicas reguladas por otras leyes, siempre que no sean incompatibles con su
naturaleza.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 249 of 1506 --

Tema 1: Temas com unes a la especialidad: Civil, Familia y Comercial
La doctrina considera que el Derecho Civil ha traspasado las fronteras de las diversas discipli
nas jurídicas, porque en el ejercicio de éstas últimas especialidades, muchas veces carecen de
la capacidad jurídica para resolver sus actos que le son propios, lo cual determina para que sin
pensar acudan la aplicación supletoria de las normas civiles, de lo que se puede concluir que
los denominados derechos especiales por mucho que mantienen su independencia siempre
se alimentan de lo que el derecho Civil les puede proporcionar vía supletoriedad para solucio
nar algún conflicto que sea de su competencia.
Se aplica la supletoriedad del Derecho Civil, siempre y cuando no exista la solución del con
flicto dentro del contexto del mismo derecho especial. En este caso se aplica el método de la
autointegración.
OBLIGACIÓN DE DENUNCIAR VACIOS 0 DEFECTOS DE LA LEGISLACIÓN
Artículo X.- La Corte Suprema de Justicia, el Tribunal de Garantías Constitucionales y el Fiscal
de la Nación están obligados a dar cuenta al Congreso de los vacíos o defectos de la legisla
ción.
Tienen la m ism a obligación los jueces y fiscales respecto de sus correspondientes superiores.
El enunciado obliga a tres entes: la Corte Suprema de Justicia, al Tribunal Constitucional y al
Fiscal de la Nación realizar la divulgación de las incoherencias en las normas jurídicas. La obli
gación se le asigna a la Corte Suprema y no al presidente de ésta. El órgano deliberante de la
Corte Suprema es la Sala Plena, por tanto, corresponderá a este colegiado la difusión de la
cobertura de la norma jurídica. La Corte Suprema no solo tiene la obligación de poner en co
nocimiento los vacíos o defectos de la norma jurídica, según el artículo comentado, sino que
además, tiene el derecho a la iniciativa en la formación de leyes; sin embargo, debe tenerse en
cuenta que el artículo 21 de la Ley Orgánica citada permite no solo se dé cuenta al Congreso
de los vacíos y deficiencias de la normasino también al Ministerio de Justicia. Esta regulación
debe ser justificada en atención a la vigencia antelada del Código Civil, esto es, en 1984. El
Tribunal Constitucional está obligado a la denuncia legal; pero— a la vez— también goza de
la facultad de la iniciativa legal en la actual Constitución de 1993 y en la derogada de 1 9 7 9 - El
Fiscal de la Nación se obliga a la denuncia legislativa. La redacción del artículo en comentario
no refiere al Ministerio Público sino que personifica la figura del Fiscal de la Nación. A pesar de
esta redacción debemos entender que dicha obligación le corresponde al Ministerio Público a
través de sus miembros.
La norma en comentada se justifica por la naturaleza esencialmente política de la función
legislativa. Las leyes no son siempre elaboradas con criterios técnicos pues el Congreso está
conformado no en base a especialistas en el Derecho, sino a políticos, cuyo criterio de elección
no es precisamente la capacidad para desarrollar la producción de leyes. Este artículo, a pesar
de contener la obligación no solo de los organismos ya descritos sino también de los jueces y
