UBILEX
fiscales respecto de sus correspondientes superiores, es poco invocado, pero no por ello es me
nos importante, para el desarrollo de una legislación interna coherente, con menos lagunas
deficiencias y aspectos obsoletos.
li. DERECHOS DE LA PERSONA Y EL CONCEBIDO. ATRIBUTOS DE LA PERSONALIDAD.
CAPACIDAD (INTERDICIÓN), NOMBRE, DOMICILIO. FIN DE LA PERSONA. PERSONAS
JURÍDICA: TIPOS. REPRESENTACIÓN. FIN O EXTINCIÓN DE LA PERSONA JURÍDICA
1. Derecho de la persona y el concebido. Atributos de la personalidad
El sujeto de derecho.- Es el ente en que el ordenamiento jurídico imputa derechos y deberes,
este ente o centro de referencia normativo no es otro que el ser humano, antes de nacer o des
pués de haberse producido este evento, ya sea que se le considere individualmente o como
organización de personas.
El Código reconoce cuatro categorías de sujeto de derecho:
1. Persona natural o individual: El hombre una vez nacido como Individuo.
2. Personas jurídicas: Organización colectiva siempre que cumpla con la form alidad de su
inscripción exigida con la norma.
3 . El concebido: Ser humano antes de nacer.
4 . Organización no inscrita: La pluralidad de personas individuales que actúan organiza
damente en el cumplimiento de determinados fines valiosos; es una organización de per
sonas que, comportándose como persona jurídica, no ha cumplido con el requisito de su
inscripción en el registro respectivo.
La subjetividad y personalidad.- La subjetividad del sujeto de derecho, debe de entenderse
como la capacidad la idoneidad a su titu la r de derechos y deberes como los reconoce el orde
namiento jurídico, atribuyéndose la calidad de centro de Imputación normativo.
Personalidad: La calidad del “Sujeto de Derecho” es atribulble solo al ser humano, a todos los
seres humanos sin excepción, excluyéndose la posibilidad de configurar sujetos de derecho
constituidos por conjunto de bienes, siendo esta posición humanista o personalista.
El Código Civil de 1936, usaba la palabra “Personalidad” que originaba dificultades teóricas,
siendo sustituida en el Código Civil de 1984 por la expresión más cabal de “Persona Humana".
Derechos personalísimos.- Que tienen como característica fundamental que el objeto de
protección jurídica se encuentra situado en el ámbito de la persona misma, del sujeto de de
recho, al objeto de aquellos derechos se hallan en el mundo personal, dentro del entorno del
ser humano; que asegura a la persona humana su vida en comunidad y que los demás seres
humanos respeten aquellos instrumentos de apoyo de su ser.
Derechos de la personalidad.- Son aquellos que son Innatos al hombre como tal, y de los
cuales no puede ser privado. Así, por ejemplo: el derecho a la vida, al honor, a la libertad, a la
integridad física, a la Intimidad de la vida personal y fam iliar en todos sus diversos aspectos,y
el derecho de autor que goza de una regulación especial.
250 BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 251 of 1506 --

Tema 1: Temas com unes a la especialidad: Civil, Familia y Comercial
Caracteres de ios Derechos de ia Personalidad:
a. Son innatos, se adquiere con el nacimiento.
b. Son vitalicios, puesto que duran tanto como la vida del titular.
c. Son inalienables, porque están en el comercio jurídico, y no pueden ser objeto de venta,
cesión o transferencia.
d. Son imprescriptibles, pues no se adquieren ni se pierden por el transcurso del tiempo, o
del abandono que de ellos se hagan.
e. Son absolutos, en el sentido de que se pueden oponer.
Derecho a la vida.- La vida está protegida j urídicamente desde el momento de la concepción,
de ahí que el aborto sea considerado un delito, incluso en el ámbito laboral, a la madre emba
razada, se le protege. Con mayor razón está protegida la vida después del nacimiento, ya sea
porel derecho penal o civil.
Derecho a la integridad corporal.- Este derecho está íntimamente vinculado con el anterior.
La protección jurídica o la integridad jurídica y la salud de las personas, esta contenido ante
todo en el Código Penal; también lo está por el derecho civil, que obliga a indemnizar los da
ños y perjuicios resultantes de las lesiones físicas y sanciona la nulidad de actos y contratos
que vulneren este derecho.
Derecho a la libertad.- Este derecho está protegido ante todo, en el derecho penal, que cas
tiga la reducción de una persona a la servidumbre o a otra condición análoga. El Código civil
reputa ilícitos los actos jurídicos que se opongan la libertad de las acciones o de la conciencia.
Derecho al respeto de la intimidad.- El derecho reconoce la intim idad de la vida privada, en
todos sus aspectos, como objeto de protección jurídica, con los únicos límites del asentimien
to de la propia persona o de la de un prevaleciente interés social.
Derecho al honor.- El honores el íntimo y raigal valor moral del hombre. Es un valioso bien de
carácter no patrimonial, que conlleva un sentimiento o conciencia de la propia dignidad como
persona. El honor es un bien que socialmente se traduce en el respeto y consideración que se de
los demás en la estima, aprecio, buena famay reputación adquiridas por la virtudy el trabajo.
Derecho a la vida.- Es primordial entre los derechos atinentes a la persona, y el presupuesto
indispensable de todos los demás. De no existir el derecho a la vida, carecería de sentido re
ferirse a la constelación de derechos reconocidos porel ordenamiento jurídico para la protec
ción y tutela de la persona humana.
Derecho a la libertad.- Supone la personalidad de todo ser humano de decidirse por un pro
yecto de vida dentro del bien común, de realizarse plenamente como hombre, o en otros tér
minos, de poder hacer todo aquello que esta jurídicamente permitido, que no está expresa
mente prohibido, siempre que no se atente contra el derecho, el interés social y no signifique
un abuso del derecho.
Derecho a la integridad física.- Permite a la persona, mantener la de su cuerpo, a fin que uti
lizándolo al máximo, y en óptimas condiciones, pueda realizarse plenamente como ser libre.
Al mencionarse la integridad física, debe entenderse que ella se refiere al cuerpo, es decir a la
inescindible unidad psicosomática.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 252 of 1506 --

UBILEX
2. La vida humana y é concebid©
El Código Civil otorga al concebido la calidad del sujeto de derecho de centro de imputación
normativo, sustentándose en que el concebido constituye vida humana genéticamente indi
vidualizada, desde el instante mismo de la concepción, ósea, a partir de la fecundación de un
óvulo por un espermatozoide.
Repercusión jurídica de la ingeniería genética: Nuestra legislación es indulgente, no regula
acontecimientos provocados por los nuevos avances de la genética referidos a las nuevas téc
nicas de fertilización,ya que se trata de situaciones no contempladas. En el Perú, es el Derecho
Genético quien ha realizado una elaboración legal para proteger al ser humano de los avances
biocientífñcos de la ciencia genética.
3. Derechos patrimoniales y extrapatrimoniales del concebido
El concebido como sujeto de derecho, se le atribuye derechos extrapatrimoniales y patrimo
niales. En cuanto a los primeros no esté sujeto a condición alguna. Ejemplo: el derecho la vida.
En cambio, con respecto a los segundos existe un conjunto de derechos de índole patrimonial
que si están sometidos a condición resolutoria: como los derechos sucesorios y la donación.
En estos casos si bien el concebido adquiere derechos en cuanto sujeto de derecho, están so
metidos a condición resolutoria. Si el concebido no nace vivo se resuelven tales derechos pa
trimoniales.
4. Capacidad (interdicción), nombre, domicilio
El goce de los derechos significa (dentro del centro de imputación de derechos y deberes que
es la persona) que no sufre restricciones para exigir sus derechos, sus facultades son plenas,
sus derechos no serán burlados ni distraídos.
La capacidad jurídica o de goce pertenece a todo sujeto de derecho (concebido, persona na
tural o jurídica y entes no personificados) y consiste en la aptitud para ser titu la r de derechos
y obligaciones. Así todo sujeto de derecho puede ser propietario, arrendatario, mutuatario,
mutuante, etc. Pero existen casos especiales en los cuales el sujeto de derecho está privado de
la capacidad jurídica. Por ejemplo: los menores que no pueden contraer m atrim onio o para
adoptar. Pero estas son excepciones, la regla es la capacidad jurídica.
La capacidad de ejercicio (Legal) es la posibilidad de aptitud del sujeto de derecho a ejercer,
por sí mismo, los derechos de que goza en cuanto a persona. Esta capacidad de voluntad está
supeditada a la de goce, porque quien tiene el derecho tiene la acción,y este no existe si aquel
no ha nacido. Si por capacidad, se entiende la aptitud o suficiencia para alguna cosa, la capa
cidad legal, es la facultad más o menos amplia de realizar actos válidos y eficaces en derecho,
la suficiencia de la persona para adquirir derechos y administrarlos por ella misma, ante la ley,
contrario sensu, la incapacidad es la carencia de condiciones físicas, psíquicas.
El Perú cuenta con un nuevo tratamiento de la capacidad en el Código Civil, logrando un acer
camiento a las directrices de las Naciones Unidas en pro de la autonom íay la plena capacidad
jurídica de las personas con discapacidad. Mediante las últimas modificaciones, realizadas
por el Decreto Legislativo N°i384 (D. Leg. 1384), Decreto Legislativo que reconoce y regula la capa-
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 253 of 1506 --

Tema 1: Temas com unes a la especialidad: Civil, Familia y Comercial
cidad jurídica de las personas con discapacidad en igualdad decondiciones, se unen varios aspectos in
conclusos en torno a los derechos de las personas con discapacidad, sobre la base del respeto a
los derechos humanos de todos los ciudadanos, especialmente en cuanto a su dignidad, auto
nomía e igualdad ante la ley. El modelo social vigente remplaza el régimen de sustitución
de la voluntad de las personas incapaces(sistema de sustitución), por uno de asistencia
a través de los denom inados apoyos y salvaguardias. Toda persona, independientem ente
de su capacidad, es un sujeto de derecho libre de tom ar y responder de sus decisiones
personales.
5. Capacidad e incapacidad de ejercicio:
Para Marcial Rubio, “la capacidad de ejercicio es la atribución de la persona de ejecutar por sí
misma los derechos a los que tiene capacidad de goce”.
a. - Capacidad de ejercicio plena.- La capacidad de ejercicio es la aptitud para podercelebrar
por sí mimo actos jurídicos válidos. Para celebrar un contrato, contraer matrimonio, esta
blecer una herencia etc. Según el Art. 42 del C.C. se adquiere la capacidad de ejercicio a
los 18 años, esto incluye a todas las personas con discapacidad, en igualdad de condicio
nes con las demás y en todos los aspectos de la vida, independientemente de si usan o
requieren de ajustes razonables o apoyos para la manifestación de su voluntad.
La modificación del D. Leg. N ° i384 ha suprimido del artículo 43 el inciso segundo del C.C,
de tal manera que las personas que por cualquier causa se encuentren privados de discer
nimiento serán, efectivamente, capaces. En ese contexto, la falta de discernimiento no es
sinónimo de incapacidad. Esto tiene una íntima relación con la modificación del artícu
lo 44 del C.C., en tanto las personas con retardo mental o los que adolecen de deterioro
mental, a pesar de ser faltas de discernimiento, no serán consideradas incapaces al haber
sido derogadas como supuestos de tal artículo.
b. Incapacidad de ejercicio.- Es la ausencia de capacidad de ejercicio. El sujeto de derecho
no puede celebrar actos jurídicos válidos: no podrá celebrar contratos, donar, etc. Con an
terioridad a la publicación del D. Leg. 1384, la incapacidad de ejercicio podía ser absoluta
y relativa (sistema de sustitución), ahora se pasó a un sistema en el cual no se niega la ca
pacidad, sino que pasa a considerarse en sus aspectos de ser absoluta o restringida, reafir
mando la autonomía jurídica de las personas, su realización a través de apoyos (guardas).
• Incapacidad de ejercicio Absoluta (Art. 43 C.C.).
Los menores de 16 años, salvo aquellos actos determinados por la ley.
El Código Civil de 1852 solo regulaba a la incapacidad absoluta. Por su parte, el
Código Civil de 1936 extendió la institución hacia la incapacidad relativa, man
teniéndose esta en el texto original del Código Civil del 1984. Ahora, el referido
Código Civil, modificado por el D. Leg. N° 1384, refiere, a la capacidad y a la ca
pacidad restringida, eliminando también en gran medida a la incapacidad del
sujeto.
El nuevo sistema de capacidad suprime el sistema de sustitución, que primaba
para los privados de discernimiento y demás personas con discapacidades, a fin
