de que pudieran ejercer sus derechos y deberes de manera válida a través de
su curador. Siendo así, ahora estos individuos cuentan con capacidad jurídica
plena, lo cual, de manera principal, les permite autodeterminarse en función a
su autonom íay dignidad.
• Capacidad de ejercicio restringida (Art. 44 C.C.). Tienen capacidad de ejercicio res
tringida:
Los mayores d e i6 añosy menores d e i8 años.
Los pródigos. Entendiéndose por pródigo al que disipa sus bienes, al gastador
desordenado.
Los que incurren en mala gestión. Se entiende por ella, la manifiesta ineptitud
de una persona para manejar sus negocios. Se trata de una inhabilidad para la
administración del patrimonio.
Los ebrios habituales. Este estado produce con frecuencia “psicosis paranoide
de celos, alucinaciones alcohólicas, cuadros clínicos, todos ellos, con pérdida de
discernimiento".
Los toxicómanos. Se entiende por ello al “drogadicto”y se aplica a la persona que
ha desarrollado fármaco - dependencia severa, es decir aquella que necesita
consumir alguna droga para aplacar la apetencia imperiosa de la misma.
Los que sufren pena que lleva anexa la interdicción civil. Esta incapacidad no se
origina ni en la edad ni en la salud de la persona sino que encuentra fundamen
to en la situación de hecho en que se halla la persona, que le impide ejercer sus
derechos por sí misma. El Art. 595 del Código Civil establece que ejecutoriada la
sentencia penal que conlleve la interdicción civil, el fiscal pedirá, dentro de 24
horas, el nombramiento de curador para el interdicto.
Las personas que se encuentren en estado de coma, siempre que no hubiera
designado un apoyo con anterioridad.
Ajustes razonables y apoyos (Art. 45 C.C.).- El Código Civil de 1984 anterior a las modifica
torias realizadas por el D. Leg. 1384 propugnaba una sustitución de la persona considerada
incapaz, limitaba su personalidady vulneraba la esencia de su propia vida. La modificación del
artículo 45 y la incorporación de los artículos 45-A y 45-B permiten a la persona con discapacidad,
a su elección en caso cuente con discernimiento, nombrara un apoyo o ajustes razonables para el
ejercicio de su capacidad jurídica.
Según el vigente artículo 45 del C.C., “Toda persona con discapacidad que requiera ajustes razona
bles o apoyo para el ejercicio de su capacidad jurídica puede solicitarlos o designarlos de acuerdo a su
libre elección”.
El “ajuste razonable”, es un mecanismo que permite a la persona poder realizarse, es todo
aquello que necesita para manifestar su voluntady que se verá realizado mediante un apoyo
que no lo limite, sino que lo coadyuve al desarrollo de su personalidad.
Representantes legales (Art. 45-A C.C.).- El artículo 45-A del C.C. reitera lo señalado en el
antiguo artículo 45, por el que las personas mayores de 16 añosy menores d e i8 años, los
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 255 of 1506 --

Tema 1: Temas com unes a la especialidad: Civil, Familia y Comercial
pródigos, los que incurren en mala gestión, los ebrios habituales, los toxicómanos y los
que sufren pena que conlleve a su interdicción civil, deberán contar con un representante
legal de acuerdo con las normas de la patria potestad, la tutela y la cúratela.
Designación de apoyos y salvaguardias (Art. 45-B C.C.).-Conforme a lo establecido en
el artículo 659-B del C.C. sobre los apoyos, son formas de asistencia libremente elegidas
por una persona mayor de edad para facilitar el ejercicio de sus derechos, incluyendo el
apoyo en lacomunicación,en lacomprensión de los actos jurídicosy de las consecuencias
de estos,y la manifestación e interpretación de la voluntad de quien requiere el apoyo. La
referida norma establece que “El apoyo no tiene facultades de representación salvo en los
casos en que ello se establezca expresamente por decisión de la persona con necesidad de
apoyo o el juez en el caso del artículo 569".
Según el artículo 45-B del C.C.: pueden designar apoyos y salvaguardias:
1. Las personas con discapacidad que manifiestan su voluntad puede contar con apoyos y
salvaguardias designados judicial o notarialmente.
2. Las personas con discapacidad que no pueden manifestar su voluntad podrán contar con
apoyos y salvaguardias designados j udicial mente.
3. Las personas que se encuentren en estado de coma que hubieran designado un apoyo
con anterioridad mantendrán el apoyo designado.
4. Las personas con capacidad de ejercicio restringida contempladas en el numeral 9 del
artículo 44 contarán con los apoyos y salvaguardias establecidos judicialmente, de con
form idad con las disposiciones del artículo 659-E del C.C., que expresa que el juez puede
determinar, de modo excepcional, los apoyos necesarios para las personas con discapa
cidad que no puedan manifestar su voluntad y para aquellas con capacidad de ejercicio
restringida.
El incorporado artículo 1976-A del C.C. establece que "La persona que cuenta con apoyos es
responsable por sus decisiones, incluso de aquellas realizadas con dicho apoyo, teniendo
derecho a repetir contra él. Las personas comprendidas en el artículo 44 numeral 9 no son
responsables por las decisiones tomadas con apoyos designados judicialmente que hayan ac
tuado con dolo o culpa”.
Como se puede advertir, la referida norma establece que la persona con discapacidad, que
pueda o no manifestar su voluntad, será responsable por las decisiones que pudiera adoptar
en el marco de un proceso de transacción, siempre que se encuentre debidamente acompaña
do por su órgano de apoyo, quien velará por que la persona con discapacidad pueda compren
der los actos jurídicosy sus consecuencias. En caso que el órgano de apoyo, valiéndose de su
cercaníay confianza respecto de la persona con discapacidad, le perjudicará con la suscripción
de determinados actos jurídicos, obteniendo indebidamente un lucro para sí o un tercero, en
perjuicio de la persona con discapacidad, aquél podrá repetir contra el órgano de apoyo por
los daños y perjuicios generados, sin embrago no podrá pretender nada al tercero con el que
se vincula.
El nuevo artículo 45-B establece dos posibilidades según la persona con discapacidad cuente
o no con discernimiento. Así:
