Supuestos para el cese de incapacidad (Art. 46 C.C.): Existen determinadas situaciones en las
que se produce el cese de la incapacidad. Estas supuestos son:
La incapacidad cesa a partir del nacimiento del hijo o hija únicamente para realizar los
siguientes actos:
1. Inscribirel nacimientoy reconocerá sus hijos e hijas,
z. Demandar por gastos de embarazo y parto.
3. Demandary ser parte en los procesos de tenencia, alimentos y régimen de visitas a
favor de sus hijos e hijas.
4. Demandary ser parte en los procesos de filiación extramatrimonial desús hijos e hijas.
5. Celebrar conciliaciones extrajudiciales a favor de sus hijos e hijas.
6 . Solicitar su inscripción en el Registro Único de Identificación de Personas Naturales,
tram itar la expedición y obtener su Documento Nacional de Identidad.
7. Impugnar judicialmente la paternidad.
En forma análoga, el artículo 46-AC.C. refiere que la incapacidad de las personas mayores
de 16 años cesa por obtener título oficial que les autorice ejercer profesión u oficio. No se
aplica para contraer matrimonio.
Interdicción civil: Es laacción judicial por la cual aúna personase le declara incapaz de ejercer
sus derechos civiles por sí misma. Señala el artículo 583 del C.C. que, pueden pedir la interdic
ción de la persona con capacidad de ejercicio restringida según el artículo 44 numerales del 4
al 7, su cónyuge, sus parientes o el Ministerio Público.
Pueden ser objeto de interdicción:
Los pródigos.
Los que incurren en mala gestión.
Los ebrios habituales.
Los toxicómanos.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 257 of 1506 --

Tema 1: lem as com unes a la especialidad: Civil, Familia y Comercia!
Nombre
El nombre es el modo del cual se identifica a la persona. Y por tanto se diferencia de las demás
personas.
Elementos del Nombre: El nombre comprende tanto el prenombre o nombre de pila y los
apellidos. Ejemplo: Juan Pérez Reyes.
Según el Art. 19 C.C. el nombre es un derecho y un deber. El derecho a nombre permite iden
tificar a una persona: el deber de llevar un nombre, comprende el derecho a exigir que se le
designe por dicho nombre, por ende, se regula las acciones tendientes a hacer cesar la vulne
ración de este derecho o a impedir la utilización indebida del nombre.
Características del Nombre:
Es necesario Nadie püeSe dejar cíe tener ún nombre (prenombre y apellidos):
Es único
Es inmutable (Art. 29 C.C.)
El nombre permite identificar a una persona, distinguiéndolo de los demás. Por! lo tanto,
nadie puede usar un nombre que no le corresponde (Art.''''28 C.C,) El uso de un nombre que
no le corresponde, significa violación del derecho al nombre o a la identidad. Aquel que
es:perjudicado por la usurpación del nombre tiene acción pafa hácér cesar la violación y
obtener la indemnizacíón que corresponda..
Nadie puede cambiar su nombre ni hacerle adiciones, salvo por motivos justificados y
mediante autorizaciónjudicial;ldeb¡damente:publicada e in scrita;^
nombre alcanza, si fuere el caso, al cónyuge y a los hijos menores de edad.
El nombre carece de significación económica y, por tanto, se halla fuera del comercio de los hom
bres. El nombre es un derecho inalienable, Inembargable e imprescriptible. De allí que el Art. 27 C.C.
señala que es “nulo” el convenio relativo al nombre de una persona natural. Sin embargo, se puede
permitir el uso temporal del nombre para fines publicitarios, de interés social y los que establece
la ley. Aquí se trata sólo de la posibilidad de permitir el uso temporal del nombre de una persona
notorlay popular para, a través del prestigioy simpatía que Inspira la persona que lo detenta (Mara
dona, Boris Becker, Pelé) promover la venta de un producto en una sociedad de consumo.
Protección jurídica del nombre:
Acción de reconocimiento del propio Nombre (Art. 26 C.C.)
Cuando a una persona no se le ha designado por su nombre, ésta puede exigir a través del
poder judicial que cese esta violación y exigir la Indemnización que corresponda. El monto de
la indemnización, como se trata de un daño moral a la persona lo establece el Art. 1985 C.C. El
Código Civil no se ha puesto en la hipótesis de Impedir una posible violación. Esta deficiencia
se puede suplir a través de la acción de garantía, el proceso constitucional de Amparo.
Acción de recuperación del Nombre (Art. 28 C.C.)
Aquí la violación del derecho al nombre es diferente: se usurpa el nombre de otra persona.
Cuando se utiliza el nombre que no le corresponde; el afectado tiene derecho a exigir la cesa
ción de esta usurpación y obtener la Indemnización que se determinará según el Art. 1985 C.C.;
porque se trata de un daño a la persona.
