UBILEX
H 6. Uso del Apellido
1. Tratándose de hijo matrimonial; corresponde el primer apellido del padre y el primer
apellido de la madre (Art. 20 C.C.).
2. Tratándose de hijo extramatrimonial; se dan dos casos (Art. 21 C.C.).
Si un sólo progenitor lo ha reconocido.- Entonces le corresponde ambos apellidos
del progenitor.
Si ambos progenitores lo han reconocido. El hijo lleva el primer apellido del padre y
el prim erapellido de la madre.
3. El Adoptado.- Puede darse dos situaciones (Art. 22).
Que adopte sólo una persona.- Entonces el hijo lleva los apellidos del adoptante.
Que lo adopten una pareja.- El adoptado llevará el primer apellido del padre adop
tante)/ prim erapellido de la madre adoptante.
4. El recién nacido cuyos progenitores son desconocidos debe ser inscrito con el nombre
adecuado que le designe el registrador del estado civil (Art. 23 C.C.). Toda persona tiene
derecho y deber al nombre.
5. La mujer casada tiene el derecho a llevar el apellido del marido agregado al suyo y a con
servarlo mientras no contraiga nuevo matrimonio, se produzca el divorcio o nulidad de
m atrim onio (Art. 24 C.C.). El C.C. considera que el derecho de la mujer a llevar el apellido
del marido es una facultad; por lo tanto, la mujer puede conservar sus apellidos; o puede
añadirse el apellido del marido.
Cuando se produce la separación de cuerpos, la mujer conserva de llevar el apellido del mari
do. En caso de controversia (el marido se oponga) lo decidirá el juez.
La Prueba del Nombre (Art. 25 C.C.) La prueba del nombre resulta de su partida de inscripción
en los registros de estado civil. En dicha partida también se registra el cambio o adición del
nombre permitido por la ley.
Cambio de Nombre: Por regla general no se permite la modificación o el cambio de nombre.
Sin embargo; por excepción, se permite esta adición o cambio se deba a razones justificadas y
mediante autorización judicial.
Las razones justificadas son:
- Si es que el nombre tiene una significación ridicula.
- Si el nombre es contrario al sentimiento religioso: Ateo: Aticio.
- Si tiene un significado ideológico.
- Si tiene en nuestro idioma una difícil pronunciación.
Este cambio o adición del nombre no altera la condición civil (marido, deudor, acreedor, etc.)
de quien lo tiene, ni constituye prueba de filiación (Art. 30 C.C.).
La persona perjudicada porel cambio de nombre puede impugnarla judicialmente (Art. 31 C.C.).
El seudónimo: El seudónimo es un medio de individualización que se utiliza para una deter
minada actividad de la persona, ya sea esta artística, literaria, teatral, cinematográfica (Ma-
