Tema 1: Temas com unes a la especialidad: Civil, Familia y Comercial
donna, Thalía, etc.) en tanto el seudónimo cumple la función identificadora, la ley lo protege
en los mismos términos que el nombre (Art. 32 C.C.) Se le aplican todos los artículos que regu
lan al nombre; en lo que corresponda.
7. Domicilio
La persona, en su vida de relación jurídica, necesita ser ubicada en un lugar determinado. El
domicilio es el asiento jurídico de la persona, su sede legal, el territorio donde se le encuentra
para imputarle posiciones jurídicas (cónyuge, acreedor, deudor, etc.), para atribuirle derechos
o deberes.
Se debe distinguir, domicilio, residencia y morada. El dom icilio lo determina la ley, es un cri
terio jurídico. La residencia es el lugar donde normalmente vive la persona con su familia, es
un criterio fáctico. La habitación o morada es el lugar donde temporalmente se encuentra una
persona.
Según el artículo33 del C.C., el domicilióse constituye por la residencia habitual de la persona;
por lo tanto, el Código establece que existe el dom icilio cuando hay residencia habitual. El
criterio jurídico concuerda con el fáctico.
A. Clases:
- Domicilio General: Es aquel que se aplica para la generalidad de posiciones ju ríd i
cas, de derechosy obligaciones. El domicilio general puede ser:
Domicilio Real.-Es el lugar de residencia habitual de una persona. Donde vivimos.
Domicilio Legal- Es el domicilio impuesto por la ley. Así los incapaces tienen por do
micilio el de sus representantes legales (Art. 37 C.C.), el domicilio de las personas
jurídicas donde lo establece su estatuto.
- Domicilio Especial: Es un domicilio excepcional, para específicas situaciones ju ríd i
cas. Para específicos derechosy obligaciones. Puede ser:
Domicilio Contractual: Es el que señala para la ejecución del contrato: el domicilio
donde se entrega el bien, donde se cumple la obligación.
Domicilio Procesal: Es el domicilio que señalan las partes en el proceso, con la fin a li
dad de que sean notificados. El Art. 424 Inc. 2 C.RC., considera el señalamiento del
domicilio procesal como un requisito de la demanda.
- Domicilio Real: Tradicionalmente se considera al domicilio real con dos elementos:
Un elemento objetivo.- Que es el lugar de residencia habitual de una persona, donde
vive regularmente, donde se encuentra habitual mente una persona.
Un elemento subjetivo.- El “animus”de pertenencia de una persona en un determinado
lugar. El considerarlo como lugar habitual de residencia.
El Código Civil sólo ha considerado “el domicilio real” bajo su aspecto objetivo, no
se requiere para que haya domicilio ningún “animus”de pertenencia de una persona
en un determinado lugar. El lugar donde se encuentra habitualmente una persona
basta determinar el domicilio real (Art. 33 C.C.).
