io ^ o ly n ía rio . Cada quien fija su domicilio.
Es muíabie. Cualquier persona puede variar su domicilio.
Es inviolable. Constituye una garantía constitucional (Art. 2 Inc. 9 Const.); y la vulne
ración del derecho a la inviolabilidad del dom icilio es sancionable penalmente.
Clases de Domicilio Real
i) Domicilio Unitario: Consiste en un solo lugar donde reside habitualmente una per
sona (Art. 33 C.C.).
i i) Domicilio Múltiple: Considera varios lugares el dom icilio de una persona. Una per
sona puede tener varios domicilios. Una persona puede vivir alternativamente re
sidir en un lugar y trabajar habitualmente en otro lugar, el C.C. considera a ambos
como domicilio. El Art. 35 C.C. señala que es factible que una persona tenga varios
domicilios reales.
iii) El Domicilio Conyugal: Es un ti pode dom icilio real. El dom icilio conyugal es el lugar
donde habitualmente viven los cónyuges juntos. Si los cónyuges se han separado,
se considera como domicilio conyugal el últim o lugar donde vivieron juntos (Art. 36
C.C.).
Domicilio Legal: El domicilio legal lo establece la ley, aunque muchas veces no sea el lugar
habitual de residencia de una persona no sea su dom icilio real. Tal es el caso de:
Los incapaces tienen por domicilio el desús representantes legales (Art. 37 C.C.. Portanto;
el dom icilio del incapaz será el domicilio del tutor o curador).
Los funcionarios públicos (Ministros, Viceministros, etc.) están domiciliados en el lugar
donde ejercen sus funciones (el Ministerio, el Palacio de Gobierno, Congreso, etc.) (Art. 38
C.C.).
Las personas que se encuentran temporalmente en el extranjero, ya sea en ejercicio de
funciones del Estado o por otras causas (negocios, becas, etc.) se consideran domiciliadas
en el últim o domicilio que hayan tenido en el territorio nacional.
Las personas jurídicas se entienden domiciliadas en el lugar que establece su estatuto.
Cambio de Domicilio: El cambio de domicilio real (residencia habitual) se produce sólo con
el hecho de traslado de la residencia habitual a otro lugar Art. 39 C.C. El cambio de domicilio
es un hecho, basta con cambiar de residencia, y se entenderá domiciliada a la persona en este
nuevo lugar.
Cuando exista una relación obligacional (acreedory deudor) el cambio de dom icilio del deu
dor no se puede hacer valer el acreedor, salvo que el deudor hubiera puesto en conocimiento
de manera indubitable al acreedor, del cambio del domicilio. Ejemplo. “A” le debe a "B” 2,000
dólares, pero súbitamente “A” cambia de domicilio sin comunicar a “B”, éste demanda a “A” en
su antiguo domicilio, este domicilio será válido, ya que "A” no comunicó a “B”, la consecuencia
es que “A”, se entenderá comoque ha sido modificada.
