260 BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 261 of 1506 --

Tema 1: Temas com unes a la especialidad: Civil, Familia y Comercia
Personas que no tienen residencia habitual (Art. 32C.C.): Toda persona tiene domicilio, es un
derecho y un deber; las personas que no tienen lugar de residencia habitual, tienen también
domicilio; es el lugar donde se encuentren.
8. Fin de la persona
Muerte: El art. 61 del C.C. declara, en términos generales, que la muerte pone fin a la persona.
De este modo se incluye la muerte natural como la declaración de muerte presunta, con la
diferencia de que en la muerte presunta puede presentarse la declaración de existencia.
La muerte termina con la calidad de sujeto de derecho inherente a la persona natural. Con la
muerte ya no existe la persona,y por lo tanto ya no es centro de derechosy obligaciones. Y de
acuerdo con el Art. 660 del C.C., desde el momento de la muerte se transmiten a los sucesorios
los bienes, derechosy obligaciones que constituyen la herencia.
Efectos de la muerte: La muerte origina múltiples efectos jurídicos que van desde la disolu
ción del m atrim onio hasta la apertura de la sucesión, mediante la herencia (bienes, derechos
y obligaciones).
Empero, si bien la muerte pone fin a la persona se puede proteger la confidencialidad y me
moria de fallecido por parte de los familiares.
A pesar del hecho de la muerte y su consiguiente efecto jurídico comprobamos que existe
cierta continuidad de la persona a través de sus bienes, mediante su voluntad plasmado en un
testamento o en un acto constituido de una fundación. Esta voluntad plasmada, expresada en
vida, se prolonga más allá de la muerte, más allá de la extinción de la persona.
Criterios para determinar el momento de la muerte:
M uerte Clínica. La muerte clínica se da cuando cesa la actividad cerebral, aun cuando otras
células permanecen vivas. Es la muerte cerebral.
M uerte Biológica. Significa la desaparición definitiva de vida a nivel de célulasy tejidos.
La posición adoptada por el Código Civil de 1984 según Fernández Sessarego es el criterio
de la muerte clínica o cerebral.
Situaciones en los cuales no se puede determinar qué la persona murió prim ero:
Saber cuándo.murió primero una persona trae: notables consecuencia de índole hereditaria. Cuando
es posible determinar que la persona murió primero entonces si hay transmisión de derechos heredi
tarios, si hay sucesión; Pero ¿Qué pasa cuando no se puede-.probar.-0determinar qué persona murió :
primero? Por ejemplo, en un accidente de tránsito muchas veces no se puede determinar qué persona murió
primero cuando se trata de una familia. Este problema tiene dos soluciones;
:Premoriencia: Si no se puede determinar qué persona murió primero, se determina quién murió primero por
razones de: sexo, edad. Así en un accidente se entiende que.muríó primero eí hijo, después de madre y último
el marido,: Esta solución:está en contra de la igualdad ante la Ley que señala la Constitución,
Connióriencia: Sí no se puede determinar que la persona murió primero se entiende que todos: murieron al
mismo tiempo y. entre ellos no hay transmisión de derechos hereditarios. Así en un accidente toda la familia
murió al mismo tiempo y entre los fallecidos no hay transmisión de derechos. Esta es la posición adoptada
por el Código Civil de 1984.
