| 9. Declaración de muerte presunta
La declaración de muerte presunta es una solicitud que se presenta ante el juez para que de
clare judicialmente que frente a determinados hechos hay alto grado de certeza que la perso
na está fallecida.
La declaración de muerte presunta tiene los mismos efectos de la muerte, con la única dife
rencia que en la muerte natural no existe el reconocimiento de existencia. En la muerte natu
ral hay certeza que la persona ha fallecido, en la declaración de muerte presunta hay un alto
grado de certeza que la persona está fallecida. En la declaración de muerte presunta, no se
requiere que previamente se haya declarado ausente a la persona.
Situaciones en lasque se pueden configurar ia muerte presunta:
