La declaración de muerte presunta se tram ita a través de un proceso no contencioso (Art. 749
inc. 5 del Código Procesal Civil) Puede solicitarlo:
1) Cualquier interesado-fam iliares, etc.
2) El Ministerio Público de oficio.
En la resolución que declara la muerte presunta debe contener la fecha probable de la muerte;
y si es posible el lugar (Art. 64 C.C.).
El juez puede declarar improcedente la demanda de declaración de muerte presunta, porque
no se verificó el plazo, no se han producido los hechos de los Inc. 2y 3 del Art. 63 C.C.
Efectos de la Declaración de muerte presunta: La declaración de muerte presunta produce
todos los efectos de la muerte natural: desde la disolución del matrimonio hasta la apertura
de la sucesión.
La única diferencia es que en la declaración de muerte presunta se puede presentar el reco
nocimiento de existencias; y quedar sin efecto ciertos aspectos de la declaración de muerte
presunta.
Reconocimiento de existencia: El reconocimiento de la existencia sólo procede cuando se
trate de declaración de muerte presunta. La persona que reaparece está en aptitud de solicitar
la declaración del reconocimiento. Para tal efecto debe aportar la prueba de la supervivencia.
El reconocimiento de la existencia se readquiere la categoría de sujeto de derecho, la única
prueba que se debe acreditar es el de la supervivencia.
El reconocimiento de la existencia es un proceso no contencioso (Art. 794 del C.PC.) Como
única prueba se requiere acreditar la supervivencia. Para ello no se requiere sólo la presencia
262 BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 263 of 1506 --

Tema 1: Temas com unes a la especialidad: Civil, Familia y Comercial
física, sino también una manera idónea que reivindique sus derechos o también nombrando
un representante con posterioridad a la declaración de muerte presunta. Pueden solicitar el
reconocimiento de la existencia:
1) La persona que ha sido declarada presuntamente muerte.
2) Cualquier interesado. Ejemplo: su representante, etc.
3) De oficio por el Ministerio Público.
Efectos del reconocimiento de la existencia:
Si la declaración de muerte presunta produce los efectos de la muerte natural. El reconoci
miento de la existencia busca dejar sin efecto la declaración de muerte presunta.
En lo que respecta al matrimonio, si el cónyuge ha contraído nuevo matrimonio, éste permanece váli
do a pesar del reconocimiento de existencia. Pero si el cónyuge no ha contraído matrimonio, este
permanece válido (Art. 68C.C.).
En lo que respecta a los bienes. Se deja sin efecto la sucesión, y los bienes retornan a posesión del
propietario en el estado que se encuentren en el momento que se produce la declaración (Art.
69C.C.).
El juez debe apreciarla buenay mala fe de las personas que adquirieron los bienes. Si se actuó de buena
fe, el reconocido no podrá solicitar el retorno de los bienes enajenados. Si se actuó de mala fe
el reconocido puede solicitar su reivindicación.
Los actos de disposición y de gestión por los derechos del muerto presunto son firmes; aunque el decla
rado existente puede reemplazara los herederos en las relaciones obligaciones constituidas
durante el tiempo de su declaración de muerte presunta.
10. Personas jurídica: Tipos. Representación. Fin o extinción de la persona
La persona jurídica: Es la organización de personas naturales que persiguen fines valiosos y
que constituye un centro unitario ideal de imputación de situaciones jurídicas - derechos y
deberes- con autonomía formal en relación con las personas que la integran.
Por otro lado, es necesario señalar, que la persona jurídica viene a constituir un privilegio con
cedido por el ordenamiento jurídico a una determinada colectividad destinada a cum plir cier
tos fines coexistenciales que la persona natural que no puede o no desea cum plir en forma
individual.
Así podemos distinguir dos tipos dentro de las asociaciones de personas:
a) Agrupaciones que constituyen personas jurídicas sin finalidad económica, dentro de las
cuales tenemos a las asociaciones, comités y fundaciones reguladas por el Código Civil.
b) Personas jurídicas constituidas con una finalidad propiamente económicas, tales como
las sociedades civilesy mercantiles, reguladas porla Ley General de Sociedades N°26887,
las cooperativas, reguladas por la Ley General de Cooperativas, Decreto Legislativo N° 85
que actualmente cuenta con un TUO aprobado por D.S N° 074''90-TR,y las Empresas In
dividuales de responsabilidad Limitada, normadas mediante el Decreto ley N°2i62i.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 264 of 1506 --

UBILEX	I
El Código Civil al regular a las personas jurídicas, no pretende abarcar todas las personas ju
rídicas, sino específicamente a las personas jurídicas de derecho civil, aquellas que son aptas
para realizar los fines no lucrativos y se trata de la asociación, la fundación y el comité.
10.1. Teorías sobre Sa concepción de la Peisona Jurídica
Teoría de la Ficción: La teoría de la ñcción, que fue insinuada por Cini baldo del Fieschi y siste
matizada de una manera conclusa y definitiva por Savigny, parte de la idea de que el único su
jeto natural de derechos y obligaciones jurídicas es el hombre. Sólo éste es capaz de voluntad
y, por consiguiente, sólo él puede ser naturalmente sujeto de derechos.
Esta doctrina dominó en la ciencia jurídica prácticamente sin contradictores, hasta la segun
da m itad del siglo pasado, recién entonces los juristas se ensañaron contra ella, haciéndola
objeto de los más duros ataques (Borda, Guillermo A “Manual de Derecho Civil parte general
p.306).
La teoría de la ficción ha sido calificada de ineficaz, ilógica e insuficiente, porque, según los
críticos, la ficción no explica los hechos reales que se producen con motivo de la personalidad
de existencia ideal.
Teoría negatoria de la personalidad: Quienes niegan la teoría de la ficción por entender que
ésta no explica los fenómenos que se observan en el derecho, en este punto, llegan, pues a
una teoría negatoria. Pero para fundarla deben explicar cómo es que se producen estos fenó
menos,ya que no admiten que se deban a la existencia de una persona. De ahí que las teorías
negatorias sean varias: (Cit. R11)
Patrimonios de afectación: “al gunas de las personas jurídicas no son otra cosa que patrimonios
afectados al cumplimiento de ciertos fines (Brinz, Bekker).
Ihering, porsu parte, piensa que los verdaderos sujetos de los derechos de una persona moral
son sus miembros, puesto que ellos son los beneficiarios y destinatarios de la utilidad que
el patrimonio puede rendir. Las personas jurídicas serían sujetos aparentes que ocultan a los
verdaderos (Borda p.307)
Propiedad colectiva: Planiol sostiene que la llamada persona de existencia ideal no es sino una
forma de propiedad colectiva, que existe en derecho moderno paralelamente a la propiedad
individual. Es análoga al condominio, pero se diferencia de éste en que la llamada persona de
existencia ideal supone la propiedad colectiva de varias personas consideradas como si fuesen
una sola en cuanto al ejercicio de su derecho; en tanto que en el condominio se considera a
cada una dueña de una cuarta parte. Esta tesis es seguida también por Berthélemy
Negación del Derecho Subjetivo: Duguiten suteoría, niega la existencia de derechos subjetivos,
y por lo tanto la de sujetos de derechos. En consecuencia, el problema acerca de la naturaleza
de la persona de existencia ideal viene a quedar disipado ni ésta, ni las personas humanas
son sujetos de derecho. Todos los hombres están sometidos a regla de interdependencia en
miras a la solidaridad social. Los actos que realicen con arreglo a ellas deben ser reconocidos y
protegidos,y entre ellos pueden figurar los que se realicen en corporaciones, fundiciones, etc.”
(Arauz Catex, Manuel, Oh. Cit. p. 12).
264 BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y N O M B R A M IEN TO DE JUECES Y FISCALES

-- 265 of 1506 --

isma 1: Te m as co m unes a la especialidad: Civil, Familia y Com ercial
Teorías de la Realidad- Doctrinas que han tenido el mayor auge y difusión en épocas recien
tes creen ver en la persona de existencia ideal elementos "reales" (y no ficticios) que permiten
afirmar (y no negar) su existencia. Este planteamiento impone concretar en qué consiste esa
realidad; y en este trance los autores divergen; por eso las teorías son varias. Las agrupamos
para reseñarlas.
Teorías Voluntaristas.- Un primer grupo sostiene que estas personas son reales en cuan
to tienen una voluntad distinta de la de sus miembros. El conjunto de éstos, formando
asambleas, votando conforme a reglas, o delegando su actuación en representantes, crea
o emite una voluntad jurídica única y nueva, que es una realidad. Representan esta ten
dencia Jellnek, Zitelman y los sociólogos organicistas (que comparan la persona ideal con
un organismo cuyas células serían hombres)
Teorías del Interés.- Un segundo grupo, de juristas, sostiene que las personas llamadas
ideales son reales, porque tienen un interés distinto del de sus miembros. Michoud
aduce que los que interesa en estas personas no es tanto la voluntad abstracta: “ No
se puede querer, sin querer alguna cosa”; he ahí el interés protegido. SaleiIles, segui
do entre otros por Barcia López, destaca la existencia de “un poder puesto al servicio
de intereses de carácter social”. Ferrara advierte que “persona” no significa "hombre”, y
sostiene que el Estado puede acordar personalidad a cualquier cosa, entre o figura del
intelecto (llega a decir que hasta podría acordársela a un número), pero sólo la acuerda
a entes que satisfagan intereses humanos; en una asociación de hombres hay una uni
dad "plástica, viviente”, que el derecho transforma en unidad jurídica.
Teoría de la Institución.- Un tercer grupo, partidario de la teoría de la institución (de vas
to alcance en la sociologíay en el derecho), cree resolver mediante ella el problema de la
persona de existencia ideal. La institución es "una idea de obra o de empresa, que se rea
liza”. Al ponérsela en práctica, quienes, partan de ella organizan un poder, mediante ór
ganos, y por lo tanto dicen la idea existe en el medio social; se ha vuelto eficiente porque
inspira actos concretos. La institución es por eso real, y es el sujeto de derecho. Esta teoría,
de base platónicay berjoniana, fue creada por Hauriay seguida por Renardy Délos.
Teoría normativas o teoría de Kelsen: Para el ilustre jusfilósofo vienes “persona” no es una
ficción ni una realidad, sino un concepto (o ser una representación del entendimiento). Este
concepto alude el térm ino de la imputación que hacen las normas jurídicas, es decir, el centro
al cual se imputa una serie de acciones humanas normativamente pensadas.
Las normas hablan de comprar, percibir frutos, pagar, etc. Pero ¿quién es el que en cada norma
compra, percibe frutos, paga? La “persona”. No sabe, pues, distinguir entre persona de exis
tencia visible o ideal. Allí donde hay una “persona”; con esto se agota en la teoría de Kelsen el
concepto jurídico de "persona” (Areux Cetex, Manuel, Ob. cit. p. 141).
Visión tridimensional de la persona jurídica: La aplicación de la teoría tridimensional del de
recho al caso concreto de la "persona jurídica” permite distinguir en ella, en interacción diná
mica, tres dimensiones que se exigen recíprocamente para dar cuenta de su plena realidad.
En principio, y como se ha advertido, la “persona jurídica” requiere primariamente, como cual
quier otra institución, de un substrato humano, el que está compuesto por las personas que
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN I
Y N O M B R AM IEN TO DE JUECES Y FISCALES

-- 266 of 1506 --

UBILEX
la constituyen e integran. Sin la presencia actuante de estos seres humanos es imposible ima-
ginarla o concebirla. Se trata de la dimensión sociológica-existencial de la “persona jurídica”.
El grupo humano, que constituye primariamente la “persona jurídica”, actúa organizadamente
para lograr un fin o un conjunto de fines valiosos. Es este fin valioso, vivenciado porcada uno
de sus componentes, el que aglutina a la comunidad de personas y otorga un sentido a su
específica actividad. Percibimos así la dimensión axiológica de la “persona jurídica”.
La “persona jurídica”, en cuanto organización de personas que persigue fines valiosos, requiere
que mediante un recurso propio de la técnica jurídica se le considere, pese a su pluralidad exis-
tencial, como una unidad formal para el efecto de lograr que los actos jurídicos que realizan
sus miembros no se les impute a cada uno de ellos, en forma inm ediatay directa, sino que se
atribuyan a un centro ideal de referencia de situaciones jurídicas subjetivas. La “persona jurídi
ca" tiene una especial regulación normativa. Esta constituye su dimensión formal-normativa.
La “persona jurídica”, como está dicho, es el resultado de la interacción dinámica de sus di
mensiones sociológico-existencial, axiológica y formal-normativo. Para comprenderla unita
riamente no es posible prescindir de alguna de ellas ya que, de hacerlo, tendríamos tan sólo
una visión recortada, parcial y fragmentaria de la misma. El Código Civil peruano de 1984 ha
recogido la visión tridimensional de la “persona jurídica". Ello se pone de manifiesto a través
del texto de los artículos 80o, 90o, in ° y 134o, en lo que se describe a la asociación, la fundación
el comité y la comunidad campesina y nativa, respectivamente. En todos ellos se hace refe
rencia a que cada una de dichas “personas jurídicas” es una organización de personas que se
propone fines valiosos de carácter no lucrativo.
En el artículo 78ose hace alusión a la dimensión formal-normativa cuando se establece que la
"persona jurídica” tiene existencia distinta de sus miembros, por lo que ninguno de éstos, ni
todos ellos, tienen derecho al patrimonio de ella ni están obligados a satisfacer sus deudas. En
concordancia con lo dispuesto en el articulado citado en el párrafo anterior, debe entenderse
que dicha distinción es sólo formal y, como un recurso de técnica jurídica, opera exclusiva
mente para la atribución de situaciones jurídicas subjetivas a un centro ideal de referencia
formalmente “distinto” de sus miembros.
10.2. Tipos de personas jurídicas reguladas en el Código Civil
En el Código Civil se regulan:
La Asociación (Art. 80 al 98).
La Fundación (Art. 99 al n o).
El Comité (Art. 111 al 123).
Las Comunidades Campesinas (Art. 134 al 139).
En el mismo Código se regula la asociación, fundación y comité no inscritos.
A. La asociación
El artículo 80 del Código Civil señala que la asociación es una organización estable de perso
nas naturales o jurídicas, o de ambas, que a través de una actividad común persigue un fin no
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y N O M B R AM IEN TO DE JUECES Y FISCALES

-- 267 of 1506 --

Tema 1: T e m as co m unes a la especialidad: Civil, Familia y C om ercial
lucrativo, y es en base a esta definición de la citada disposición normativa que podemos es
tablecer asociaciones deportivas, religiosas, culturales, etc, e incluso puede ser utilizada para
representatividad de gremios empresariales o sindicales, buscando la tutela de sus interesesy
su representatividad frente al Estado1.
Las personas naturales tienen amplia libertad no solo para formar personas jurídicas, como
es el caso de la asociación, sino también el derecho de desvincularse de ellas. En la STC 2389-
2009-AA/TC (Fj. 19), el supremo intérprete de la Constitución precisa la doble dimensión del
derecho de asociación en los siguientes términos:
“a. Una dimensión positiva que abarca las facultades de conformar asociaciones (derecho
a formar asociaciones), la de afiliarse a las organizaciones existentes y la de permanecer
asociado mientras no se incumplan las normas estatutarias.
Dentro de la facultad de conformar organizaciones, se encuentra comprendida la posi
bilidad de estructurar, organizar y poner en funcionamiento la asociación (principio de
autoorganización), la que se materializar a través del estatuto, que debe establecer como
mínimo reglas acerca del comportamiento exigido a los socios y de las cargas que se les
imponen, así como de los derechos que pueden ejercery, por supuesto, sobre la manera
de term inar el vínculo con la asociación, por parte del afiliado, y de excluir al socio, por
parte de la asociación.
En este contexto, puede señalarse que el ejercicio del derecho de asociación supone un
número plural de personas que acuerdan de manera autónoma, libre y espontánea la
creación de un ente a través del cual realizarán un proyecto de interés, propósitos, ideas o
metas colectivo, común, pacífico y lícito.
Desde esta perspectiva, este Tribunal considera que el derecho de asociación se concre
ta en la existencia de personas jurídicas, libres y capaces para ejercer derechos y con
traer obligaciones, a fin de responder autónomamente porsudevenirsocial, en aras de
lograr la satisfacción de un interés u objetivo común, no siempre ligado a la obtención
de lucro.
b. En su dimensión negativa, comprende la facultad de toda persona para negarse a form ar
parte de una determinada asociación, así como el derecho a no ser obligado a integrar
una asociación o el derecho a no seguir asociado contra su voluntad o retirarse de una,
cuando así lo desee”. (V Pleno Casatorio Civil. Fj. 22)
Órganos de gobierno: La persona jurídica ostenta la capacidad de goce y la de ejercicio. Sin
embargo, para que la capacidad de ejercicio sea real, debe hacerse a través de los órganos que
integran a dicha persona.
i) La Asamblea General (Art. 84 C.C.): La Asamblea General es el órgano de decisión, con
formado por la totalidad de los asociados que constituyen la persona jurídica. La calidad
de órgano supremo que el Código atribuye a la Asamblea General le confiere las máximas
facultades para dirigir la actividad social, sin interferir con aquellas facultades específica
mente otorgadas a otros órganos sociales.
1 V Pleno Casatorio Civil. FJ. 72.
