Y N O M B R AM IEN TO DE JUECES Y FISCALES

-- 268 of 1506 --

UBILEX
La competencia de la Asamblea General de asociados es indelegable, al ser acuerdos de
competencia exclusiva, por la trascendencia de los acuerdos a adoptarse. (V Pleno Casa-
torio Civil Fj. 75)
Convocatoria a Asamblea General: La asamblea general es convocada por el presidente del
consejo directivo de la asociación, en los casos previstos en el estatuto, cuando lo acuer
de dicho consejo directivo o cuando lo soliciten no menos de la décima parte de los aso
ciados.
Excepcionalmente convocará el presidente cuando lo soliciten no menos de la décima
parte de los asociados. Entendemos que este caso podría justificarse por el mérito del
petitorio o por situaciones trascendentes que atañen la marcha de la institución.
Finalmente, si la solicitud de los asociados no es aceptada dentro de los quince días que
siguen a su presentación o es denegada, la convocatoria la formulará el juez en lo civil a
mérito de la sentencia ejecutoriada recaída en el proceso sumarísimo.
Quorum-. De acuerdo al Art. 78 C.C., la voluntad de la asociación se forma en la Asamblea
General, y se expresa en la adopción de acuerdos, los cuales se obtienen a partir de mayo
rías y quorums establecidos por la ley.
En principio, el quorum debe estar reglado por el estatuto. Supletoriamente, se aplicarán
las normas del Art. 87 del C.C., en el cual se señala que "para la validez de las reuniones
de Asamblea General se requiere, en primera convocatoria, la concurrencia de más de la
mitad de los asociados. En segunda convocatoria, basta la presencia de cualquier número
de asociados. Los acuerdos se adoptan con el voto de más de la mitad de los miembros
concurrentes.
Para m odificar el estatuto o para disolver la asociación se requiere, en primera convo
catoria, la asistencia de más de la m itad de los asociados. Los acuerdos se adoptan con
el voto de más de la m itad de los miembros concurrentes. En segunda convocatoria, los
acuerdos se adoptan con los asociados que asistan y que representen no menos de la
décima parte.
Cada asociado tiene un solo voto, buscando con ello evitar el entorpecimiento de la mar
cha de esta persona jurídica y con ello el inmovilismo, que justamente es contrario a su
establecimiento y promoción; toda vez que su existencia se debe a la confluencia de es
fuerzos a fin de dinamizar el entramado social en aras de un fin altruista. (V Pleno Casa-
torio Civil Fj. 78)
i i) El Directorio o Consejo Directivo: Directorio, órgano colegiado de la asociación queseen-
carga de la elaboración y dirección de los planes destinados al logro de los fines sociales.
Sus atribuciones y obligaciones se fijan en el estatuto.
iii) La Gerencia: Es el órgano encargado de la ejecución de los planes diseñados por el direc
torio. Generalmente, es el que ostenta la representatividad de la asociación, siempre que
le sea atribuida en asamblea general de asociados o en consejo directivo y por escritura
pública, la cual debe ser inscrita en el registro de poderes y mandatos de los Registros
Públicos.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y N O M B R AM IEN TO DE JUECES Y FISCALES

-- 269 of 1506 --

Tema 1: Te m as co m unes a la especialidad: Civil, Familia y Com ercial
iv) El Consejo de Vigilancia: Es el órgano de control de la asociación. Su misión es fiscalizar
los actos realizados por los otros órganos de decisión y dar cuenta a la junta general de
asociados de tales actividades.
B. La fundación
El artículo 9 9 ° del Código Civil define a la fundación como “una organización no lucrativa insti-
tuida mediante la afectación de uno o más bienes para la realización de objetivos de carácter
religioso, asistencial, cultural u otros de interés social”.
Características:
La fundación nace de un acto de liberalidad, unilateral y tiene características propias: i) es un
acto de disposición, pues sólo nace si el fundador aporta todo o parte de su patrimonio, ii)
es un acto de organización, pues el fundador organiza a las personas (generalmente terceros
distintos a él) para que velen por el patrimonio y lo apliquen para los fines de interés social
señalado para su constitución.
Por tanto, es"(...) una organización creada para la gestión de un patrimonio autónomo desti
nado y vinculado de manera tendencialmente perpetua a la obtención de un fin socialmente
relevante preestablecido por el fundador (,..)”2, en ello estriba el carácter no lucrativo de este
sujeto de derecho; toda vez que la afectación del patrimonio está destinado a la consecución
de un fin valioso fijado de antemano por el titu lar o fundador, el cual es ineludible para el
logro de su finalidad.
Órganos:
Consejo de Supervigilancia de Fundaciones: El Consejo de Supervigilancia de Fundaciones es
la organización administrativa encargada del control y vigilancia de las fundaciones.
Su integración y estructura se determinan en la ley de la materia.
El Consejo de Supervigilancia de Fundaciones ejerce las siguientes funciones básicas:
1. Indicar la denominación y domicilio de la fundación, cuando no consten del acto constitutivo.
2 . Designar a los administradores cuando se hubiese om itido su nombramiento por el fun
dador o sustituirlos al cesar por cualquier causa en sus actividades, siempre que no se
hubiese previsto, para ambos casos, en el acto constitutivo la forma o modo de reempla
zarlos.
En el caso previsto en el párrafo anterior, están impedidos de ser nombrados como ad
ministradores de las fundaciones, los beneficiarios o los representantes de las institu
ciones beneficiarías. Asimismo, en dicho supuesto, el cargo de adm inistradores indele
gable”.
3 . - Determinar, de oficioy con audiencia de los administradores o a propuesta de éstos, el ré
gimen económicoy administrativo, si hubiere sido om itido porel fundador, o modificarlo
cuando impidiese el normal funcionamiento o conviniere a los fines de la fundación.
2 BRECIA, Humberto y otros. Op., cit., p. 256.
BALOTAR 10 DESARROLLADO PARA LOS EXÁM ENES ESCRITOS DE SELECCIÓN
Y N O M B R AM IEN TO DE JUECES Y FISCALES 269

-- 270 of 1506 --

UBILEX
4 . - Tomar conocimiento de los planes y del correspondiente presupuesto anual de las fun
daciones, para lo cual éstas elevan copia de los mismos al Consejo al menos treinta días
antes de la fecha de iniciación del año económico.
5. - Autorizar los actos de disposición y gravamen de los bienes que no sean objeto de las ope
raciones ordinarias de la fundación y establecer el procedimiento a seguir, en cada caso.
6 . - Promover la coordinación de las fundaciones de fines análogos cuando los bienes de és
tas resulten insuficientes para el cumplimiento del fin fundacional, o cuando tal coordi
nación determinase una acción más eficiente.
7. - Vigilar que los bienesy rentas se empleen conforme a la finalidad propuesta.
8 . - Disponer las auditorías necesarias.
9. - Impugnar judicialmente los acuerdos de los administradores que sean contrarios a ley
o al acto constitutivo o demandar la nulidad o anulación de los actos o contratos que
celebren, en los casos previstos por la ley. La impugnación se tram ita como proceso abre
viado; la demanda de nulidad o de anulación como proceso de conocimiento.
10. - Intervenir como parte en los juicios en que se impugne la validez del acto constitutivo de
la fundación.
11. - Designar al liquidador o a los liquidadores de la fundación a falta de disposición en el acto
constitutivo.
12. - Llevar un registro administrativo de fundaciones.
C. El comité
El artículo 111o del Código Civil define al comité “como la organización de personas naturales
o jurídicas, o de ambas, dedicada a la recaudación pública de aportes destinados a una fina
lidad altruista". Es decir, no tiene su patrimonio originado en el aporte de los integrantes ni
en la afectación patrimonial que hace el fundador. El propósito del Comité es precisamente
recolectar fondos públicos.
Características:
Organización de personas. Es una característica genérica de todas las personas jurídicas. Es
una organización de personas que representa a un grupo humano que lleva a cabo acciones e
ideas concertadas. Puede estar conformada por personas naturales o jurídicas o ambas.
Finalidad altruista. El Comité es un caso diferenciado de las demás personas jurídicas: no pro
cura riqueza o lucro. Se forman comités con el fin de prestar socorro en caso de calamidades,
para colaborar en la realización de obras comunitarias, con fines patrióticos o para ayudar a
las personas desvalidas o enfermas.
Procuración de aporte. A efectos de realizar sus fines u objetivo, el comité puede recaudar
aportes de todo género del público en general. Dichos aportes se recaudan a través de dife
rentes actividades lícitas, no contrarias a las buenas costumbres, a la moral o al orden público.
El acto constitutivo y el estatuto. Estos deben constar por escrito y, al mismo tiempo ser inscri
tos en el registro público correspondiente.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y N O M B R AM IEN TO DE JUECES Y FISCALES

-- 271 of 1506 --

Tema 1: Te m as co m unes a la especialidad: Civil, Familia y Com ercial
Registro del Comité. Debe mantener debidamente actualizados el nombre, domicilio, acti
vidad y fecha de admisión de los asociados; además, indicar los integrantes del directorio o
personas que lleven a cabo cualquier actividad administrativa.
Responsabilidad solidaria de los directivos. Los directivos tienen a su cargo la gestión del co
mité; por ello adquieren una especial responsabilidad sobre toda la sociedad. Esta respon
sabilidad es compartida en forma solidaria por todos los miembros del consejo directivo en
cuanto concierne a la mejor conservación y aplicación de los aportes adquiridos a los objetivos
propuestos.
Verificación del Ministerio Público. El Ministerio Público tiene la facultad, en defensa de la so
ciedad, de denunciar todo acto ilícito que atente contra el orden público, sus valores morales
y las buenas costumbres.
Órganos:
La Asamblea General: Es el órgano supremo del comité. Es la reunión de todos los inte
grantes en asamblea que ha de ser convocada en los casos previstos por el Estatuto. Esta
junta discute y toma acuerdos sobre las diferentes cuestiones que interesan a la vida del
comité.
Clases de Asamblea:
a) Asamblea ordinaria.- Es aquella que está establecida en el estatuto. Por lo menos,
deben llevarse a cabo tres asambleas ordinarias durante un año.
b) Asamblea Extraordinaria.- Es laque está prevista en el estatuto; es una asamblea de
emergencia para tratar asuntos que no pueden tener espera. La puede convocar el
presidente o el directorio
El Consejo Directivo: La conceptualización, así como las facultades del consejo directivo,
están contempladas en el Art. 114 del Código Civil, el cual establece: “El consejo directivo
es el órgano de gestión del comité,y es convocado por quien lo presida en los casos previs
tos en el estatuto o cuando lo solicite cualquiera de los miembros integrantes del consejo
o la décima parte de los miembros del comité. Si su solicitud fuese denegada o transcu
rren siete días de presentada sin efectuarse la convocatoria, se procede de conformidad
con los establecidos en el Art. 85”.
Responsabilidades del Comité:
Los miembros del consejo directivo del comité son responsables solidarios de la conservación
y debida aplicación de los aportes recaudados a la finalidad anunciada.
Los gestores del comité administran bienes aportados por la colectividad para beneficiar a
determinadas personas. Ni los aportantes ni los beneficiarios tienen participación alguna en
la gestión. Por eso, es importante que el Ministerio Público, en representación de los intereses
de la sociedad, ejerza vigilancia sobre el comité.
