D. Las •Gaimimsfecfes campesinas y naiwas
La Constitución Política contempla un régimen especial con miras al reconocimiento y a la
protección de las Comunidades Campesinasy Nativas, señalando:
“Artículo 8§ C - Las Comunidades -Campesinas'' y las1IMátivás tienen existencia legal'' y son personas juó
ridicas. Son autónomas en su organización, en el trabajo comunal y en el uso y la libre disposición de
sus tierras, así como en lo económico y administrativo, dentro del marco que la ley establece. La pro
piedad de sus tierras es imprescriptible, salvo en el caso de abandono previsto en el artículo anterior,
El Estado respeta la identidad cultural de las Comunidades Campesinas y Nativas."
Por su lado nuestro Código Civil en su Art. 134 establece que Tas comunidades campesinasy
nativas son organizaciones tradicionales y estables de interés público, constituidas por per
sonas naturales y cuyos fines se orientan al mejor aprovechamiento de su patrimonio, para
beneficio general y equitativo de los comuneros, promoviendo su desarrollo integral,”
Las comunidades campesinas y nativas están reguladas por legislación especial, la Ley N°
24656— Ley General de Comunidades Campesinas— reconoce a las Comunidades como ins
tituciones democráticas. En ese sentido, se les impone una organización basada en una asam
blea general en la que participan los Comuneros calificados y una Directiva Comunal elegida
periódicamente mediante voto personal, igual, libre, secreto y obligatorio, entre otras,
E. Las organizaciones no gubernamentales
Según Zabala M atulic las ONGs son aquellas “organizaciones de carácter social, independien
tes y autónomas, jurídicamente fundadas y que actúan sin finalidad de lucro. Su acción se
orienta hacia la Cooperación al Desarrollo y hada la búsqueda de acuerdos de ayudas entre
Gobiernos con el objetivo de provocar la sol¡daridady promover el desarrollo en los pueblosy
sociedades del Tercer Mundo”.
En tal sentido y de acuerdo a la definición presentada podemos determinar como caracterís
ticas Intrínsecas de las ONG las siguientes: i) Son Personas Jurídicas que actúan sin fines de
lucro, ii) Su objeto se centra fundamentalmente en aspectos promotores de desarrollo.
Clasificación y Regulación jurídica:
En nuestro ordenamiento legal no existe normatividad especial que regule a las organizacio
nes no gubernamentales de desarrollo ONGs. En este sentido debemos entender que su régi
men legal se fundamenta a través de lafigura de laasociación civil ode lafundación, personas
jurídicas que de acuerdo a nuestra legislación vigente actúan sin fines de lucro.
La denominación de ONG en el Perú tiene un reconocimiento legislativo a nivel de las normas
de Cooperación Técnica Internacional (Decreto Legislativo N °7i9 y su Reglamento). Concreta
mente se ha creado un registro administrativo que lleva la Secretaría Ejecutiva de Cooperación
Técnica Internacional denominado registro de Organizaciones No Gubernamentales de Desa
rrollo Receptoras de Cooperación Técnica Internaclonal-ONGD. Se inscriben en dicho registro
las personas jurídicas sin fines de lucro, constituidas en el Perú, que tienen como finalidad la
realización de acciones de desarrollo que Involucran Cooperación Técnica Internacional.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y N O M B R AM IEN TO DE JUECES Y FISCALES

-- 273 of 1506 --

Tema 1: Tem as comunes a la especialidad: Civil, Familia y Comercial
La Cooperación Técnica Internacional está regulado en el Perú por:
Decreto Legislativo N °719 "Ley de Cooperación Internacional” publicada en el Diario Ofi
cial “El Peruano” con fecha 10.11.1991.
Decreto Supremo N° 015-92-PCM “Reglamento de la Ley de Cooperación Internacional”
publicado con fecha 30.01.1992.
A grandes rasgos, el Decreto Legislativo N°71 9 establece las normas generales a que se sujeta
la cooperación técnica internacional que se gestiona a través de los organismos del Estado y
que proviene de fuentes del exterior del carácter público y/o privado.
La Cooperación Técnica Internacional es el medio por el cual el Perú recibe, transfiere y/o inter
cambia recursos humanos, bienes, servicios, capitales y tecnología de fuentes cooperantes ex
ternas cuyo objetivo es complementar y contribuir a los esfuerzos nacionales en materia de
desarrollo, destinados a:
Apoyar la ejecución de actividades y proyectos prioritarios para el desarrollo del país y de
sus regiones.
Adquirir conocimientos científicos y tecnológicos para su adaptación y aplicación en el
Perú.
Brindar preparación técnica, científica y cultural, a peruanos en el país o en el extranjeroy
a los extranjeros en el Perú.
Por otro lado, el Decreto Supremo N° 015-92-PCM "Reglamento de la Ley de Cooperación Inter
nacional” establece lo siguiente:
Se denomina "Registro de Organizaciones No Gubernamentales de Desarrollo”
(ONGD-PERU) constituidas en el Perú, al Registro que para esas personas jurídicas tiene
carácter constitutivo y que es conducido por el Ministerio de la Presidencia.
Caracteriza a estas personas jurídicas el carecer de fines de lucroy tenercomo finalidad la
realización de acciones de desarrollo que involucran cooperación técnica internacional.
11. Representación de la persona jurídica
No obstante la importancia del tema, en el Código Civil no se ha establecido dispositivo expreso
sobre la representación de las personas jurídicas, por lo que debemos remitirnos a las normas
pertinentes del Libro de Acto Jurídico, con los problemas conceptuales y prácticos que ello aca
rrea, según lo expresado por Lohmann Lúea de Tena: “la representación genera problemas con
ceptuales y prácticos tratándose de las personas jurídicas dado que el órgano representativo no
tiene autonomía respecto a la persona jurídica de la que es su vehículo de expresión— hay una
suerte de “ensimismación” del órgano con la persona jurídica— , por lo que no podría hablarse
propiamente de representación; sin embargo, considera que en este caso nos encontramos con
un “suigeneris" fenómeno de representación y no ante un caso de ausencia de ella, pues si bien
hay falta de propiedad terminológica, visto desde el lado práctico, la actuación de las personas
jurídicas en el ámbito jurídico requiere de una especial manera de representación”.
Consideramos necesario el establecimiento de un marco legal general que establezca faculta
des mínimas o “standard” en los órganos representativos, de modo tal que quienes contraten
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES 273

-- 274 of 1506 --

UBILEX
o se vinculen jurídicamente con las personas jurídicas tengan la certeza de que el acto surtirá
los efectos queridos y no serán desconocidos; ello sin perjuicio de dejar algún margen al es
tatuto para determinar el modo del ejercicio de tales facultades y otros aspectos vinculados.
Aunque limitado al ámbito procesal, constituye un avance en ese propósito la dación de la
Ley N° 26789 que dispone en su artículo único que, ‘‘el administrador representante legal o
presidente del consejo directivo, según corresponda, de las personas jurídicas reguladas en la
Sección Segunda del Libro I del Código Civil, gozan de las facultades generalesy especiales de
representación procesal señalada en los Artículos 74°y 75° del Código Procesal Civil, aprobado
por Decreto Legislativo N°768, por el solo mérito de su nombramiento inscrito en el registro
correspondiente, salvo disposición estatutaria en contrario. Para efectos de lo dispuesto en el
párrafo anterior, sólo debe presentarse copia notarialmente certificada del documento donde
consta el nombramiento inscrito.
12. Responsabilidad de las personas jurídicas
Responsabilidad Penal de las personas jurídicas: En el Perú, en los últimos años, se recono
ció que las personas jurídicas son responsables penalmente. Dentro del marco jurídico que
regula las sanciones penales tenemos a las reglas previstas en los artículos 104,105 y 105-A del
Código Penal (CP) y los artículos 90, 9T, 92, 93, 313-Ay 401-C del Código Procesal Penal (CPP),
conjuntamente con la Ley N °3 0 4 2 4 3, modificada por las Leyes N°s 30835 4y 31740, norma que
regula la responsabilidad administrativa de las personas jurídicas en el proceso penal.
Los artículos 104y 105 del CP disponen las medidas accesorias aplicables ante la comisión de
actos delictivos cometidos por parte de las personas jurídicas, siendo la finalidad de estas la
de neutral izar o dism inuir la peligrosidad objetiva con el objeto de prevenir la futura comisión
de delitos, por medio de ellas. En cuanto a la regulación del proceso penal, el artículo 90 del
CPP señala que las personas jurídicas serán incorporadas en el proceso a requerimiento del
Ministerio Público, los artículos 91 y 92 del CPP establecen el procedimiento y los requisitos
que la referida autoridad fiscal deberá cumplir para tal fin; sin embargo, es relevante men
cionar que en el artículo 93 del CPP, se detalla expresamente que aquellas gozan de todas las
garantías procesales establecidos en el CPP
Respecto a la Ley N °3 0 4 2 4 y sus modificatorias, éstas regulan la responsabilidad administra
tiva de las personas jurídicas por corrupción. Dichas normas siguen la tendencia internacio
nal de reformas normativas internas tendientes a establecer sistemas de responsabilidad de
personas jurídicas, a fin de que sean también sancionadas penalmente cuando los autores del
delito son directivos, gerentes o funcionarios de dicha persona jurídica, esto en el marco de la
lucha contra la corrupción. Cas. N °2147-2019. Puno.
Acerca de las reglas previstas en el Ley N° 30424, el legislador sólo desarrolló los criterios de
atribución de la responsabilidad, las sanciones que podrían ser aplicables como las agravantes
y atenuantes de la responsabilidad penal en las personas jurídicas para aquellos delitos pre-
3 Ley que regula la responsabilidad administrativa de las personas jurídicas por el delito de cohecho activo
transnacional.
4 Ley que regula la responsabilidad administrativa de las personas jurídicas.
