vistos en el Art. i de la Ley (Colusión simpley agravada, cohecho activo genérico y tramnacional,
cohecho activo específico, tráfico de influencias, lavado de activos, minería ilegal, crimen organizado
y terrorismo). Siendo trascendental y relevante el hecho de haber considerado la implementa-
ción de un modelo de prevención como supuesto de eximente de responsabilidad, tal y como
se ha previsto en su artículo 17, circunstancia no prevista en el CP ni el CPR Adicional a lo men
cionado, tenemos la Exposición de Motivos del Decreto Supremo N° 002-2019-]US, Reglamen
