Responsabilidad civil de las personas jurídicas: Conforme a la clasificación de los supuestos
de Responsabilidad Civil de la Persona Jurídica elaborada por Juan Espinoza5, tenemos:
a) La responsabilidad ultra vires de la persona jurídica, vale decir, cuando realiza actos que
exceden su objeto social.
b) La responsabilidad civil dentro del ejercicio de las funciones del órgano, representante o
dependiente.
c) La responsabilidad civil en exceso de las funciones del órgano, representante o depen
diente.
d) La responsabilidad civil derivada de una situación de apariencia.
e) La responsabilidad civil con ocasión de las funciones del órgano, representante o depen
diente.
13. Fin de la persona jurídica
A. Proceso de Disolución
- Disolución de la Asociación:
Disolución de pleno derecho.• La asociación se disuelve de pleno derecho cuando no pueda
funcionar según su estatuto.
Disolución por liquidación: La Asociación se disuelve por liquidación, según lo acordado por
su respectiva Junta de Acreedores de conformidad con la ley de la materia. En caso de pér
didas acumuladas, deducidas las reservas superiores al tercio del capital social pagado,
el Consejo Directivo debe solicitar el inicio del Procedimiento Concursal Ordinario de la
asociación, conforme a la ley de la materiay bajo responsabilidad ante los acreedores por
los dañosy perjuicios que resultaren por la omisión.
Disolución por atentar contra orden público (Art. 96 C.Q.): El Ministerio Público puede solicitar
judicialmente la disolución de la asociación cuyas actividades o fines sean o resulten con
trarios al orden público o a las buenas costumbres.
