La demanda se tram ita como proceso abreviado, considerando como parte demandada a
la asociación. Cualquier asociado está legitimado para intervenir en el proceso. La senten
cia no apelada se eleva en consulta a la Corte Superior.
En cualquier estado del proceso puede el juez dictar medidas cautelares suspendiendo
total o parcialmente las actividades de la asociación, o designando un interventor de las
mismas.
Disolución por falta de norma estatutaria: De no haberse previsto en el estatuto de la aso
ciación normas para el caso en que no pueda seguirfuncionando o para su disolución, se
procede de conformidad con lo dispuesto en el artículo 5 9 9 , inciso 2 C.C.
- Disolución de la Fundación:
El Consejo de Supervigilancia puede solicitar la disolución de la fundación cuya finalidad
resulte de imposible cumplimiento.
La demanda se tram ita como proceso abreviado ante el juez Civil de la sede de la funda
ción, emplazando a los administradores. La demanda será publicada por tres veces en
el diario encargado de los avisos judiciales y en otro de circulación nacional, mediando
cinco días entre cada publicación.
La sentencia no apelada se eleva en consulta a la Corte Superior.
Disolución del Comité
Disolución por atentar contra el orden público: Es de aplicación al Comité lo dispuesto en el
artículo 96 C.C.
Disolución y liquidación del Comité: Cumplida la finalidad propuesta, o si ella no se ha podi
do alcanzar, el consejo directivo procede a la disolución y liquidación del comité, presen
tando al Ministerio Público copia de los estados finales de cuentas.
B. Proceso de Liquidación
- Liquidación de la Asociación
Destino del patrim onio restante a la liquidación: Disuelta la asociación y concluida la liquida
ción, el haber neto resultante es entregado a las personas designadas en el estatuto, con
exclusión de los asociados. De no ser posible, la Sala Civil de la Corte Superior respectiva
ordena su aplicación a fines análogos en interés de la comunidad, dándose preferencia a
la provincia donde tuvo su sede la asociación.
- Liquidación de la Fundación
Destino del p a trim onio restante a la liquidación: El haber neto resultante de la liqu id a
ción de la fundación se aplica a la fin alida d prevista en el acto constitutivo. Si ello
no fuera posible, se destina, a propuesta del Consejo, a increm entar el patrim onio
de otra u otras fundaciones de fin alida d análoga o, en su defecto, a la Beneficencia
Pública para obras de similares propósitos a los que tenía la fundación en la localidad
donde tuvo su sede.
