Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 277 of 1506 --

Tema 1: Temas com unes a la especialidad: Civil, Familia y Comercial
14. Extinción de las personas jurídicas
Puig Brutau. señala tres las causas de extinción:
- Haber expirado el plazo durante el cual funcionaba legalmente.
- Por haber realizado el fin para el cual se constituyeron.
- Por ser ya imposible aplicar a éste (es decir, al fin para el cual se constituyeron) la
actividady los medios de que disponían cabe señalar en primer lugar que cuando el
fin para el que se constituyó la persona jurídica deviene legal o físicamente de im po
sible realización, la misma se extinguirá por falta de objeto. Pero también sucederá
lo mismo cuando el fin sea de imposible realización por fallar uno de los elementos
esenciales que constituyen el "substratun” de la misma.
15. Negocio jurídico: requisitos, form alidad de los actos jurídicos
El negocio jurídico en nuestro Código Civil
Vidal Ramírez, señala que el Acto Jurídico, viene a ser una elaboración basada en el sistema
Francés, específicamente en el Código Civil de 1804. Para la doctrina francesa el acto juríd i
co es toda manifestación de la voluntad con la finalidad de producir efectos jurídicos (crear,
regular, modificar, extinguir relaciones jurídicas: josserand; Mazeaud) Sin embargo se hace
la crítica a este sistema señalando que los particulares no pueden decidir cuándo producen
efectos jurídicos. El efecto jurídico es siempre es atribuido por la ley en general o por el orde
namiento jurídico. Es decir, no interesa lo que los particulares quieran; el Derecho es siempre
el que califica si esta declaración de voluntad es Acto Jurídico o no. Los particulares no pueden
decidir por ejemplo cuando un contrato es válido o no: esto siempre es decidido por la ley. Si
los particulares pudieran decidir cuándo se crea efectos jurídicos, entonces habría una inse
guridad jurídica.
La doctrina moderna iniciada por los tratadistas alemanes, seguida por los italianos y españo
les ha desarrollado la doctrina del Negocio Jurídico, conceptuándola como la declaración de
la voluntad orientada a conseguir un efecto práctico, lícito y amparado por el ordenamiento
jurídico. Para Enneccerus, el supuesto de hecho es el fundamento de las consecuencias juríd i
cas. La participación de la voluntad hace que el hecho jurídico derive en acto jurídico.
En nuestra Codificación Civil la diferencia entre el acto jurídico y el negocio jurídico es una
cuestión dilucidada. El Código Civil de 1936 no formuló una noción de acto jurídico, pero lo
concibió como todo hecho voluntario y lícito, con manifestación de voluntad y efectos que
ridos, según el esquema de León Barandiaran. El vigente Código Civil no presenta dudas en
cuanto a que no acoge la denominación de negocio jurídico y da una noción de acto jurídico
en su artículo 140o con la que confirma su extracción conceptual tanto de la obra de Vélez
Sarsfield como de la del Código de Becvilaquay se aproxima al concepto de negocio jurídico,
de manera tal, que nos permite decir que para nuestra codificación civil, entre el acto jurídico
en la noción del artículo 140o y el negocio jurídico existe una evidente relación de sinonimia
conceptual.
De la sinonimia conceptual entre el acto jurídico y el negocio jurídico existente en nuestra
codificación civil, tanto en la de 1936 como en la de 1984, así como en la justificación del m m en
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 278 of 1506 --

UBILEX
iuris de acto jurídico, participan otros autores nacionales, como Aníbal Torres Vásquezy es ex
plicada por Manuel de la Puente, para quien “los actos jurídicos de la teoría del negocio jurídi
co vienen, en realidad, a representar los hechos jurídicos de la teoría del acto jurídico”y que “la
noción de acto jurídico tiene, en el fondo, dentro de su propia teoría, el mismo contenido que
la del negocio jurídico en la teoría de éste, y que ambas cumplen adecuadamente su rol en el
ámbito de sus respectivas teorías”. Además, este reputado autor nacional ha expuesto un razo
namiento que es plenamente válido en relación al proceso de elaboración del Código de 1984
y en cuanto a que "no habría tenido sentido que, existiendo en el Perú una inalterada tradición
de aplicar la teoría del acto jurídico, con resultados plenamente satisfactorios, se introdujera
el concepto de negocio jurídico, con el evidente riesgo, de utilizar una noción jurídica fuera de
su propio Derecho”.
Lasinonimiaconceptual se funda también en la consideración del acto jurídico como un género
y del negocio jurídico como una especie y, de este modo, inferir que todo negocio jurídico es un
acto jurídico, pero que no todo acto jurídico es un negocio jurídico, la que permite distinguir los
actos jurídicos en negocíales y no negocíales.
El concepto de acto jurídico considerado es el que coincide con el del negocio jurídico. Es
el acto jurídico que tiene como sustrato la voluntariedad que requiere de la licitud y de una
manifestación de la voluntad que produzca efectos correlativos a los perseguidos deliberada
mente por el sujeto, noción contenida en el acotado artículo 140o.
16. Elementos del acto jurídico
Todo acto jurídico tiene una estructura o contenido. Este contenido está compuesto por varios
elementos. Se suele confundir elementos con requisitos del acto jurídico. Se ha creído erró
neamente que es necesario que un acto jurídico contenga todos los elementos paraserválido.
En realidad, hay elementos que no son requisitos.
Existen tres clases de elementos:
1. Elementos esenciales: Son los componentes imprescindibles que definen al acto jurídico
porque forman la esencia del acto jurídico, y deben estar siempre presente para que el
acto jurídico alcance existencia jurídica. Sin ellos es imposible que pueda celebrarse el
acto jurídico. Los elementos esenciales se distinguen en:
Elementos esenciales de carácter general: Vienen a ser los REQUISITOS DE VALI DEZ que
enumera el art. 140 del C.C.y que son imprescindibles en la generalidad de los actos jurí
dicos.
Conforme a nuestro ordenamiento jurídico los elementos o requisitos esenciales para la
validez de todo acto jurídico son:
Plena capacidad de ejercicio, salvo las restricciones contempladas en la ley.
Objeto físicay jurídicamente posible.
Fin licito.
Observancia de la forma prescrita bajo sanción de nulidad.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 279 of 1506 --

Tema 1: Temas com unes a la especialidad: Civil, Familia y Comercial
En los actos bilaterales o plurilaterales, el elemento esencial no es la simple manifesta
ción de voluntad de ambas partes, sino el consentimiento, o sea la confluencia de volun
tades de todas las partes que celebran el acto jurídico.
Elementos esenciales de carácter especial: Se llaman también elementos constitutivos.
Provienen de la propia naturaleza jurídica del acto que se va a celebrar, que los identifica
y tipifica respecto de otros actos jurídicos.
Ejemplo: El contrato de compraventa. Para su validez requiere de la capacidad, manifes
tación de voluntad, objeto, final idad y forma, y para que se tipifique y se distinga de otra
categoría jurídica, requiere del bien que se vende y del precio que se pacta.
2. Elementos naturales: Son los que integran el contenido de un acto jurídico porque son
inherentes a él, de manera que el derecho se los atribuye aun cuando los sujetos de la
relación jurídica no hayan manifestado nada respecto de ellos. Para algunos doctrina
rios más que elementos son efectos o consecuencias que derivan de la propia naturaleza
jurídica del acto jurídico establecidos por ley. Como no son elementos esenciales para la
formación del acto jurídico porque se originan en la ley de acuerdo a la denominación
del acto, las partes de la relación jurídica, pueden separarlos y desligarlos sin afectar la
validez del acto jurídico.
Ejemplo, son elementos naturales las obligaciones de saneamiento en todo contrato en el
que se transfiere la propiedad, la posesión o el uso de un bien (art. 1484 C.C.). Los intere
ses son también elementos naturales (a r ti2 4 2 a li 250 del C.C.).
3. Elementos accidentales o modalidades del acto jurídico: Son aquellos que son extra
ños al acto jurídico. No forman parte ni de la esencia ni de la naturaleza del acto jurídico.
Constituyen una autolimitación a la autonomía de la voluntad de los sujetos de la rela
ción jurídica civil. Para que formen parte de un acto jurídico es necesario pacto expreso. El
orden público no tiene nada que ver con estos elementos. El derecho no impide que los
sujetos de una relación jurídica añadan otros requisitos que el Código Civil los enumera
como modalidades del acto jurídico. Estos elementos accidentales son: la condición, el
plazo y el cargo.
17. Formalidades del acto jurídico
En nuestro Código Civil encontramos establecidas dos formalidades: la formalidad ad solem
nitatem y la form alidad ad probationem, la cual se encuentra regulada en su art. 1 4 4 , el mismo
que indica.- «Cuando la ley impone una forma y no sanciona con nulidad su inobservancia,
constituye sólo un medio de prueba de la existencia del acto».
Forma ad so le m n ita te m (forma solemne).-es requisito de validez del acto jurídico y su inob
servancia invalida a éste. Se prescribe que «El acto jurídico es nulo cuando no revista la forma pres
crita bajo sanción de nulidad», lo que se encuentra regulado en el art. 219 inciso 6 del Código Civil.
Sobre el particular, Aníbal Torres Vásquez manifiesta que «La solemnidad vale el acto jurídico
mismo; es un elemento constitutivo del acto y, por consiguiente, el único medio probatorio de
su existencia».
La form alidad ad solemnitatem está dirigida a dotar de eficacia constitutiva al negocio.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 280 of 1506 --

UBILEX
i ! F o rm a ad pmbatm mm (fo rm a p ro b a to r ia ),- no es requisito de validez del acto jurídico; se
puede prescindir de ella sin que por eso se vea afectada la validez y eficacia del acto. La forma
impuesta por la ley sin sancionar su inobservancia con la nulidad, sirve únicamente para facili
tar la prueba de la existenciay del contenido del acto; tiene una función procesal y no sustanti
va, por ser un medio probatorioy no un elemento necesario para la validez del acto. La forma
lidad ad probationem es usada para probar la existencia de un negocio de manera fehaciente.
Esta formalidad consiste en documentar— ya sea por un instrumento público o privado— la
manifestación de voluntad. En ese sentido, podemos recordar el aforismo: Verba volant, scrípta
manentl. Las palabras desaparecen, los escritos permanecen.
18. Validez y eficacia. Nulidad y anulabilidad
Eficacia e ineficacia del acto jurídico: Señalando como criterio diferenciador la producción
de sus efectos. Así, será eficaz, cuando produzca los efectos queridos por el sujeto o sujetos
que lo realizan; por el contrario, si el acto es incapaz de producir efectos, se catalogará como
ineficaz.
Ahora bien, esta ineficacia puede deberse-corno apunta Marcial Rubio6, a las causas siguien
tes: A la falta de alguno de los requisitos esenciales (señalados en el artículo 140° del C.C.);
incumplimiento de una norma imperativa; el caso de simulación absoluta; la nulidad del acto
(artículo 219° del C.C.); la anulabilidad del acto jurídico(artículo 221° del C.C.); revocación, res
cisión; acto sujeto a modalidades mientras ellas no se cumplan si son suspensivas o, si son
resolutorias a partir de su cumplimiento; resolución; mutuo disenso; etc.
Clases de Ineficacia*.
1. Ineficacia estructural o invalidez.- La ineficacia estructural, denominada también origi
naria o por causa intrínseca, es aquella ineficacia negocial que se presenta al momento
mismo de la celebración del acto jurídico. Es decir, se trata de un acto jurídico afectado
por una causal de ineficacia desde el momento de su conformación, celebración, form a
ción, nacimiento, conclusión o perfección.
La coetaneidad al momento de la formación del acto jurídico es el primer rasgo caracte
rístico de la ineficacia estructural.
Empero, además, se fundamenta en el principio de legalidad, pues todas las causales de
invalidez vienen siempre establecidas por la ley, no pudiendo ser consecuencia del pacto
entre las partes.
En los supuestos de ineficacia estructural, el negocio jamás produce efectos jurídicos por
haber nacido muerto, o deja de producir retroactivamente todos los efectos jurídicos que
hubiera producido por haber nacido gravemente enfermo.
6 RUBIO CORREO, Marcial. La invalidez del acto jurídico. Biblioteca para leer el Código Civil. Vol. IX. Pontificia Univer
sidad católica del Perú. Lima 1992, pp. 14-15.
2 BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 281 of 1506 --

Tema 1: Temas com unes a la especialidad: Civil, Familia y Comercial
La ineficacia estructural se presenta bajo la generalidad de la invalidez de los negocios ju
rídicos, la misma que abarca hasta dos supuestos: la nulidady la anulabiIidad; recibiendo
ambas el nombre genérico de invalidez en la legislacióny en ladoctrina.
vi»5 Pier¡o CasafoTO Civil (Regía 1): La disposición por parte de uno de los cónyuges, sin intervención
del otro, regulada en el artículo 315 del Código Civil es un supuesto de Ineficacia del acto jurídico;
por consiguiente, resulta inoponible para la sociedad conyugal, sin perjuicio de los efectos para las
partes que intervinieron en el mismo.
2 . Ineficacia funcional.- Denominada también sobreviniente o por causa extrínseca, co
nocida como la ineficacia en sentido estricto supone un acto jurídico perfectamente es
tructurado en el cual han concurrido todos sus elementos, presupuestosy requisitos, sólo
que, por un evento ajeno a su estructura, deja de producir efectos jurídicos.
Los supuestos típicos de ineficacia funcional son la resolución y la rescisión.
Sin embargo, se pueden sumar otros tales como: la condición y el plazo, la resciliación o
mutuo consenso, la revocación, la reversión, la retractación, el retracto mismo, la inoponi-
bilidad, la excepción de cumplimiento del con trato, la excepción de caducidad del plazo,
incluso la separación de cuerpos y el divorcio.
En la ineficacia funcional, por regla general, el defecto se presenta con posterioridad a la
formación del acto jurídico. Sin embargo, esto no es absoluto, pues en los casos de resci
sión, la causa de ineficacia es coetánea también a la formación del negocio.
La ineficacia funcional puede serconsecuencia del pacto entre las partes que han celebra
do un acto jurídico, en aplicación del principio de autonomía privada, que es el principio
di rectriz en materia de actos j urídicos y contratos.
19. Validez e invalidez del acto jurídico
Será válido, aquel que posee o reúne los requisitos esenciales (sean estos generales o espe
ciales) señalados por la ley, o que estos se encuentren exentos de algún vicio que los afecten.
Por el contrario, será un acto jurídico inválido, aquel que carezca de algún requisito esencial
o que cualquiera de estos adolezca de determinado vicio. Como señala Emilio Betti: “...Se de
nomina inválido, propiamente, el negocio en el que falta o se encuentre viciado alguno de los
elementos esenciales o carezca de uno de los presupuestos necesarios al tipo de negocio a que
pertenece. Invalidez es aquella inidoneidad para producir los efectos del tipo que deriva de la
lógica correlación establecida entre requisitos y efectos por el dispositivo de la norma jurídica
yes, conjuntamente, la sanción del deber impuesto a la autonomía privada de utilizar medios
adecuados para la consecución de sus fines propios..."(Betti, Emilio: Teoría General del Nego
cio Jurídico. Editorial Revista de Derecho Privado, p. 349).
No todo acto válido es eficaz. Existen actos que siendo válidos son ineficaces. Ejemplo: aquellos sujetos
