UBILEX
20. Invalidez del acto jurídico
Existen solamente dos supuestos de invalidez o ineficacia estructural en el sistema jurídico
nacional-, la nulidad y la anulabilidad, conocidos también como nulidad absoluta y nulidad
relativa, respectivamente.
El sistema nacional no reconoce la categoría de la inexistencia como sucede en otros sistemas
jurídicos como el italiano, el francés y el español.
Nulidad del Acto Jurídico
La nulidades la forma más grave de invalidez negocial e importa la definitiva inidoneidad
del acto para producir efectos, la misma que puede sertotal o parcial.
El acto nulo, conforme a la doctrina contemporánea en la estructuración de los negocios
jurídicos, es aquél que carece de algún elemento, presupuesto o requisito, o cuyo conteni
do es ilícito por atentar contra los principios de orden público, las buenas costumbres, o
una o varias normas imperativas.
El artículo 219odel Código Civil señala los supuestos de nulidad absoluta, establecidos de
manera taxativa:
1) Cuando falta la manifestación de voluntad del agente;
2) Se ha derogado el numeral 2 que aludía que el acto jurídico es nulo cuando sea prac
ticado por persona absolutamente incapaz.
3) Cuando su objeto es física o jurídicamente imposible o cuando sea indeterminable;
4) Cuando su fin sea ilícito;
5) Cuando adolezca de simulación absoluta;
6) Cuando no revista la forma prescrita bajo sanción de nulidad;
7) Cuando la ley lo declara nulo; y
8) En el caso del artículo V del Título Preliminar, salvo que la ley establezca sanción di
versa.
Nulidad Textual o Expresa: Las nulidades expresas son aquéllas que vienen dispuestas,
manifiestamente, por un texto legal.
Nulidad Virtual o Tácita: El últim o inciso del artículo 219o hace referencia directa a los
supuestos de las nulidades tácitas o virtuales. Aquí, la nulidad viene impuesta por el he
cho de que el negocio jurídico contraviene uno de los fundamentos o pilares del sistema
jurídico.
A criterio de Aníbal Torres, aquí nos referimos, por un lado, a las normas imperativas, o sea
aquellas que son de cumplimiento obligatorio y no derogables por las partes; y, por otro
lado, al orden público, que está constituido por el conjunto de principios fundamentales
de diversa índole que constituyen la base social sobre la cual se asienta la comunidad
como sistema de convivencia jurídica, garantizan un ambiente de normalidad con justi
cia y paz.
282 BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 283 of 1506 --

Tema 1: Temas com unes a la especialidad: Civil, Familia y Comercial
ó J "La nulidad manifiesta es aquella que resulta evidente, patente inmediatamente percepti-
J3 s ble, en suma, aquélla que resulta fácil de detectar sea que se desprenda del acto mismo o del
-ta a m S L v examen de algún otro elemento de prueba incorporado al proceso. La nulidad manifiesta no se
circunscribe a algunas o a alguna específica causa! de nulidad, sino que se extiende a todas las
causales que prevé el articulo 279 del Código Civil." Cas. tl°65§7-2019 Lima Norte.
Í2) "El contrato de compraventa materia de nulidad adolece de falta de manifestación de vo
luntad por estar ausente la voluntad declarada de la parte vendedora, dado que suscribió el
contrato persona distinta a quien actuaba como representante de la referida parte, según se consignó en el
propio texto contractual". Cas. N° 1241-2018 Lambayeque.
Anulabilidad del Acto jurídico
El acto anulable es aquél que se encuentra afectado por un vicio en su conformación.
No se trata de un acto que carezca de algún elemento o presupuesto, o cuyo contenido
sea prohibido, sino de actos que cumplen con la mayoría de sus aspectos estructurales,
pero que tienen un vicio en su conformación.
El artículo 221o del Código Civil señala los supuestos o causales por los que el acto es anu-
lable, establecidos de manera taxativa:
1) Por capacidad de ejercicio restringida de la persona contemplada en los numerales 1
al 8 del artículo 4 4 7;
2) Por vicio resultante del error, dolo, violencia e intimidación;
3) Por simulación, cuando el acto real que lo contiene perjudica al derecho de tercero; y
4) Cuando la ley lo declare anulable.
Semejanzas entre la Nulidady la Anulabilidad:
1. Las causales son siempre coetáneos a la celebración del acto jurídico, las causales
tanto de nulidad como las de anulabilidad se presentan siempre al momento de la
celebración del negocio, es decir, al momento de su formación, y por ello es que se
habla de ineficacia originaria.
2. Están siempre referidas a un defecto en la estructura del acto jurídico, suponen un
defecto en la estructura negocial, por ello son supuestos de ineficacia estructural.
3. No pueden ser pactadas, vienen establecidas por la ley.*34
7 Artículo 44.- Capacidad de ejercicio restringida.
Tienen capacidad de ejercicio restringida:
1. - Los mayores de dieciséis y menores de dieciocho años de edad.
2. - Los retardados mentales. Numeral derogado.
3 - Los que adolecen de deterioro mental que les impide expresar su libre voluntad. Num eral derogado
4 - Los pródigos.
5. - Los que incurren en mala gestión.
6. - Los ebrios habituales.
7. - Los toxicómanos.
8. - Los que sufren pena que lleva anexa la interdicción civil.
9. - Las personas que se encuentren en estado de coma, siempre que no hubiera designado un apoyo con
anterioridad.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 284 of 1506 --

UBILEX
Diferencias entre la Nulidad y la Anuíabilidad:
i. La nulidad supone un defecto severo en la conformación del acto jurídico, mientras
que la anuíabilidad únicamente un vicio en la estructura, es decir, un defecto menor.
z. Todas las causales de nulidad se construyen y establecen legalmente en tutela del
interés público, mientras que las causales de anuíabilidad se fundamentan en la
tutela del interés privado, de las partes que han celebrado el acto jurídico, a fin de
protegerá la parte que ha resultado afectada por la causal de anuíabilidad.
3. La acción para solicitar la declaración judicial de nulidad de un acto jurídico puede ser
interpuesta no solo por cualquiera de las partes que lo han celebrado, sino también
por cualquier tercero, siempre que acredite legítimo interés económico o moral, o por
el Ministerio Público. Incluso el juez puede declarar de oficio una nulidad cuando la
misma resulte manifiesta, según lo establece el artículo 220odel Código Civil.
Por el contrario, la acción judicial para solicitar la anuíabilidad del acto jurídico sólo
puede ser interpuesta por la parte que ha celebrado el acto jurídico viciado, en cuyo
beneficio la ley establece dicha acción.
4. Los actos nulos nacen muertos y por ende no producen ninguno de los efectos jurídi
cos que tendrían que haber producido. Por el contrario, los actos anulables nacen con
vida, pero gravemente enfermos y como tales tienen un doble destino alternativo y
excluyente son subsanados o convalidados a través de la confirmación. Son decla
rados judicialmente nulos a través de la acción de anuíabilidad. Respecto de los ac
tos anulables, debemos decir, que a diferencia de los actos nulos, los mismos nacen
produciendo todos sus efectos jurídicos, y los seguirán produciendo normalmente si
son confirmados, o dejaran de producirlos si son declarados judicialmente nulos.
5. Los actos nulos, a diferencia de los actos anulables, no pueden ser confirmados o
convalidados justamente por haber nacido sin vida.
6 . Son también distintos los plazos prescriptorios de las acciones de nulidady de anu-
labilidad. La acción de nulidad prescribe a los diez años, mientras que la de anulabi-
lidad a los dos años, según lo dispone el artículo 2001 del Código Civil.
21. Fraude a través de los actos jurídicos
El fraude, es un elemento que perturba las relaciones establecidas entre acreedor y deudor,
por cuanto se dirige al incumplimiento de la obligación asumida. El fraude se configurará
como una suerte de actuar doloso o malicioso, con el fin de perjudicar al acreedor, im pidién
dole que se haga cobro de lo debido.
Frente al fraude se erige la acción pauliana, aunque como dice Lohmann, no toda conducta
y acto fraudulentos posibilitan esta acción y, por otro lado, la acción pauliana perseguirá la
ineficacia de actos que han causando perjuicios a los acreedores, no son fraudulentos como
sinónimos de dolosos.
La acción revocatoria o pauliana: es aquella por la cual, un acreedor persigue se deje sin efec
to o sea inoponible respecto de él, el acto o los actos de disposición que haya practicado su
deudor con un tercero, en perjuicio de dicho acreedor. Tiene como fundamento, el reconstituir
