n e g o c io ju r íd ic o e n c u a n t o es p o s ib le d e e n t e n d e r s e e n el s e n t id o d e t e r m in a d o p o r la s p a rte s.
286 BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 287 of 1506 --

Tema 1: Temas com unes a la especialidad: Civil, Familia y Comercial
El jurista italiano Messineo, considera que la interpretación del negocio vale tanto como la
investigación del significado efectivo del mismo, que siempre es claro y patente, ya se trate
de una o varias manifestaciones de la voluntad cuando se agotan todas las reglas o métodos
de interpretación del acto jurídico y en el ámbito de la lógica jurídica queda la duda sobre la
interpretación exacta del acto jurídico, la ley interviene para perm itir la interpretación de la
declaración dudosa.
No deben confundirse las normas de interpretación con las normas supletorias, es decir con
aquellas que regulan los efectos del acto jurídico a falta de voluntad contraria por más que
tengan con éstas mucha afinidad. Las normas supletorias presuponen la falta de voluntad, en
tre las partes, por lo que existiendo un vacío se accede a esas normas, en tanto que las normas
interpretativas suponen una voluntad no claramente manifestada.
Las normas interpretativas no deben considerarse como normas doctrinales y que no tienen
por lo mismo valor jurídico, son verdaderas normas jurídicas porque constituyen criterios le
gales y no simples criterios lógicos, por ello no pueden violarse impunemente.
Teorías de la interpretación
1. - Teoría de la voluntad.-Sostenida por la doctrina Francesa, con influencia del derecho roma
no y considera que para hallar el verdadero sentido de un acto jurídico debe establecerse
cuál ha sido la voluntad real de los agentes o sujetos de la relación jurídica, de tal modo
que la voluntad prevalece sobre lo que aparece como declarado. Sin embargo, cabe adver
tir que en esta teoría no se trata de atribuir valor a una voluntad intimista, agnóstica, sino
a una voluntad demostrada por una medio de una conducta exteriorizada.
2. - Teoría de la declaración.-Sostenida por la doctrina alemana, y considera que la interpreta
ción debe hacerse de acuerdo a lo expresado, tal y conforme aparece, prescindiéndose
de la voluntad interna no contenida en la manifestación o declaración. Frente a estas dos
teorías de carácter absolutoy exclusivistas, han surgidos dos nuevas teorías
3. - Teoría de la responsabilidad civil.-Esta teoría se encuentra fundamentada doctrinariamente
casi en los mismos términos de lateoríade lavoluntad,disminuyendosucarácterabsolu-
toal sostenerque no basta sólo establecer la voluntad de las partesy su prevalencia sobre
lo declarado sino también determinar las responsabilidades que las partes de la relación
jurídica han asumido.
4 - Teoría de la confianza o teoría de la buena fe - Esta teoría se encuentra fundamentada doc
trinariamente casi en los mismos términos de la teoría alemana de la declaración, dis
minuyendo su carácter absoluto al sostener que no basta sólo lo declarado por las partes
para interpretar el acto jurídico sino que debe establecerse la buena fe y confianza de las
partes al celebrar el acto jurídico.
Normas de interpretación contenidas en el Código Civil
Artículo 168° C.C. (principiogeneral de interpretación).- El dispositivo preceptúa que el Acto
jurídico debe ser interpretado conforme a lo expresado en él y según el principio de la
buena fe. Esta norma tiene su antecedente en el art. 1328o del C.C. de 1936, que establecía
que los contratos son obligatorios en cuanto se halla expresado en ellos, y deben ejecu
tarse de acuerdo a las reglas de la buena fe y la común intención de las partes.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 288 of 1506 --

UBILEX
Al no haberse considerado en el Art. 168o, la común intención de las partes, el C.C. de 1984
ha tomado como fuente a las teorías de la declaración y de la confianza o de la buena fe,
también denominada teoría objetiva, de este modo lo que antes se aplicaba solamente a
los contratos, ahora se ha hecho extensiva a todos los actos jurídicos.
En cuanto a la buena fe, hay que entenderla en el sentido que la teoría se sustenta en la va
lidez a priori de la manifestación de la voluntad, si el destinatario ha actuado de buena fe,
esto es, confiando en la declaración y su correspondencia en la actuación y manifestación
de la voluntad sin mala intención, respecto a las consecuencias o resultados que se deri
ven del compromiso jurídico respectivo, en consecuencia, la declaración produce todos
sus efectos. Por el contrario, si la declaración no genera la confianza en quien la recibe, la
falta de correspondencia con la voluntad hace ineficaz el acto jurídico.
Artículo 169° C.C. (método de interpretación sistemático o interdependiente).- El dispositivo es
tablece que las cláusulas de los negocios se interpretan las unas por medio de las otras
atribuyéndose a las dudosas el sentido que resulte del conjunto de todas, esto significa,
que para interpretar un acto jurídico hay que vincular las cláusulas, contenida en dicho
acto, unas con otras, por cuanto el acto jurídico tiene un carácter integrador, representa un
continente normativo, luego ninguna cláusula posee un sentido anárquico o autárquico,
vale decir, existencia, independencia y autonomía por sí sola con prescindencia de los
demás.
Las cláusulas son parte de un todo que representa el acto jurídico, no pueden haber por
lo tanto contradicciones entre ellas. En cuanto a las cláusulas dudosas debe tenerse en
cuenta las siguientes reglas de hermenéutica:
1. - Producida una duda, ya sea en el acto jurídico o en una cláusula del acto jurídico, la
interpretación procura obtener un efecto adecuado antes de no tenerlo, es decir, que
la elaboración del acto jurídico debe responder a la voluntad destinado a crear algún
resultado, salvo que de la declaración se perciba que no es idónea para tener efecto
alguno.
2. - En los Actos Jurídicos elaborados por una de las partes en form ulario o impresos, en
caso de duda la interpretación favorece a la otra parte. Este caso está referido a la
parte fuerte que hace laofertay es justificable porque el autor de los enunciados du
dosos u obscuros estaba en la obligación de expresarse con claridad. Son los casos,
por ejemplo, de los contratos de adhesión (telefónica, sedapal, etc).
3 - En el supuesto que subsistiese la duda, pese a la aplicación de otras reglas de herme
néutica, deberá actuarse con rigor menos gravoso respecto al obligado si el negocio
fuera gratuito; tratándose de uno oneroso deberá solucionarse en forma equitativa, es
decir, sin perjudicar los intereses de las partes.
4.- Si la obscuridad es tal, así provenga de una parte de modo que no se puede determ i
nar lo que se quiso crear jurídicamente el acto jurídico deviene en ineficaz por falta
de consentimiento valedero o por error obstativo.
Artículo 170o C.C. (método de interpretación finalista o teleológico).- El dispositivo prescribe
que las expresiones que tengan varios sentidos deben entenderse en el más adecuado a
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 289 of 1506 --

-ama 1: T e m as co m unes a la especialidad: Civil, Familia y Com ercial
la naturaleza y al objeto del acto. Esta norma se refiere pues, a los casos de expresiones
ambiguas. Debe entenderse que en el acto jurídico se puede adscribir ciertas disposicio
nes o términos como “da” o “entrega”, cuyo significado puede deducirse del conjunto de la
declaración y debe entendérselas, como que se trata de transferir la propiedad de un bien
a través de la venta, donación, permuta, etc.
Asimismo, debe entenderse el vocablo objeto como sinónimo de finalidad u objetivo y no
como bien o cosa, por ello el jurista De Cossio, afirma que sería peligroso convertir el proceso
de interpretación en algo puramente subjetivo, puesto que el acto jurídico, una vez perfeccio
nado, adquiere cierta autonomía e impone sus propias exigencias.
Simulación del acto jurídico:
Se trata de un acuerdo de los sujetos que intervienen en el acto jurídico para em itir una falsa
declaración de voluntad, con el ánimo de que los terceros crean en lo aparentey no conozcan
la realidad. Ejemplo, el deudor para impedir una medida cautelar como el embargo, simula
haber vendido la totalidad de su patrimonio a otra persona que acepta participar en el acto
simulado. El acreedor que cree que es cierto ya no podrá ordenar ejecución sobre esos bienes.
Pero al margen de esta apariencia, el supuesto vendedory comprador saben que tal circuns
tancia sólo es aparente, en la medida que en la realidad el desplazamiento no se ha produci
do. El acreedor cree en la apariencia porque desconoce la realidad.
Requisitos:
i.- Disconformidad entre lo que aparece como manifestación de voluntad con la voluntad
real y sincera de los declarantes.
2 - Concertación previa de los agentes o sujetos de la relación jurídica para dar a lo manifesta
do, declaradoy no querido, visos de autenticidad con el propósito de engañar a terceros.
Por la primera característica la simulación se distingue de la reserva mental, porque ésta úl
tim a no se manifiesta. Por la segunda característica se distingue de la declaración informal,
pues, en esta no se pretende dar a la manifestación apariencia de seriedad.
Clases de simulación:
1. - Simulación absoluta.-Cuando la declaración no respondea ningunadeterminación real
mente querida, y de allí que el art. 190odel C.C., expresa que en esta simulación se aparen
ta un acto jurídico, cuando no existe realmente voluntad para celebrarlo.
Ejemplo: A finge vender un bien a B, siendo así que no hay voluntad alguna de que B, ad
quiera el dom inio de aquel bajo ningún concepto.
2. - Simulación relativa.- Cuando el acto declarado no responde a la verdadera determinación
de la voluntad, pero esta última existe, solo que no se declara. Hay aquí dos actos: un acto
aparente, ostensible, que es ficticio; y, otro acto oculto, secreto que es real, el verdaderamen
te deseado por las partes, de modo que este último se halla disimulado por el primero.
Ejemplo: A y B aparecen celebrando un contrato de compraventa cuando en realidad, lo
que ha hecho A es donar el inmueble a B. El acto aparente es la compraventa, el acto ocul
to o secreto es la donación. Tal es el sentido del artículo 191odel C.C. La simulación relativa
puede consistir también en la referencia de datos inexactos sobre el objeto del negocio o
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 290 of 1506 --

UBILEX
sobre fechas o cantidades, como cuando se aparenta vender un inmueble por un precio
determinado, para evitar el pago de los impuestos a la SUNAT. La simulación relativa se
clasifica en lícita e ilícita.
Simulación relativa lícita.- La simulación en principio no es reprobada por la ley.
Stolfi, refiriéndose al acuerdo simulatorio sostiene que el mismo no tiene en sí, nada
de ilícito, las partes pueden recurrir a él, por simple ostentación o por motivos de
conveniencia social o para ocultar a terceros la verdadera naturaleza del negocio o
acto jurídico. El C.C de 1936, siguió el principio de la licitud de la simulación. El C.C.
de 1984 no dice nada al respecto, pero de la simple lectura del art. 191o del C.C. apre
ciamos que si la admite, igual suerte corre el art. 192o.
Simulación relativa ilícita.- La simulación tiene como una de sus características el
propósito de engañar a terceros, cuando éste engaño es malicioso, cuando es perju
dicial al derecho de terceros la simulación es ilícita.
24. La acción de nulidad por simulación
La acción de nulidad por simulación procede tanto en la simulación absoluta, como en la
relativa. Según el art. 193° del C.C. puede ser ejercitada por cualquiera de las partes o por el
tercero perjudicado, puede ser ejercitada por cualquiera de las partes, los que deben inter
ponerlos durante su vigencia, por lo que, es de aplicación los plazos prescritos, estipulados
para las acciones de nulidad contenida en el art. 2001o Inc. i°, que fija un plazo de 10 añosy de
anulabilidad, según el art. 2001o Inc. 4 °, que fija un plazo de 2 años, ya sea cuando se trata de
simulación absoluta y de simulación relativa, respectivamente. Esto significa que concluidos
dichos plazos ya no es procedente interponer la acción de nulidad por simulación de acuerdo
con la prescripción extintiva de la acción que se interpone en el proceso mediante excepción.
Lasimulación debe ser probada porquien laalegue. Paraellose puede ser recurrir a la prueba
directa e indirecta.
Efectos: La nulidad porsímulación trae consigo los siguientes efectos:
Si lasimulación es absoluta al declararse su nulidad judicial, se extingue definitivamente
el acto jurídico aparente y también sus consecuencias si los hubiera. Ejemplo: Si un in
mueble se transfirió con simulación absoluta al declararse su nulidad no es necesaria una
nueva escritura traslativa de dominio basta con la inscripción de la sentencia del juez en
el Registro de Propiedad.
Si lasimulación es relativa, hay que distinguir si se trata de una lícita o ilícita. En el primer
caso se anula el acto aparente,y el acto oculto surge haciéndose ostensibley subsistiendo
todos sus efectos. En el segundo caso tanto el negocio oculto como el aparente quedan
anulados sin efecto alguno, por consiguiente, las cosas vuelven a su estado anterior.
Oponibilidad e inoponibilidad de la acción.- El Art. 194o del C.C. establece que la simulación
no puede ser opuesta por las partes, ni por los terceros perjudicados a quien de buena fe y a
título oneroso haya adquirido derechos el titu la r aparente. Entonces, la simulación es inopo-
nible, es decir, que no se puede impugnar al tercero adquiriente de buena fe y a título oneroso
290 BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

