y es oponible al tercero adquiriente que actuó de mala fe, es decir, que conocía que el bien
procedía de un acto simulado, aunque lo hubiera adquirido a título oneroso.
25. Vicios de la voluntad
Los vicios afectan la voluntad interna, lo que va a traer como consecuencia que al exteriorizarla
quede también determinada por los mismos vicios. Se considera como vicios de la voluntad al
error, el dolo, la violenciay la intimidación.
a. El error: El error es conceptuado como aquella divergencia inconsciente que se da entre
la voluntad interna o real del sujeto y los efectos que busca con su manifestación.
Para Fernando Vidal Ramírez, consiste fundamentalmente en una representación subje
tiva contraria a la verdadera realidad objetivay cuando esa falsa representación ha tenido
tal importancia en la génesis del negocio que haya sido capaz de determinar la voluntad,
constituye un vicio de la misma.
1. Error de hecho: la ausencia de conocimiento o el conocimiento equivocado esté re
ferido a una situación de hecho.
2. Error de derecho: la ausencia de conocimiento o el conocimiento equivocado esté
referido a una norma jurídica.
3. Error esencial: si afecta la validez del acto jurídico.
Error In Substantia : Cuando recae sobre la propia esencia o una cualidad del ob
jeto del acto que, de acuerdo con la apreciación general o en relación a las cir
cunstancias, debe considerarse determinante de la voluntad.
Error In Personam: Cuando recae sobre las cualidades personales de la otra par
te, siempre que aquéllas hayan sido determinantes de la voluntad.
Error luris-, Cuando el error de derecho haya sido la razón única o determinante
del acto.
Error En La Cantidad: El error de cálculo no da lugar a la anulación del acto sino
solamente a rectificación, salvo que consistiendo en un error sobre la cantidad
haya sido determinante de la voluntad.
Error En El Motivo-, el erraren el motivo sólo vicia el acto cuando expresamente se
manifiesta como su razón determinantey es aceptado por la otra parte.
Error Obstativo-, Las disposiciones de los artículos zoi a 207 también se aplican,
en cuanto sean pertinentes, al caso en que el error en la declaración se refiera a
la naturaleza del acto, al objeto principal de la declaración o a la identidad de
la persona cuando la consideración a ella hubiese sido el motivo determinante
de la voluntad, así como al caso en que la declaración hubiese sido trasmitida
inexactamente por quien estuviere encargado de hacerlo.
4. Error indiferente: no afecta la validez del acto jurídico, no pudiendo producirsuanu-
lación. Se clasifican en error de cuenta o de cálculo (Art. 204 C.C.), error en el motivo (Art.
205 C.C.), error en la denominación (Art. 209 C.C.).
