Clasificación:
Doio causante o determinante y dolo incidente o incidental, según causeo no laanulabili-
daddel acto.
Dolo positivo y negativo, según se trate de una acción u omisión.
Dolo directo (según se lo utilicen las partes) o indirecto(lo utiliza terceros).
c La violencia física e intimación: La violencia es el ejercicio de una fuerza física o psico
lógica dirigida a agredirá otro (o lesionarlo), si concurre este supuesto dentro de un acto
jurídico, este es anulable. Asimismo, la violencia es la limitación de la libertad del sujeto.
Clases de violencia:
La doctrina y los códigos han utilizado varias denominaciones para indicar tal falta de
libertad: fuerza, coacción, amenaza, intimidación, violencia, distinguiendo también las
dos formas en que tal falta de libertad puede ofrecerse, que los romanos expresaban con
los términos de vis absoluta (violencia física) y vis compulsiva (violencia moral).
La intimación: La intimidación es la coacción, la amenaza; se configura cuando se inspira
al agente el miedo fundado de sufrir un mal inminente o grave en su persona. Esta acción
vuelve el acto jurídico anulable.
"La intimidación com o vicio de voluntad requiere la existencia de un fundado temor, esto
implica que no basta un sim ple te m o r sino un tem or razonable, que es: consecuencia de
s u frirá n m a l grave e inminente; sin embargo, lo primero a advertir es que tratándose de
intimidación, lo que importa es que e lm a l conque se amenaza produzca impresión decisiva
en el sujeto,:llevándolo: a;hacer la:declaración. No impera un criterio objetivo; la gravedad del
mal, sino subjetivo: que el tem or producido haya perturbado la voluntad d e t sujeto. " Cas. N?
2942-2016 Tacna.
26. Confirmación del acto jurídico
Si un acto jurídico adolece de un vicio o causal de nulidad relativa, puede ser anulado o conva
lidado mediante la confirmación. La confirmación, entonces, es un acto unilateral, de carácter
recepticio, que implica una convalidación del acto con nulidad relativa, y una renuncia a la
acción de nulidad relativa.
292 BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 293 of 1506 --

Terna 1: Te m as com unes a la especialidad: Civil, Familia y Com ercia
Ciases:
Confirmación expresa-, es la que se realiza mediante instrumento que contenga la mención del
acto que se quiere confirmar, la causal de anulabilidady la manifestación expresa de confir
marlo (Art. 230 C.C.).
Confirmación tácita-, es aquella que resulta de la ejecución total o parcial por la parte a quien
corresponde la acción de anulabilidad conociendo la causal, o, si existieran hechos que in
equívocamente pongan de manifiesto la intención de renunciar a la acción de anulabilidad.
27. Representación: clases
Concepto: Por regla general toda persona en el ejercicio de sus derechos, y en uso de sus fa
cultades puede celebrar cualquier acto jurídico sin contravenir la ley, el orden público y las
buenas costumbres, Por excepción, la ley otorga o faculta a la persona o sujeto de derecho q ue
pueda celebrar indirectamente el negocio o acto jurídico, por intermedio de otra persona que
previamente a designado con tal fin, para que actúe a su nom brey representación celebrando
directamente el acto jurídico. A esta persona se le denomina Representante. En esta últim a
hipótesis se da la institución de la representación, consecuentemente, el representante es la
persona que en forma directa celebra el negocio o acto jurídico, en cambio el Representado
lo hace en forma indirecta, y a cuyo nombre el representante celebra el Acto Jurídico con un
tercero.
Clases de representación:
7.- Representación legal.- Llamada también representación necesaria, se sustenta en la ley, en
la función tuitiva del Estadoyen aquella finalidad dirigida fundamentalmente por el Es
tado a fi n de q ue nadie se quede sin la protección desús intereses y derechos. Comprende
tanto a las personas naturales como a las personas jurídicas. En relación a los incapaces,
los padres son representantes legales, respecto de sus hijos menores, y aún de los que
están por nacer. El Derecho familia ha creado la institución jurídica denominada Patria
Potestad, la que se ejerce conjuntamente por el padrey la madre durante el matrimonio.
Tratándose de los hijos extramatrimoniales, la representación es ejercida por el padre o
la madre que los ha reconocido y si ambos lo reconocen, pero viven separados, el Juez
determina a quien corresponde. La Tutela se ejerce sobre los menores de edad que no se
encuentran bajo la Patria Potestad. Al representante la ley lo denomina tutor. La Cúratela
se ejerce sobre las personas mayores de edad que son incapaces absolutos, los Curadores
son representantes legales de las personas anteriormente indicadas.
Los Representante Legales de las personas Jurídicas de Derecho Público se determinan
por las disposiciones que las leyes establezcan, (en concordancia con los arts. 76°y 79° del
C.C.) Por ejemplo. El Alcalde representa a la Municipalidad, el Ministro al Ministerio, etc.
En el caso de las personas jurídicas de Derecho Privado regulados por el Código Civil, la
ley general de Sociedades o por leyes especiales. Sus representantes son los presidentes,
gerentes generales, secretarios generales, según el caso particular.
2 .- Representación voluntaria convencional - Es aquella que surge en forma libre y espontánea
de parte de las personas naturales o jurídicas, como resultado de un acuerdo de volunta-
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES 293

-- 294 of 1506 --

UBILEX
des. Para el Jurista Italiano Covi el o, el otorgamiento del poder de representación es siem
pre una manifestación de voluntad por la cual una persona autoriza a otra para actuar en
su nombre y en defensa de sus intereses. Por ejemplo, el mandato regulado por los arts.
I790y 1792 del C.C.
Representación d ire cta - Doctrinariamente es aquella en que el representante declara una
voluntad propia, que actúa a nombre del representado, y que está premunido de faculta
des o poderes conferidos por el representado para ejercer la representación. Estos requi
sitos deben ser concurrentes y tener una representación emanada de un poder.
Representación indirecta.-Doctrinariamente es aquella en la cual una persona se coloca en
lugar de otra, celebrando el acto jurídico en su propio nombre, sin poner de manifiesto
que está actuando a nombre de otro o cuidando interese ajenos. En este caso el represen
tante recibe la denominación de interpósita persona. El Código Civil vigente regula dicha
institución en los arts. 1809o al 1813o.
Poderes
Concepto: El concepto del poder está referido a la representación voluntaria directa. Tiene
varias acepciones. Es el documento en el cual consta la representación, es decir las facultades
amplias, generales o especiales que una persona otorga a otra persona para que actúe a su
nombre. Puede celebrarse por Escritura Pública, por acta fuera de Registro o por Carta Poder.
También es el acto jurídico, por medio del cual, se confiere la representación. El Poder designa
estrictamente la situación jurídica de que es investido, o en que es colocado el representante,
y que le permite actuaren la esfera Jurídica ajena del representado.
Clases de poder: Conforme al art. 155o del C.C., el representado puede otorgar los poderes
siguientes:
El Poder General, es aquel que se otorga para actos de administración de los bienes, de-
rechosy patrimonios que poseey del cual es titu lar el Representado.
El Poder Especial, es aquel que se otorga al representante para actos específicos y concre
tos, y se otorga por escritura pública, bajo sanción de nulidad. Ejemplo: para la venta de
un bien inmueble, el representado otorgará poder especial a su representante con tal fin.
El Poder General, es exclusivamente para los actos de administración y el Poder Especial para
aquellos que en forma expresa autoriza el representado de un modo indubitable y por escri
tura pública, bajo sanción de nulidad como sucede cuando una persona autoriza a otra, para
que realice actos jurídicos de disposición en sus bienes.
28. Violación y exceso de facultades
Excesos en el ejercicio de la representación:
Si el representante ha procedido excediéndose en las facultades que le confirió el repre
sentado o violando dichas facultades el acto jurídico celebrado en esas condiciones no
surte ningún efecto jurídico para el representado, sin perjuicio de las responsabilidades
civiles o penales en que hubiere incurrido el representante frente al re presentado y frente
a terceros. Se encuentra regulada por el primer párrafo del art. 161odel C.C.
294 BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 295 of 1506 --

Tema 1: Temas com unes a la especialidad: Civil, Familia y Comercial
Ausencia de representación o falsa representación:
Igualmente son ineficaces los actos celebrados por el que funge de representante, sin te
ner representación alguna. Sin embargo, en estos casos el acto jurídico puede ser ratifi
cado por el representado de acuerdo con la forma prescrita empleada en su celebración y
tiene efecto retroactivo, dejando a salvo el derecho de terceros, conforme establece el art.
162o del CC. Antes de la ratificación puede resolverse o extinguirse el acto jurídico entre
el tercero y representante, sin perjuicio de la indemnización que corresponda. La facultad
de ratificar se trasmite a los herederos del representado. Se encuentra regulada por el
segundo párrafo del art. 161odel C.C.
Acto jurídico a lie n o n o m in e :
La regla contenida en el art. 166° del C.C., establece que el acto jurídico que celebre con
sigo mismo el representante ya sea en nombre propio o como representante de otro, es
anulable. La excepción establecida en el mismo artículo se da en los 3 casos siguientes:
1. - Si la ley lo permite, el acto alieno nomine es válido.
2. - Si el representado lo hubiera autorizado en forma específica, el acto alieno nomine es
válido.
3. - Si el objeto del negocio no produce un conflicto de intereses, el acto jurídico alieno
nomine es válido. En el caso del acto jurídico consigo mismo, corresponde al repre
sentado que no dio la autorización pertinente ejercer la acción judicial de anulabili-
dad o nulidad relativa.
29. Revocación, renuncia ysustitución. Responsabilidades
1.- Revocación del poder:
Es el acto unilateral del representado para dejar sin efecto la representación otorgada
al representante. El representante puede revocar el Poder otorgado al representante en
cualquier momento, para dicho efecto, la revocación del poder deberá comunicarse al
representante y a todos los que intervienen o tienen legítimo interés, o mantengan re
laciones jurídicas vinculadas con dichos poderes. Respecto a los terceros, la revocación
surte efecto si se ha inscrito en los Registros Públicos, de lo contrario no puede oponerse
a éstos si han celebrado actos jurídicos con el representante ignorando la revocación del
poder que estaba debidamente inscrito. Vale decir si los terceros han actuado de buena
fe al celebrar los actos jurídicos con el representante, surtirán sus efectos jurídicos. Se en
cuentra regulado por el art. 152° del C.C. concordante con el art. 149° del C.C.
Inevocabilidad del poden- El poderes irrevocable cuando el representado a otorgado poder
para un acto especial por tiempo limitado o cuando es otorgado en interés común del
representado y del representante o de un tercero. Sin embargo, en este caso, si el repre
sentado dejara sin efecto el poder estará obligado a indemnizar los daños y perjuicios
irrogados al representante. El Plazo de vigenciay validez del poder irrevocable, no puede
ser mayor de un año, de conformidad con el art. 153o del C.C.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES 295

-- 296 of 1506 --

UBILEX
I2. Renuncia o í ! ooder:
El representante puede renunciar a la representación para lo cual deberá comunicárselo
al representado, debiendo continuar en sus funciones hasta ser reemplazado, salvo im
pedimento grave o justa causa, en todo caso el representante puede dejar la representa
ción si transcurridos 30 días de notificado el representado, más el térm ino de la distancia,
no ha sido reemplazado por otro.
3. Sustitución dei Poder. Responsabilidad del representante.
La sustitución consiste en la delegación que hace el representante de todas o algunas de
las facultades que ha recibido para ejercer la representación a otra persona llamado sus
tituto. Se encuentra regulado por el art. 157o del C.C.
Clases de sustitución:
Sustitución restricta o restringida.- El representante efectúa la sustitución en la persona
que el representado designó previamente al otorgarle poder y representación, es decir
el representado le señala claramente el nombre y la persona que podrá sustituirlo para
celebrar cualquier acto jurídico en que el representante no pudiera concurrir. El Represen
tante designa a su sustituto en aquella persona que el representado le ha señalado, de tal
manera que los actos que celebre el sustituto con terceros serán exclusivamente respon
sabilidad del sustituto y no del representante. El representante cumple lo ordenado por
el representado. Se encuentra contemplado en el primer párrafo del art. 158o del C.C.
Sustitución irrestricta.- Está regulada en el segundo párrafo del art. 158° del C.C. y con
siste en la libertad que tiene el representante para elegir y designar a su sustituto, asu
miendo las responsabilidades si designa como sustituto a una persona que no es idónea,
es incapaz o insolvente, es decir que no reúna condiciones morales, intelectuales, físicas,
para cumplir con las funciones del cargo. Será responsable también por los actos que ha
biendo celebrado al sustituto perjudiquen al representado.
30. Reglas sobre prescripción y caducidad
Prescripción extíntiva: concepto, efectos: El Código Civil en su artículo 1989° establece que
la prescripción es una institución jurídica que, mediante el transcurso del tiempo, extingue la
acción, dejando subsistente el derecho.
La prescripción extintiva o liberatoria descansa en la necesidad de poner térm ino a la incerti
dumbre de los derechosy en la presunción de abandono por parte del titular. Cuando el artícu
lo 1989 del Código Civil se refiere a la acción, no se refiere a la acción como el derecho subjetivo
abstracto, ya que al ser un derecho abstracto no está sujeta a prescripción.
La prescripción funciona específicamente contra la pretensión planteada en la demanda, neu
tralizándola o paralizándola, pero ello no significa que se destruye el derecho material que
sirve de base a la pretensión. Refuerza lo manifestado que la prescripción extintiva se ejerce
a iniciativa de parte, lo que quiere decir que el solo transcurso del tiempo no paraliza la pre
tensión y señalo paralizar la pretensión y no extinguirla porque aun cuando el beneficiado
con ella lo deduce en el proceso como medio de defensa no extingue el derecho mismo ya
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 297 of 1506 --

Tema 1: Temas com unes a la especialidad: Civil, Familia y Comercial
que puede suscitar aún ciertos efectos jurídicos. Por ejemplo, un pago con no repetición o un
reconocimiento extrajudicial de la obligación, etc.
Renunciabilidad e irrermnciabilidad: El derecho de prescribir es irrenunciable. Es nulo todo
pacto destinado a impedir los efectos de la prescripción.
Puede renunciarse expresa o tácitamente a la prescripción ya ganada.
Se entiende que hay renuncia tácita cuando resulta de la ejecución de un acto incompatible
con la voluntad de favorecerse con la prescripción.
Suspensión de la prescripción: La prescripción se suspende:
- Cuando las personas con capacidad de ejercicio restringida contempladas en el artículo
44 incisos del i al 8 no cuentan con sus representantes legales.
- Entre los cónyuges, durante la vigencia de la sociedad de gananciales.
- Entre las personas comprendidas en el artículo 32.6o del Código Civil (unión de hecho).
- Entre los menores y sus padres o tutores, durante la patria potestad o la tutela.
- Entre las personas con capacidad de ejercicio restringida contempladas en el artículo 44
numeral 9 y las personas que le prestan apoyos necesarios, durante el ejercicio del apoyo
brindado.
- Durante el tiempo que transcurra entre la petición y el nombramiento del curador de bie
nes, en los casos que procede.
- Entre las personas jurídicas y sus administradores, mientras éstos continúen en el ejerci
cio del cargo.
- Mientras sean imposibles reclamar un derecho ante el tribunal peruano.
Desaparecida la causa de suspensión, la prescripción reanuda su curso adicionándose el tiempo
transcurrido anteriormente.
Interrupción de la prescripción: La prescripción se interrumpe por:
- Reconocimiento de la obligación.
- Intimación para constituir en mora al deudor.
- Citación con la demanda o por otro acto con el que se notifica al deudor, aun cuando se
haya acudido a un juez o autoridad incompetente.
- Oponer judicialmente la compensación.
Plazos prescriptoriosestablecidos: Prescriben, salvo disposición diversa de la ley:
1. A los diez años, la acción personal, la acción real, la que nace de una ejecutoria y la de
nulidad del acto jurídico.
2. A los siete años, la acción de dañosy perjuicios derivados para las partes de la violación de
un acto simulado.
3. A los tres años, la acción para el pago de remuneraciones por servicios prestados como
consecuencia de vínculo no laboral.
4. A los dos años, la acción de anulabilidad, la acción revocatoria, la acción indemnizatoria
por responsabilidad extracontractual y la que corresponda contra los representantes de
incapaces derivadas del ejercicio del cargo.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN I
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 298 of 1506 --

UBILEX
5. A los quince años, la acción que proviene de pensión alimenticia.
La prescripción se produce vencido el últim o día del plazo.
31. Caducidad: concepto y efectos
El vocablo caducidad tiene su origen etimológico en las locuciones latinas caducus y cadere,
cuyas acepciones son, entre otras, las de dejar de ser, desaparecer, acabar la vida, la de term i
nar, extinguirse. El Diccionario de la Real Academia de la Lengua le da, atendiendo a su origen
etimológico, el significado de perder su fuerza una ley, un testamento o un contrato, y el de
extinguirse un derecho, una facultad, una instancia o un recurso, entre otras. De ahí, entonces,
que llevado el vocablo a su significado jurídico sea el de un anuncio o advertencia de una fu tu
ra e inexorable extinción de los derechos por el transcurso del tiempo.
Según lo regulado en el artículo 2003o del Código Civil, la norma precisa que la caducidad, al
extinguir el derecho, extingue también la acción que genera o, para mayor claridad, la pre
tensión que ha debido hacerse valer dentro del plazo prefijado por la ley. Esta norma debe
entenderse no referida propiamente a la acción sino a la pretensión, que es la expresión de la
exigibilidad del derecho que se quiere hacer valer mediante el ejercicio de la acción.
En la caducidad el orden público está más acentuado que en la prescripción extintiva, pues el
imperativo de la ley por definir o resolver una situación jurídica se aprecia con mayor rotundi
dad, haciéndolo prontamente mediante sus plazos prefijados.
Fijación de plazos: Los plazos de caducidad los fija la ley, sin a dm itir pacto contrario.
Continuidad: La caducidad no admite interrupción ni suspensión, salvo el caso previsto en el
artículo 1994° inciso 8 del Código Civil.
Declaración: La caducidad puede ser declarada de oficio o a petición de parte.
Plazo final de la caducidad: La caducidad se produce transcurrido el últim o día del plazo,
aunque éste sea inhábil.
33. Medios alternativos de solución de conflictos: Autocomposición y heterocomposición
El conflicto se puede presentar de diversas maneras y ámbitos para enfrentarlo existen di
ferentes mecanismos, siendo los más importantes: la autotutela, la heterocomposición y la
autocomposición.
La autotutela.
Es entendida como defensa propia, empleada con el objeto de defender un bien jurídico
como la vida o la posesión de un bien. Dado que a través de la autotutela se busca solo po
ner a salvo un bien jurídico, tiene el carácter de provisional y limitado. En materia penal,
la expresión más común de autotutela es la legítima defensa, regulada en el artículo 20o
inciso 3) del Código Penal.
La heterocomposición
Es la solución al conflicto a través de la intervención de un tercero imparcial, con podery
autoridad suficiente para imponer su decisión. Dicho tercero puede ser el juez en el pro
ceso judicial o el árbitro en el arbitraje.
BALOTARIO DESARROLLADO PARA LOS EXAMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 299 of 1506 --

Tema 1: Temas com unes a la especialidad: Civil, Familia y Comercial
La autocomposición
Es la solución del conflicto por parte de los propios protagonistas o intervinientes en el
mismo. De manera similar a la heterocomposición, en la autocomposición puede inter
venir un tercero ajeno a la relación, sin embargo, el tercero no puede ni debe imponer su
decisión o fórm ula de solución. Los mecanismos más conocidos son la negociación, la
mediación y la conciliación.
La negociación implica la intervención de las partes o representantes con la finalidad de buscar
en principio, beneficios mutuos. Incluso, cabe la posibilidad de ser empleada sin que exista un
conflicto previo, eso sí, mantener la comunicación es importante para lograr un intercambio
favorable de posiciones e intereses.
La mediación es un mecanismo interesante pero que no tiene regulación legal en nuestro orde
namiento; sin embargo, puede ser utilizado en ámbitos como el educativo u organizacional.
33. Conciliación
La conciliación es un procedimiento o camino previo al proceso judicial que implica la partici
pación de un conciliador, las partesysus representantes,yquetienecom oobjetivoel deevitar
e! proceso judicial o concluirlo por acuerdo libre de aquéllos. Es en esencia una negociación,
pero con la intervención del tercero quien ayuda en el proceso de comunicación.
La conciliación puede darse en dos ámbitos: extrajudicial o intraprocesal.
La conciliación se caracteriza por ser un procedimiento informal (versus el proceso judicial),
consensual (prima la voluntad de las partes), resolutivo (con el acuerdo conciliatorio se da
solución al conflicto), confidencial (conciliador e intervinientes deben guardar reserva de lo
ocurrido al interior del procedimiento), voluntario (las partes no están obligadas a llegara un
acuerdo conciliatorio) y además existe actividad limitada del conciliador (el conciliador no
puede im ponerfórm ula alguna de conciliación a las partes).
Algunos principios aplicables a la conciliación son: i) el principio de libertad (voluntad para resol
ver el conflicto); ii) el principio de confidencialidad (reserva de información y actuaciones en el
proceso); iii) el principio de información del procedimiento y de las consecuencias de los acuer
dos; iv) el principio de no violencia (prevenir actos de agresión verbal o física, de lo contrario no
existirá el ambiente propicio para llevar adelante el procedimiento); y v) el principio de participa
ción (participación activa de las partes en la generación de ideasy soluciones).
La Conciliación Extrajudicial: En aplicación de la Ley de Conciliación N° 26872 modificada
porel D. Leg. N °i0 7 0 y el TUO desu Reglamento, el D.S. N° o í7-2021-]US, es un procedimiento
obligatorio. Las materias a ser resueltas mediante este procedimiento son aquellas que versan
sobre derechos disponibles de las partes, alimentos, régimen de visitas, asuntos laborales, in
demnizaciones por daños causados y otros de tipo patrimonial.
Los conciliadores pueden ser funcionarios de la administración pública, abogados, psicólogos
u otros profesionales que cuenten con la preparación previa y hayan recibido el título que los
faculta a dirigir una conciliación por parte del Ministerio de Justicia. Con la modificación a
la Ley de Conciliación, actualmente es obligatorio acudir a un Centro de Conciliación antes
de dar inicio al proceso judicial, el no hacerlo constituye una causa de improcedencia de la
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 300 of 1506 --

demanda por una manifiesta falta de interés para obrar de parte del demandante o del de
mandado (en caso de plantear reconvención).
El acta con acuerdo conciliatorio constituye título de ejecución, lo que significa que debe
contener obligaciones ciertas, expresas y exigióles. Como tal, el acta se ejecutará a través del
proceso de ejecución de resoluciones judiciales (innovación importante introducida por el D.
Leg. N ° i0 7 0 ).
La Conciliación Intraprocesal: Es aquella que se produce una vez iniciado el proceso judicial,
en ejercicio claro de la facultad que tiene el juez y las partes de resolver el conflicto en cual
quier etapa de la primera instancia; como tal es un acto trilateral (las partes, sus representan
tes y el juez). Las partes pueden rechazar la fórmula conciliatoria propuesta por el Juez; pero si
esta fórmula establece derechos iguales o mayores a los que contendrá la sentencia a emitir,
cabe la imposición una multa por rechazarla. El acuerdo conciliatorio tendrá efectos de cosa
juzgada, esto es que no se podrá cuestionar posteriormente. Y como tal, ante su incum pli
miento será el propio Juez a pedido de la parte afectada, el que ejecute el acuerdo contenido
en el acta, dentro del propio proceso, haciendo uso de los apremios que la ley le franquea. Si
bien es cierto, el Decreto Legislativo i 070 derogó los artículos 469o, 470°, 471oy 472o del Código
Procesal Civil que regulaban a la conciliación dentro del proceso judicial, nada le impide al
juez realizarla en determinados casos como, por ejemplo, divorcio por causal o alimentos, ello
en aplicación del art. III del Título Preliminardel C.C.
ARBITRAJE. Base constitucional. Clases. Principios. Es un mecanismo alternativo a la solu
ción judicial — cuasijudicial— que vincula a las partes con un árbitro. Las normas generales
que lo regulan son el Decreto Legislativo N °i07T publicado el 28 de junio de 2008 y vigente
desde el 01.09.2008.
La actual Leyes la tercera ley que regula el arbitraje en el Perú. La primera fue el Decreto Ley N°
25935 (09.12.1992) que derogó las disposiciones del Código Civil de 1984 referidas a la cláusula
compromisoria y compromiso arbitral, y las del Código Procesal Civil referidas al juicio arbi
tral. Esta primera ley de arbitraje fue derogada por la Ley General de Arbitraje, Ley N° 26572.
Ésta tomó como fuente de inspiración a la Ley Modelo de la Comisión de las Naciones Unidas
para el Derecho Mercantil Internacional, vigente hasta el 31.08.2008, derogada por la vigente
Ley de Arbitraje, Decreto Legislativo N °i07i. A diferencia de su predecesora, la actual Ley esta
blece un sistema monista para el arbitraje,ya que sus normas se aplican al arbitraje doméstico
y al arbitraje internacional.
Con respecto a la naturaleza jurídica del arbitraje, tanto la Constitución Política como el Tribu
nal Constitucional han reconocido que el arbitraje es una jurisdicción de excepción. En efecto,
el art. 1390 de la Constitución Política del Perú establece que: "son principiosy derechos de la fun
ción jurisdiccional, entre otros, la unidad y exclusividad de la función jurisdiccional y no existe ni puede
establecerse jurisdicción alguna independiente, con excepción de la m ilita r y la a rb itra l”.
En esta misma línea, el Tribunal Constitucional como máximo intérprete de la Constitución,
ha establecido que:
