el ejercicio de la jurisdicción implica cuatro requisitos, a saber, a) Conflicto entre las partes: b)
Interés social en la composición del conflicto, c) Intervención del Estado mediante el órgano judi
cial, como tercero imparcial, d) Aplicación de la ley o integración del derecho, (...), que prima facie la
confSüéfjda de estos cuatro requisitos defiherflá naturaleza de lajurisdicciómarbitral, suponiendo^
un ejercicio de la potestad de administrarjusticia (...)" STC Exp N° 6167-20Q5-HC/TC. Caso Fernando
Cmimrias Salaverry. Fj. 8,
Sin perjuicio del reconocimiento constitucional de la jurisdicción arbitral, el arbitraje es re
conocido como un mecanismo alternativo de solución de controversias que se funda en la
autonomía de la voluntad de las partes que acuerdan libremente someter sus conflictos a la
decisión de un tribunal arbitral; esto significa que de ocurrir alguna controversia en la etapa
de ejecución contractual, éstas se obligan a no acudirá la vía judicial. Relevante es que en caso
que la persona o empresa contrate con el Estado, el arbitraje se torna obligatorio o forzoso por
mandato de la Ley de Contrataciones, a diferencia de lo que sucede en un contrato privado en
el que se puede negociar el tipo de solución, y escoger entre el arbitraje o el proceso judicial.
Clases:
A rbitraje ad hoc.-Cuando es conducido por un tribunal arbitral directamente, de acuerdo a las
reglas procedimentales que se establezcan de conformidad con la Ley de Arbitraje.
A rbitraje institucional.- Cuando es organizado y administrado por una institución arbitral que
se encarga de organizary administrar el arbitraje. La Ley de Arbitraje no exige mayores requi
sitos para su creación, únicamente exige que sean personas jurídicas con o sin fines de lucro
A rbitraje internacional - La actual Ley no define qué es un arbitraje internacional. No obstante,
el artículo 5o de la Ley señala que un arbitraje tendrá el carácter de internacional cuando en él
concurra alguna de las siguientes circunstancias:
a) Si las partes que intervienen en el convenio tienen sus domicilios en diferentes Estados
cuando se produce la celebración de dicho acto.
b) Si de acuerdo a lo pactado en el convenio arbitral, o con arreglo a éste, la sede del arbitraje
se ubica fuera del lugar de domicilio de las partes.
c) Tratándose de partes domiciliadas en el Perú, se considerará que un arbitraje es interna
cional cuando el lugar de cumplimiento de una parte sustancial de las obligaciones de la
relación jurídica se encuentra fuera del territorio nacional.
d) Por último, si las partes que intervienen en el convenio se encuentran domiciliadas en el
Perú, pero el lugar con el cual el objeto de la discusión tiene una relación más estrecha,
está fuera del territorio peruano el arbitraje también será considerado internacional.
Principios:
Principio de autonomía o separabilidad del convenio arbitral - La Ley regula expresamente este prin
cipio fundamental del arbitraje en el artículo 41.2 al disponer que el convenio arbitral que for
me parte de un contrato se considera como un acuerdo independiente de las demás estipula
ciones del mismo. Por lo tanto, la inexistencia, nulidad, anulabilidad, invalidez o ineficacia de
un contrato que contenga un convenio arbitral, no implica necesariamente la inexistencia, nu
lidad, anulabilidad, invalidez o ineficacia de éste. En consecuencia, el tribunal arbitral, sobre la
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 302 of 1506 --

UBILEX
base del principio kompetenz-kompetenz, es el competente para decidir sobre la controversia
sometida a su conocimiento, la que podrá versar, incluso, sobre la inexistencia, nulidad, anula-
bilidad, invalidez o ineficacia del contrato que contiene un convenio arbitral.
Principio de libertad de regulación.-Julio Cesar Rivera sostiene que “la primera regla que debe
aprehenderse para comprender el funcionamiento del procedimiento arbitral es que tiene
como fuente primordial el acuerdo de las partes. Ellas han de determinar, de común acuer
do, las reglas a las que se sujetará el procedimiento” La voluntad de las partes es la primera
fuente normativa para determinar las reglas del arbitraje; sin embargo, las partes deben tener
presente que su libertad contractual tiene como límites al orden público y las normas legales
imperativas.
Principio de buena fe - Las partes tienen la obligación de comportarse de acuerdo al principio
de la buena fe, esto es, a mantener una conducta idónea en todos los actos e intervenciones
que realicen dentro del proceso arbitral. Asimismo, tienen la obligación de colaborar con el
tribunal arbitral para el normal desarrollo del arbitraje.
Principio de confidencialidad.- En virtud de este principio, el tribunal arbitral, el secretario arbi
tral, las partes, los abogados, los asesores, los testigos, los peritosy cualquier otra persona que
intervenga en las actuaciones arbitrales, deben guardar reserva de las actuaciones arbitrales,
del laudo, así como cualquier información que se conozca a través de éstas.
Principio de ig ualdad.-La Ley recoge el princi pió de igualdad en su artículo 3 4 .2° al disponer que
el tribunal arbitral debe tratar a las partes con igualdady darle a cada una de ellas la suficiente
oportunidad para hacer valer sus derechos.
Principio de contradicción - Este principio resulta necesario, ya que permite al árbitro llegar por
el análisis profundo de las circunstancias y de las alegaciones de partes al conocimiento de la
litis y a través de ella a la verdad material.
34. Convenio arbitral. Actuaciones arbitrales
Concepto: El convenio arbitral es el acuerdo por el que las partes deciden someter a arbitraje
todas las controversias o ciertas controversias que hayan surgido o puedan surgir entre ellas
respecto de una determinada relación jurídica contractual o de otra naturaleza.
En la ley peruana, el convenio arbitral es un acto únicoy autosufkiente para que se inicie un ar
bitraje, por lo tanto, ya no se requiere de la ulteriorcelebración del problemático compromiso
arbitral, basta la celebración de un solo contrato: el convenio arbitral.
El convenio arbitral, según el art. 13o de la Ley, puede adoptar la fórm ula de una cláusula inclui
da en un contrato o la forma de un acuerdo independiente.
Clases: La actual Ley también regula dos supuestos especiales del convenio arbitral:
a. El Arbitraje Estatutario o Societario: La Ley permite que en el estatuto de una persona jurí
dica se pueda incluir un convenio arbitral para resolver las controversias entre la persona
jurídicay sus miembros, directivos, administradores, representantes,y funcionarios o las
que surjan entre ellos respecto de sus derechos u obligaciones o las relativas al cum pli
miento de los estatutos o la validez de los acuerdos.
302 BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 303 of 1506 --

Tema 1: Temas com unes a la especialidad: Civil, Familia y Comercial
I
b. El A rbitraje Sucesorio o Testamentario: Es el convenio arbitral que el causante incorpora en su
testamentoy mediante el cual disponed sometimiento a arbitraje de las posibles contro
versias que surjan entre los sucesores, o de ellos con sus albaceas, incluyendo las relativas
al inventario de la masa hereditaria, su valoración, administración y partición.
Requisitos: La Ley no exige ningún requisito solemne para la celebración de un convenio arbi
tral, únicamente señala que el convenio arbitral conste por escrito.
Validez: En el derecho peruano, el convenio arbitral debe reunir los siguientes requisitos para
su validez:
(i) Capacidad jurídica de los contratantes,
(ii) Consentimiento libre de vicios,
(i i i) Objeto lícito (físicay jurídicamente posible); y,
(iv) Fin lícito.
35. Actuaciones arbitrales
La Ley sigue el modelo internacional en cuanto al trám ite de las actuaciones.
1. Sede de! arbitraje y sede de las actuaciones arbitrales.- La Ley pone de relieve la autonomía de
lavoluntadde las partes,ya que éstas tienen lafacultadde determinar la sede del arbitra
je. Ante el silencio de las partes, el tribunal arbitral deberá asumir dicha labor atendiendo
a las circunstancias del casoy la conveniencia de las partes.
2. Idioma.- La Ley deja abierta a las partes la posibilidad de elegir libremente el idioma o
idiomas que se deberán utilizar en el procedimiento arbitral, afortunadamente no con
templa el uso obligatorio del idioma español en los arbitrajes internacionales. A falta de
acuerdo entre las partes, será el tribunal arbitral el encargado de determinar el idioma o
idiomas del arbitraje, desde luego, atendiendo a las circunstancias del caso.
3. Inicioy curso de las actuaciones arbitrales.- El artículo 33° de la Ley establece que las partes
pueden acordar la fecha de inicio del arbitraje. A falta de acuerdo, supletoriamente la Ley
dispone que el inicio del procedimiento arbitral será determinado por la fecha de recep
ción de lasolicitud para someter una controversia a arbitraje. Unavez más podemos com
probar que resulta innegable la amplia flexibilidad que la Ley otorga a las partes y a los
árbitros en el arbitraje.
4 . Apoyoy auxilio de los jueces en el arbitraje internacional - De conformidad con el artículo 48o
de la Ley, las partes pueden pedir la colaboración de los tribunales judiciales para la eje
cución de medidas cautelares que el propio tribunal no pueda ejecutarlas. Las medidas
cautelares ordenadas por un tribunal arbitral cuyo lugar se halle fuera del territorio pe
ruano, deberán ser reconocidas y ejecutadas conforme al procedimiento para el recono
cimiento y ejecución de laudos extranjeros.
Para proceder al reconocimiento, de la decisión que contiene la medida cautelar, la parte
deberá presentar el original o copia de la medida cautelar. Por su parte, la autoridad ju d i
cial podrá exigir que se preste garantía adecuada, cuando el tribunal arbitral no se haya
pronunciado sobre tal garantía o cuando sea necesaria para proteger derechos de terce-
