ros, en caso de incumplimiento de este requisito, la autoridad judicial podrá rechazar la
solicitud de reconocimiento.
El tribunal arbitral o cualquiera de las partes con su aprobación, también pueden pedir
asistencia judicial para la actuación de pruebas, para lo cual deberán acompañar las co
pias del documento que acredite la existencia del arbitraje y la decisión que faculte a la
parte interesada a recurrirá dicha asistencia.
En cuanto a la competencia en la colaboración y control judicial, el artículo 8 o de la Ley
establece que: (i) Para la actuación de pruebas será competente el juez Subespecializado
en lo Comercial o, en su defecto, el juez Especializado en lo Civil del lugar del arbitraje o el
del lugar donde hubiere de prestarse la asistencia. Cuando la prueba deba actuarse en el
extranjero se estará a los tratados sobre obtención de pruebas en el extranjero o a la legis
lación nacional aplicable, (ii) Para la adopción judicial de medidas cautelares será compe
tente el juez Subespecializado en lo Comercial o, en su defecto, el juez Especializado en lo
Civil del lugar en que la medida deba ser ejecutada o el del lugar donde las medidas de
ban producir su eficacia. Cuando la medida cautelar deba adoptarse o ejecutarse en el ex
tranjero se estará a los tratados sobre ejecución de medidas cautelares en el extranjero o a
la legislación nacional aplicable, (iii) Para la ejecución forzosa del laudo será competente
el juez Subespecializado en lo Comercial o, en su defecto, el juez Civil del lugar del arbi
traje o el del lugar donde el laudo debe producir su eficacia, (iv) Para conocer del recurso
de anulación del laudo será competente la Sala Civil Subespecializada en lo Comercial o,
en su defecto, la Sala Civil de la Corte Superior de justicia del lugar del arbitraje, (v) Para el
reconocimiento de laudos extranjeros será competente la Sala Civil Subespecializada en
lo Comercial o, en su defecto, la Sala Civil de la Corte Superior de justicia del dom icilio del
emplazado o, si el emplazado no domicilia dentro del territorio peruano, del lugar donde
tenga sus bienes o donde ejerza sus derechos, (vi) Para la ejecución de laudos extranjeros
debidamente reconocidos será competente el juez Subespecializado en lo Comercial o,
en su defecto, el juez Civil, del domicilio del emplazado o, si el emplazado no domicilia
dentro del territorio peruano, del lugar donde tenga sus bienes o donde ejerza sus dere
chos.
5. Control de los jueces en el arbitraje internacional - El artículo 62.1o de la Ley de manera expre
sa dispone que contra el laudo sólo podrá interponerse recurso de anulación. Agrega, el
recurso de anulación constituye la única vía de impugnación del laudo y éste tiene por
objeto únicamente la revisión de su validez por las causales taxativamente establecidas
en la Ley. De conformidad con lo previsto en la actual Ley, los tribunales judiciales tienen
prohibido — bajo responsabilidad— , pronunciarse sobre el fondo de la controversia o
sobre el contenido de la decisión o calificar los criterios, motivaciones o interpretaciones
expuestas por el tribunal arbitral.
En ese sentido, el artículo 7.2o del NCPConst., establece que no proceden los procesos
constitucionales (acción de amparo, acción de hábeas data, acción de cumplimiento),
cuando existan vías procedimentales específicas, igualmente satisfactorias, para la pro
tección del derecho constitucional amenazado o vul nerado, salvo cuando se trate del pro
ceso de hábeas Corpus. Por su parte, la Ley dispone que para efectos de lo dispuesto en el
