Tema 1: Temas com unes a la especialidad: Civil, Familia y Comercial
artículo 7.2o del NCPConst, se entiende que el recurso de anulación del laudo es una vía
específica e idónea para proteger cualquier derecho constitucional amenazado o vulne
rado en el curso del arbitraje o en el laudo.
36. Laudo arbitral. Ejecución del laudo y de las medidas cautelares. Anulación de laudo
arbitral
Laudo arbitral: El laudo arbitral es la decisión adoptada por los árbitros con respecto a la ma
teria objeto de controversia en el arbitraje.
El artículo 59o de la Ley establece que todo laudo es definitivo, inapelable y de obligatorio
cumplim iento desde su notificación a las partes y, por lo tanto, produce efectos de cosa juz
gada.
Clases:
i. Laudos finales, a la decisión que resuelve de manera definitiva todas las disputas someti
das a conocimiento de los árbitros y que implica la culminación del arbitraje.
ii. Los laudos parciales, son aquellos que resuelven, también de manera definitiva, parte de
la controversia, dejando pendiente de resolver otros aspectos o puntos controvertidos del
conflicto.
Ambas clases de laudos son definitivos y de obligatorio cumplimiento.
Requisitos: Respecto a los requisitos formales del laudo, el artículo 55° de Ley dispone que
todo laudo deberá constar por escrito y debe ser firmado por los árbitros, los que podrán ex-
presarsuopinión discrepantedeserel caso.
Respecto del contenido del laudo el artículo 56o de la Ley prevé, todo laudo deberá ser mo
tivado, a menos que las partes hayan convenido algo distinto o que se trate de un laudo que
contenga una transacción de las partes.
El laudo debe contener la fecha y el lugar del arbitraje, así como la asunción o distribución
de los costos del arbitraje. Debe tenerse presente que la controversia debe decidirse y noti
ficarse dentro del plazo establecido por las partes, por el reglamento arbitral aplicable o en
su defecto por el tribunal arbitral (artículo 53° de la Ley). Si el laudo es dictado fuera del plazo
establecido, las partes podrían solicitar la anulación del laudo arbitral, de conformidad por el
artículo 63.1 °(g) de la Ley.
Medidas Cautelares: La facultad de los árbitros para otorgar medidas cautelares está sujeta a
que el tribunal arbitral se encuentre debidamente constituido.
El otorgamiento de medidas cautelares arbitrales tiene como finalidad asegurar la eficacia
del laudo.
La medida cautelar será temporal y estará contenida en una decisión que tenga o no forma de
laudo. En tal sentido, en cualquier momento previo a la emisión del laudo que resuelva defini
tivamente la controversia, el tribunal arbitral podrá ordenar a una de las partes cualquiera de
las siguientes medidas cautelares:
(i) Que mantenga o restablezca el statu quo en espera de que se resuelva la controversia;
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES 305

