UBILEX
(i¡) Que adopte medidas para impedir algún daño actual o inminente o el menoscabo del
proceso arbitral, o que se abstenga de llevara cabo ciertos actos que probablemente oca
sionarían dicho daño o menoscabo al proceso arbitral;
(iii) Que proporcione algún medio para preservar bienes que permitan ejecutar el laudo sub
siguiente; o
(iv) Que preserve elementos de prueba que pudieran ser relevantes y pertinentes para resol
ver la controversia.
La actual Ley dispone que el tribunal arbitral deberá poner en conocimiento de la contraparte
la solicitud de la medida cautelar, con lo cual se elimina la regla inaudita parte.
Excepcionalmente, el tribunal podrá conceder medida cautelar sin necesidad de poner en
conocimiento de la contraparte, cuando la solicitante cumpla con acreditaro justificar la nece
sidad de no hacerlo para garantizar la eficacia de la medida que ha de adoptarse. Además de
ello, se faculta a la contraparte para que una vez ejecutada la medida pueda form ular reconsi
deración contra la decisión del tribunal arbitral. Asimismo, el tribunal arbitral está facultado
para modificar, sustituir y dejar sin efecto las medidas cautelares que haya ordenado una au
toridad judicial, incluso si se trata de decisiones judiciales firmes.
La Ley prevé que en el arbitraje internacional, las partes durante el transcurso de las actua
ciones pueden solicitar a la autoridad judicial competente, previa autorización del tribunal
arbitral (si ya está constituido), la adopción de las medidas cautelares que estimen convenien
tes. En todo caso, las partes pueden incluso antes de haberse iniciado el arbitraje, solicitar las
medidas necesarias a la autoridad judicial competente.
Ejecución de las medidas cautelares: En lo relativo a la ejecución de las medidas cautelares
por la autoridad judicial, ésta no tiene competencia para interpretarel contenido ni los alcan
ces de la medida cautelar.
En consecuencia, cualquiersolicitudde aclaración o precisión sobre los mismos osobre la eje
cución cautelar, será solicitada por la autoridad judicial o por las partes al tribunal arbitral. En
caso de no existir aclaración alguna, el órgano jurisdiccional ordenará la ejecución de la medi
da sin mayordilación. Ejecutada la medida, la autoridad judicial informará al tribunal arbitral
y remitirá copia certificada de los actuados.
Ejecución del laudo arbitral:
Ejecución arbitral.-A solicitud de parte, el tribunal arbitral está facultado para ejecutar
sus laudosy decisiones, siempre que medie acuerdo de las partes o se encuentre previsto
en el reglamento arbitral aplicable. Se exceptúa de lo señalado, el caso en el cual, a su sola
discreción, el tribunal arbitral considere necesario o conveniente requerir la asistencia de
la fuerza pública. En este caso, cesará en sus funciones sin incurrir en responsabilidad y
entregará a la parte interesada, a costo de ésta, copia de los actuados correspondientes
para que recurra a la autoridad judicial competente a efectos de la ejecución.
Ejecución judicial. La parte interesada podrá solicitar la ejecución del laudo ante la auto
ridad judicial competente acompañando copia de éste y de sus rectificaciones, interpre
taciones, integraciones y exclusiones y, en su caso, de las actuaciones de ejecución efec
tuada por el tribunal arbitral.
