La autoridad judicial, dictará mandato de ejecución para que la parte ejecutada
cumpla con su obligación dentro de un plazo déos días, bajo apercibimiento de eje
cución forzada.
La parte ejecutada sólo podrá oponerse si acredita con documentos el cumplim iento
de la obligación requerida o la suspensión de la ejecución conforme al artículo 6 6 .
La autoridad judicial dará traslado de la oposición a la otra parte por el plazo de 05
días. Vencido este plazo, resolverá dentro de los 05 días siguientes. La resolución que
declara fundada la oposición es apelable con efecto suspensivo.
La autoridad judicial está prohibida, bajo responsabilidad, de adm itir recursos que
entorpezcan la ejecución del laudo.
37. Anulación de laudo arbitral
El recurso de anulación es el único recurso impugnativo que podrá interponerse contra el lau
do arbitral (Artículo 62o de la Ley).
El recurso de anulación del laudo es la vía específica e idónea para proteger cualquier derecho
constitucional amenazado o vulnerado en el curso del arbitraje o en el laudo, con lo cual ex
cluye la posibilidad de acciones de amparo contra los laudos.
El recurso de anulación tiene por objeto la revisión de la validez del laudo en las causales taxa
tivamente señaladas en la Ley.
De conformidad con el artículo 63o de la Ley, el laudo sólo podrá ser anulado cuando la parte
que solicita la anulación aleguey pruebe:
a) Que el convenio arbitral sea inexistente, nulo, anulable, inválido o ineficaz.
b) Que una de las partes no ha sido debidamente notificada del nombramiento de un árbi
tro o de las actuaciones arbitrales, o no ha podido porcualquierotra razón, hacervalersus
derechos.
c) Que la composición del tribunal arbitral o las actuaciones arbitrales no se han ajustado
al acuerdo entre las partes o al reglamento arbitral aplicable, salvo que dicho acuerdo o
disposición estuvieran en conflicto con una disposición de la Ley de la que las partes no
pudieran apartarse, o en defecto de que dicho acuerdo o reglamento, no se ha ajustado a
lo establecido en la Ley.
d) Que el tribunal arbitral ha resuelto sobre materias no sometidas a su decisión.
e) Que el tribunal arbitral ha resuelto sobre materias que, de acuerdo a ley, son manifiesta
mente no susceptibles de arbitraje, tratándose de un arbitraje nacional.
f) Que según las leyes peruanas, el objeto de la controversia no es susceptible de arbitraje o el
laudo es contrario al orden público internacional, tratándose de un arbitraje internacional.
g) Que la controversia ha sido decidida fuera del plazo pactado por las partes, previsto en el
reglamento arbitral aplicable o establecido por el tribunal arbitral.
Tratándose de las causales previstas en los incisos a), b), c) y d), sólo será procedente el recurso
de anulación si dichas causales fueron objeto de reclamo expreso en su momento ante el tri
bunal arbitral por la parte afectada y dichos reclamos fueron desestimados.
