Tratándose de las causales previstas en los incisos d) y e), la anulación afectará solamente a las
materias no sometidas a arbitraje o no susceptibles de arbitraje, siempre que puedan separar
se de las demás; caso contrario, la anulación será total. Asimismo, la causal prevista en el inci
so e) podrá ser apreciada de oficio por la Corte Superior que conoce del recurso de anulación.
En el caso del arbitraje internacional, la causal prevista en el inciso f) podrá ser apreciada de
oficio por la Corte Superior de Justicia que conoce del recurso de anulación. Respecto a la cau
sal prevista en el inciso g) sólo será procedente si la parte afectada lo hubiera manifestado por
escrito de manera inequívoca al tribunal arbitral y que su comportamiento en las actuaciones
posteriores no sea incompatible con este reclamo.
Finalmente, procederá la anulación del laudo si la causal que se invoca ha podido ser subsa
nada mediante rectificación, interpretación, integración o exclusión del laudo y la parte inte
resada no cumplió con solicitarlos.
38. Amparo arbitral
Según el artículo 45 del Nuevo Código Procesal Constitucional, el amparo arbitral es un proce
so que se puede iniciar contra un laudo arbitral que tiene la condición de firme.
Sí la afectación de derechos se origina de un laudo arbitral, es competente la sala constitucio
nal o, si no lo hubiere, la sala civil de turno de la corte superior de justicia respectiva y la Sala
Constitucional y Social de la Corte Suprema es competente para resolver en segundo grado.
El plazo para presentar la demanda es de 30 días hábiles, y se inicia a partir de la notificación
del laudo arbitral.
Respecto de la posibilidad de cuestionar un laudo arbitral ante la vía del proceso constitucio
nal el Tribunal Constitucional ha señalado-.
“Eqiuh hecho JnCórJrpvédjblé que:existe la posibilidad de cuestionar, porfía v id dé! proceso
ooristitucional, upa resolución arbitral,: Está, por tanto, debe ser considerada comó Ja dnicáiop-
ción válida constitucionalmente, habida cuenta de que bajo determinados supuestos procede ¡
el proceso constitucional contra resoluciones provenientes tanto del Poder Judicial como de un
TribunaI Militar (artículo 4 del Código Procesal Constitucional). En esa medida, no existe respal
do constitucional que impida recurrir al proceso constitucional frente a la jurisdicción arbitral,"
Exp. 6167-200S-PHC/TC, Fj 23.
Cabe precisar que, el 5 de octubre de 2011, el Tribunal Constitucional publicó en el diario oficial
El Peruano la sentencia dictada en el Expediente 00142-2011-PA/TC, que, con calidad de pre
cedente, establece las nuevas reglas en materia de amparo contra las decisiones emanadas de
la jurisdicción arbitral. En el referido precedente se estableció que el recurso de anulación pre
visto en el Decreto Legislativo 1071, que n orm a d arbitrajey, por razones de temporalidad, los
recursos de apelación y anulación para aquellos procesos sujetos a la Ley General de Arbitraje
(Ley 26572), constituyen vías procedimentales específicas, igualmente satisfactorias, para la
protección de derechos constitucionales.
