l i i . D E R E C H O P R O C E S A L
El Derecho Procesal es la rama del Derecho que estudia el fenómeno jurídico llamado proceso
y los problemas que le son conexos.
El objeto de estudio no es sólo el proceso, el Derecho Procesal explicará conceptos como: ac
ción, pretensión y demanda; actor, juez y demandado; reacción del demandado, confirmación
de las pretensiones, actividad que cumple el juez, litigio, etc. poniendo mayor énfasis a la ac
tividad judicial.
Sistemas procesales: El proceso no tiene una historia propia sino más bien un destino asig
nado por la naturaleza jurídica, ideología y fines de los derechos materiales en una sociedad.
Sin embargo, si bien es indudable que los derechos materiales definen la trascendencia del
proceso, este constituye material para la elaboración de una ciencia en tanto tiene categorías,
criterios clasifícatenos, instituciones, métodos de interpretación, estructura y aun sistemas
propios. En este contexto, el cómo realice el proceso su función instrumental respecto de los
derechos materiales es determinante para la configuración de por lo menos dos sistemas pro
cesales claramente definidos. A continuación, explicaremos cada uno:
Sistema procesal privatístico: Según Monroy Calvez9, la ideología liberal, emergida de la Re
volución Francesa, no solo influyó en el pensamiento político mundial, sino también y de ma
nera trascendente en las ciencias jurídicas y, por cierto, en el proceso. El postulado de libertad,
por ejemplo, fue llevado al campo de los derechos civiles, en donde se afirmó que estos eran
de control y disposición absol utos y totales de sus titulares, sin ningún tipo de restricción y, por
eso, eran derechos privados. Esta consideración se aplicó también en el ámbito procesal: si en
el proceso civil se discuten derechos civiles y estos son privados, entonces el proceso civil es
también una actividad privada. Hasta mediados del siglo pasado, en toda Europa se le siguió
denominando Sache der Parteien (Cosa de las Partes), como recuerda CAPPELLETTI.
Sistema procesal publicístico: Continuando con lo afirmado por Monroy Calvez, lo oneroso y
absurdo del sistema privatístico planteó al procesalista la imperiosa necesidad de un cambio
de rumbo. En principio, la reforma consistió en reducir el considerable apogeo de la escritu
ra en el desarrollo de la actividad procesal. Como una alternativa de volverlo expeditivo, se
resolvió optar por la oralidad. El primer intento serio es el código de procedimiento civil de
Hannover de 1850, elaborado por Cerhard Adolf W ilheim Leonhardt. Sin embargo, los que
resultan abanderados en la tendencia de reforma son: el código de procedimiento alemán
(Zivilprozessordnung) de 1879— aún vigente en nuestros días— y, fundamentalmente, el có
digo de procedimiento austríaco vigente desde 1898, producto del talento de Franz Klein. En
8 Pleno. Sentencia 121/2024. FJ. 5 ,6.
9 MONROY GÁLVEZ, Juan. “Introducción al proceso civil". T. I. Ed. Temis. Colombia, p. 55.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES 309

-- 310 of 1506 --

UBILEX
las dos primeras décadas de este siglo, prácticamente todos los códigos europeos— excepto el
español— optaron por el predominio de la oralidad. Esta vigencia de la oralidad fue el punto
de partida de la afirmación de un nuevo sistema que, por las razones que se detallan a conti
nuación, recibe el nombre de sistema publicístico.
Diferencia sustancial entre los sistemas privatístico y publicístico: La diferencia entre los
dos sistemas que hemos descrito, según Monroy Cálvez, se asienta en la respuesta a una
pregunta específica: ¿Quién sirve a quién? Los sujetos que actúan como objeto de la pre
gunta son el Estado y los particulares. Dentro de una concepción privatística, el proceso es
el medio a través del cual el Estado concede a los particulares la oportunidad de resolver su
conflicto de intereses. Por esta razón, como el Estado está a disposición de los particulares,
el proceso, que es el vehículo del servicio, está bajo el control de quienes lo reciben, es decir,
de los particulares. Sin embargo, la misma pregunta puede tener una respuesta distinta. La
trascendencia social del proceso, expresada en la presencia exclusiva y hegemónica del Es
tado, determinó que se advirtiera el carácter público de aquel. Pero no solo eso. Muy pronto
se constató que lo más importante en el proceso no es que los particulares resolvieran su
conflicto sino que, a través de él, el derecho objetivo — creado por el propio Estado— se
tornara eficaz y respetado, y asimismo, a través de la exigencia judicial del cum plim iento del
derecho objetivo, se lograra la paz social en justicia. Como se advierte, tanto la eficacia del
derecho objetivo como el fin de la paz social en justicia son extraparticulares, y de alguna
manera extraprocesales, por así decirlo.
Es así como empieza a afirmarse la concepción del proceso como un fenómeno público y se
le considera sujeto a normas previstas por el Estado con anticipación al conflicto, normas que
también son de naturaleza pública, entre otras razones por su vocación imperativa. Con lo
dicho, a la pregunta: ¿quién sirve a quién?, la respuesta empieza a variar. Así, resulta que las
partes al enfrentarse en un conflicto de intereses brindan al Estado la oportunidad de reafir
mar la eficacia del derecho objetivo para lograr la paz social en justicia.
En consecuencia, el proceso pasa a ser una actividad pública, sujeto a normas de derecho
público. Sin perjuicio del desarrollo de los principios que sustentan este sistema, es con
veniente destacar dos hechos. En primer lugar, el sistema publicístico ha pasado a ser en
este siglo la alternativa más común y científicamente más aceptable para el diseño de un
determinado ordenamiento procesal, al punto que mantener un esquema privatístico es
signo de obsolescencia grave o aguda, según se mantengan vigentes ordenamientos estric
tamente ceñidos a las tesis decimonónicas del liberalismo individualista, o a los postulados
romano-canónica-comunes del ordo iu á k m u m privatorum . En segundo lugar, cabe precisar
que este apogeo ha generado una paradoja— citada anteriorm ente— de considerable im
portancia, Dado que la tendencia contemporánea en materia de derecho civil y comercial
— nos referimos al derecho material del cual el proceso civil es su instrum ento— es retornar
a los esquemas privatistas de hace dos siglos, hoy se reafirma la vieja tesis de considerar
privadísimos tales derechos materiales. Por otro lado, al haberse afianzado el sistema publi
cístico, resulta que en la actualidad al interior de una función pública se discuten derechos
privados.
10 BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 311 of 1506 --

Tema 1: Temas com unes a la especialidad: Civil, Familia y Comercial
1. Acción civil
La acción es el derecho que tiene todo justiciable a fin de solicitarle al Estado active su función
jurisdiccional. La acción es el derecho a la jurisdicción. Todo derecho tiene como su correlativo
al deber. Al ejercitarse la acción, la jurisdicción constituye un deber del Estado de solucionar
los conflictos de intereses o incertidumbres jurídicas.
El derecho de acción es reconocido como un derecho fundamental bajo el ropaje de derecho
a una tutela jurisdiccional efectiva, en su primera parte de acceso a la justicia. Para CARNELU-
TTI era el principal derecho,ya que, sin él, la vulneración del resto de derechos quedaría en la
orfandad de protección.
Elementos y caracteres de la acción:
Tres son los elementos de la acción:
El Sujeto: Los sujetos son dos: activo y pasivo; el primero es aquel a quien corresponde el
poder jurídico de obrar, y el segundo es aquel a cuyo cargo se producen los efectos ju ríd i
cos de la acción.
La causa-. Es el fundamento del ejercicio de la acción.
El objeto: Éste está constituido por los efectos jurídicos que se persiguen con el ejercicio de
la acción, o sea, el cumplimiento de la obligación por todos los medios posibles.
El derecho de acción se caracteriza porser público, subjetivo, abstractoy autónomo. Es público
y subjetivo, porque el justiciable se dirige al Estado; es abstracto, porque se diferencia de la
pretensión procesal; es autónomo, porque desde mediados del siglo~m~.se independiza del
derecho sustantivo.
Clasificación de la acción.- Las acciones se clasifican:
i. Por su naturaleza. Las acciones se dividen en patrimoniales y no patrimoniales. Las pri
meras tienen como fin la protección de un patrimonio, mientras que las segundas se re
fieren a derechos concernientes al estado de las personas.
ii. Por su objeto. Las acciones son reales mobi I¡arias e inmobiliarias. Las primeras se refieren
al ejercicio de derechos sobre muebles, las segundas, sobre inmuebles.
iii. Por su extensión. Las acciones pueden ser principales y accesorias. Las principales tienen
existencia propia. Las accesorias dependen de una acción principal.
iv. En cuanto a su transmisibilidad. Las acciones son cesibles e incesibles. Las acciones cesi
bles se pueden transm itir por actos intervivoso por causa mortis; las incesibles son intrans
feribles.
v. Derivadas de los hechos ilícitos. Por el dolo o culpa, nacen acciones civiles y penales. La
acción civil tiene por objeto la indemnización por el perjuicio sufrido. La acción penal per
sigue la sanción del delito, mientras esta últim a se dirige sólo contra el culpable, la civil
puede encausarse también hacia terceros. Ambas acciones pueden acumularse o ejerci
tarse separadamente.
vi. Acciones en sentido propio, han sido divididas en acciones de condena, declarativas y
constitutivas.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCION
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 312 of 1506 --

UBILEX
Las acciones de condena persiguen que el órgano jurisdiccional del Estado expida una senten
cia, obligando al demandado a una prestación a favor del actor.
Las acciones declarativas pueden ser positivas o negativas según persigan los primeras, la de
claración de la existencia de un derecho o de un hecho, y las segundas, las que persiguen la
declaración de la no existencia de un derecho o de un hecho.
Las acciones constitutivas se dirigen a modificar un estado jurídico preexistente, o a crear o
reconocer un derecho nuevo.
2. La pretensión
La pretensión es una declaración de voluntad, materializada en la interposición de la deman
da o en el ejercicio de la reconvención. Se diferencia de la acción por ser concreta y ésta abs
tracta.
Pretensión material: Denominada también sustancial, es la manifestación de voluntad de
uno a más sujetos de derecho, atribuyéndose la titularidad de un bien con exclusión o en par
ticipación con terceros. Las pretensiones materiales pueden tener o no importancia para el
Derecho; cuando tienen trascendencia o contenido jurídico, están reguladas en el derecho
material, con prevención de sus efectos, es decir, con especificación de los imperativos que
asiste a los sujetos vinculados a la pretensión.
Pretensión procesal: Es la pretensión material con relevancia jurídica formalizada porel actor
ante un órgano jurisdiccional, generalmente dirigido a un tercero emplazado, en la que se
precisa una petición, fundamentada, destinada a obtener un pronunciamiento favorable res
pecto a la satisfacción o atención en uno o más bienes o la imposición de una sanción.
La pretensión procesal es la pretensión material formalizada ante un órgano jurisdiccional.
Esta característica fija la diferencia entre la pretensión material o procesal.
3. La demanda
La demanda es el acto jurídico procesal que da inicio al proceso civil. Hace viable el derecho
de acción y contiene la pretensión del actor. Una demanda puede contener una o varias pre
tensiones.
Juan Monroy Cálvez, nos indica que la demanda, no es otra cosa que la declaración de la vo
luntad, por medio del cual una persona, haciendo uso de su derecho de acción, nos da a cono
cer dos exigencias a dos sujetos cuyos derechos son distintos.
Requisitos generales y anexos de la demanda
Tanto los requisitos de forma como de fondo se encuentran estipulados en los arts. 424y 425 del
Código Procesal Civil,y en cuanto a la forma de redacción del escrito lo tenemos estipulado en el
art. 130 del mismo código adjetivo. Los requisitos con los que debe contar un escrito, persiguen
un propósito, el cual es que se siga con un orden tanto técnico legal y científico; y con ello se
conseguirá que el objeto del proceso pueda ser discutido con toda la transparencia necesaria.
Criterios de calificación de la demanda.- En este punto se toman en consideración aspectos
como:
312 BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 313 of 1506 --

Tema 1: lem as com unes a la especialidad: Civil, Familia y Comercial
1. Admisibilidad de la demanda.- Para que el Juez pueda declarar admisible la demanda,
primero éste realiza un análisis de la existencia de los requisitos o presupuestos procesa
les, así como de las condiciones de la acción; dentro de estos tenemos: La competencia
del Juez, la capacidad procesal de las partes, los requisitos de la demanda, así como ta m
bién la titu la rid a d y el interés para obrar. Si se cuentan con los todos los requisitos señala
dos, el Juez realiza una calificación positiva, dictando el “autoadmisorio de la demanda”.
Debiendo expedirse dicha resolución, dentro de los 5 días hábiles después de presentada
la demanda. En buena cuenta, una demanda será declarada admisible si cumple con los
requisitos previstos tanto en los artículos 424,425 y 130 del Código Procesal Civil.
2. Inadmisibilidad de la demanda.- La demanda podrá ser declarada inadmisible, si no
cumple con los requisitos de forma, previstos éstos en el art 426 del Código Procesal Ci
vil los cuales los mencionaremos a continuación: No tenga los requisitos legales, no se
acompañen los anexos exigidos por ley, el petitorio sea incompleto o impreciso y la vía
procedimental propuesta no corresponda a la naturaleza del petitorio o al valor de éste,
salvo que la ley permita su adaptación Al declararse inadmisible la demanda, el Juez or
denara al demandante subsane la omisión o defectos, en un plazo no mayor a los 10 días.
Si transcurridos los diez días, el demandante no cumpliera con las correcciones respec
tivas al escrito, el Juez rechazara la demanda y ordenara la devolución de los anexos y
archivo definitivo del expediente.
3. Improcedencia de la demanda.- Para que una demanda sea declarada improcedente,
es cuando no cumple con los requisitos de fondo estipulados en el art. 427 del Código
Procesal Civil. Dentro de los requisitos por los cuales una demanda pueda ser declarada
improcedente tenemos: El demandante carezca evidentemente de titularidad para obrar,
el demandante carezca manifiestamente de interés para obrar, se advierta la caducidad
del derecho, el Juez carezca de competencia, no exista conexión lógica entre los hechos
y el petitorio, el petitorio fuese física y jurídicamente imposible, contenga una indebida
acumulación de pretensiones.
4. Derecho de contradicción
Al igual que el derecho de acción, es una expresión del derecho a la tutela jurisdiccional. El
derecho de contradicción tiene las mismas características que el derecho de acción, incluso se
identifica con éste, también en la manera como se ejercita. Es un derecho subjetivo, público,
abstracto y autónomo que permite a un sujeto de derecho emplazado exigirle al estado le
preste tutela jurisdiccional.
Cabe señalar que siempre que el demandado hace uso de su derecho de contradicción está
poniendo en práctica su derecho de defensa.
Contestación de la demanda: La contestación de la demanda, es un medio procesal, median
te el cual el demandado pone en práctica su inevitable derecho de defensa, frente a la deman
da con la que se le ha emplazado. Así, el demandado tiene la opción, de poner en práctica
su derecho de contradicción y mediante éste derecho el demandado tiene la oportunidad de
plantear una nueva pretensión procesal la cual es oponerse a la pretensión del demandante.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 314 of 1506 --

UBILEX
El derecho de contradicción persigue un propósito, el cual es declarar infundada la demanda
interpuesta por el demandado. Es conveniente advertir que el derecho de contradicción ejer
cido por el demandado, de todas formas se hará valer, a pesar de que el juez en su sentencia
acoja siempre la demanda del actory de tal forma deniegue el petitorio del demandado.
La contestación de la demanda debe cumplir con los mismos requisitos que se estipulan para
la demanda.
Es preciso señalar que el emplazado al contestar la demanda, debe pronunciarse respecto a
cada uno de los hechos dados a conocer en la demanda, por su parte el demandante debe
exponer en forma ordenada, precisa y clara en su demanda todos los hechos en los cuales
sustenta sus pretensiones procesales, de igual forma el demandado tiene que pronunciarse
sobre cada uno de los hechos dados a conocer por el actor en forma ordenada, precisay clara.
El Código Procesal Civil señala que el silencio, la respuesta evasiva o la actitud negativa por
parte del demandado, pueden ser tomados por el juez como reconocimiento de verdad de los
hechos sustentados por el demandante. Lo dicho guarda relación con los efectos que trae la
declaración de rebeldía, la cual causa también una presunción legal relativa sobre la verdad de
los hechos dados a conocer en la demanda, excepto en algunos casos que en el mismo código
se señala.
Plazos para contestar la demanda: Referente a este punto el plazo para contestar la deman
da, está fijado para cada tipo de proceso tal es así que en el proceso de conocimiento, el plazo
para contestar es de 30 días hábiles, contados desde el día del emplazamiento válido mien
tras que en el proceso abreviado es de 10 días y en el sumarísimoes de 5 días. En el caso de que
se trate de notificara personas indeterminadas o inciertas es decir de difícil ubicación, los pla
zos para contestar la demanda en in proceso de conocimiento es de 60 días siemprey cuando
el demandado se encuentre dentro del país, caso contrario si se encuentra fuera, en el proceso
abreviado el plazo es de 30 y 45 días, y en el sumarísimo el plazo se extiende a 15 y 25 días.
Anexos de la contestación de la demanda.- De igual forma que en la demanda, en la contes
tación de la demanda deben adjuntarse los documentos exigidos para la demanda, adecuán
dose obviamente a la posición que adopte el demandado frente a la demanda.
Inadmisibilidad o improcedencia de la contestación de la demanda.- La contestación de la de
manda de igual forma está supeditada a la evaluación de calificación por el juez, pudiendo ser
declarada inadmisible o improcedente, con los mismos efectos que se tienen para la demanda.
5. La jurisdicción
En sentido amplio, la jurisdicción es la exclusividad que tiene el estado para resolver conflictos
e incertidumbres jurídicas relevantes.
El artículo III Título Preliminar del C.RC. señala que uno de los fines inmediatos del proceso
es resolver conflictos de intereses e incertidumbres jurídicas; asimismo, otro de esos fines es
hacer efectivo los derechos sustanciales.
Los conflictos de intereses originan el litigio, pues existe un sujeto que pretende algo frente a
otro,y éste se resiste a cumplir las pretensiones de aquél, como son los casos de cumplim iento
de contrato, desalojo, divorcio, etc.
314 BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 315 of 1506 --

Tema 1: Temas com unes a la especialidad: Civil, Familia y Comercial
En la incertidumbre jurídica, en principio, no hay litigio. El sujeto busca la corroboración de la
existencia de un derecho, como ocurre en la sucesión intestada.
Ahora bien, los conflictos de intereses dan lugara los procesos contenciosos; en cambio, las in
certidumbres jurídicas corresponden a los procesos no contenciosos, conocido también como
de jurisdicción voluntaria. Ambos deben tener relevancia jurídica. A modo de ejemplo, no tie
ne esta calidad si un vecino deja de saludarnos, cuyo ámbito atañe a las reglas de trato social.
Normalmente, en un proceso contencioso se llega a la cosa juzgada; en un proceso no conten
cioso no existe cosa juzgada. Si un heredero ha sido preterido en la sucesión intestada, puede
demandar la petición de herencia.
Elementos y poderes de la jurisdicción:
Elementos:
Notio: Poder que tiene el órgano jurisdiccional para conocer la cuestión propuesta.
Vocatio: Consiste en ordenar la comparecencia de los litigantes y seguir el proceso en re
beldía.
Coertio: Empleo de los medios necesarios dentro del proceso, para que se cumplan los
mandatos judiciales, como son los apremiosy las multas.
ludicium: La litis normalmente se soluciona a través de la sentencia.
Executio: Poder para hacer cumplir las sentencias con la calidad de cosa juzgada.
Poderes:
Poder de decisión: Los jueces dirimen con fuerza obligatoria la controversia.
Poder de coerción-, en virtud del cual los jueces se procuran los elementos necesarios para
su decisión, de oficio o a pedido de parte, removiendo los obstáculos que se oponen al
cumplim iento de su misión.
Poder de documentación o investigación: es decir para ordenar y practicar pruebas, aun cuan
do haya oposición de parte, en cuyo caso los jueces aplican la coerción.
Poder de ejecución: implica no sólo el uso de la coerción, sino esencialmente de hacer que se
cumpla lo ordenado en la sentencia, cuando el obligado se niega a hacerlo voluntariamente.
Clases de la jurisdicción:
Según exista o no conflicto
Contenciosa: Se caracteriza porque en ésta hay litigio, y corresponde al órgano jurisdiccio
nal decidir.
Voluntaria: El litigio no existe, y tampoco existen partes insatisfechas.
Según la organización que la aplica
Ordinaria: correspondiente al fuero civil o común.
Especial: correspondiente a la m ilitar o arbitral.
Según la especialidad del órgano jurisdiccional
Constitucional, civil, penal, laboral, de familia, etc. Dependiendo de las especialidades
que la ley establezca.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCION
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 316 of 1506 --

UBILEX
6. La competencia
La competencia es el poder perteneciente al juez considerado en singular; la jurisdicción es
el poder perteneciente a todos los jueces en conjunto. La competencia es una aplicación del
principio fundamental de la división del trabajo y por eso el poderse divide, se distribuye en
tre los jueces.
Todos los jueces ejercen jurisdicción, pero cada uno de ellos tiene delimitado el campo en que
la ejerce. La jurisdicción representa la función de aplicar el derecho, mientras que la compe
tencia, es la actitud legal de ejercer dicha función en relación con un caso determinado.
Reglas para la determinación de la competencia: La competencia en nuestro sistema proce
sal, solo y únicamente puede ser fijada por Ley, siendo su naturaleza típica y la encontramos
en el Código Procesal Civil, la Ley Orgánica del Poder judicial entre otras normas específicas.
Así tenemos que la distribución de la competencia es por razón de: territorio, de la materia, de
la cuantía, de grado o función.
Competencia por razón de la materia,- Llamada también factor objetivo de la competen
cia. Atiende a la naturaleza de la pretensión y las disposiciones legales que la regulan (Art.
9 del C.PC.).
La competencia por razón de la materia se determina en función de la relación jurídica
que subyace al conflicto de intereses o a la incertidumbre jurídica que sirven de sustrato
al procesoy, en especial, por la pretensión y/o pretensiones que, respecto de ese conflicto
o esa incertidumbre, se plantean en el proceso.
La razón que está detrás de este criterio es lograr la especialización de los tribunales.
Ejemplo: juez especializado de familia, juez especializado en lo civil, etc.
Competencia por razón de la función o grado.- Primera instancia es el órgano jurisdiccio
nal ante el cual se interpone la demanda; segunda instancia es el órgano revisor. Art. 28
del C.PC.; concordancias: Art. 139 inc. 6 de la Constitución; Art. 11 T.U.O. L.O.P.J.; Art. X del T.
RdelC.RC.
• Competencia funcional vertical supone una asignación de atribuciones establecida
en la ley acerca de a quién le corresponde el conocimiento del primer o segundo
examen de una resolución judicial. Según este criterio, se realiza una división entre
juez a quo y juez ad quem. Al primero de ellos se le asigna el primer conocimiento
del asunto, correspondiéndole su estudio y resolución; el primer grado. Al segundo
de ellos, se le asigna el segundo conocimiento del asunto, correspondiéndole la re
visión de aquello que ha sido resuelto por el a quo y su confirmación, revocación o
anulación dependiendo de si encuentra o no errada la resolución del a quo y, de ser
el caso, la determinación del tipo de error en el que se incurre.
• Competencia funcional horizontal supone una asignación de atribuciones establecidas
en la ley respecto de diversas fases del proceso o, la atribución del conocimiento de
un incidente o un aspecto relacionado al proceso a un órgano jurisdiccional distin
to a aquel que conoce el proceso. En este últim o caso se trata de un incidente no
originado a consecuencia de la solicitud de un doble conocimiento de una misma
decisión, de ¡o contrario, nos encontraríamos ante un supuesto de competencia fun-
316 BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 317 of 1506 --

Tema 1: Temas com unes a la especialidad: Civil, Familia y Comercia
cional vertical, sino, de un incidente que, aunque, asignado a un órgano superior, le
corresponde a él porque así lo establece la ley. Un ejemplo de esto últim o puede ser
la competencia que se le asigna a la Sala Civil de la Corte Superior respectiva para
conocer del conflicto de competencia producido entre dos órganos del mismo dis
trito judicial o, la asignación de competencia que se le da a la Sala Civil de la Corte
Suprema para conocer del conflicto de competencia producido entre órganos juris
diccionales de distritos judiciales distintos.
Competencia por razón de la cuantía.- La competencia se determina por el valor eco
nómico del petitorio (Arts. 10 al 13 del C.RC). Cabe advertir que en algunas situaciones
no son aplicables las reglas de la competencia en estudio, en cuyo caso se aplican las re
glas de la competencia por la materia. Por ejemplo: Existen petitorios incuantificables en
dinero (v. gr.): La filiación extramatrimonial); otro caso, es el otorgamiento de escritura
pública, cuya vía procedimental es la sumarísima o la ejecutiva, según el artículo 1412 del
Código Civil.
Para obtener la cuantía se ha instaurado la Unidad de Referencia Procesal (URP), que se
obtiene tomando en cuenta el 10% de la Unidad Impositiva Tributaria (UIT), correspon
diente al inicio de cada año judicial (enero).
Al valor económico principal se suman los accesorios devengados al tiempo de la interpo
sición de la demanda.
Si la demanda contiene varias pretensiones patrimoniales, la cuantía se determina por la
suma del valor de todas ellas. Si se trata de pretensiones alternativas o subordinadas se
toma en cuenta la de mayor valor.
Es inadmisible la oposición del demandado a la cuantía, salvo disposición legal en contra
rio.
De oficio, el Juez, puede corregir la cuantía si de la demanda o sus anexos fluye una cuan
tía distinta, procediendo, en su caso, a inhibirse del conocimiento de la demanday remi
tiéndola al Juez competente.
El actorque exagere manifiestamente la cuantía, dando lugara que se declare fundadoel
cuestionamiento de la competencia, pagará las costas, los costosy una m ulta no menor a
una ni m ayoracinco URP
Competencia por razón del territorio.- Este tipo de competencia tiene su justificación por
motivos geográficos o de territorio en el que se encuentran distribuidos lo juzgados, aquí
no se consideran a los tribunales superiores, ya que ellos intervienen solo en razón de su
función. Al respecto Lino Palacio nos manifiesta que, las reglas que se refieren al criterio
territorial, están orientados principalmente a allanar a las partes y peticionarios los incon
venientes que se derivan de la distancia y así obtener un mayor rendimiento de la justicia
que surge de la aproximación entre la sede del órgano judicial y al lugar donde se produce
la prueba. A su turno Mario Alzamora Valdez nos indica que la competencia territorial está
referida a los órganos de primera instancia, en virtud del principio perpetuatio juhsdictions
ya que es la situación de hecho que existe en el momento de admitirse la demanda la que
determina la competencia para todo el juicio sin que las modificaciones puedan afectarlas.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES 317

-- 318 of 1506 --

UBILEX
En buena cuenta, la competencia por razón de territorio se determina por el lugar donde se
encuentre el dom icilio del demandado, o el lugar de los hechos de donde se deriva la preten
sión. Es preciso señalar también que este tipo de competencia se encuentra regulada en los
Arts. 14 al 27 del Código Procesal Civil.
Modificaciones a la regla de competencia territorial.-
a - PvÓYYoga de la competencia teYYitoYial - Se produce prórroga de la competencia territorial
cuando las partes renuncian al juez que les corresponde con arreglo a ley; ésta puede
producirse en forma expresa o en forma tácita. Esta modificación de la competencia te
rritorial no es posible cuando la ley la declare improrrogable. Habrá prórroga tácita res
pecto del demandante, por el hecho de interponer la demanda. Se producirá respecto del
demando cuando éste es notificado con la demanda y deje transcurrir el plazo legal sin
cuestionar su competencia o contesta la demanda sin invocar el derecho a que ese pro
ceso sea conocido por el juez de su domicilio. Y habrá prórroga expresa cuando las partes
dejen constancia en el convenio o contrato que renuncian expresamente al juez de sus
dom iciliosy se someten a la jurisdicción de determinados jueces.
(T) La competencia por razón de territorio tiene un carácter relativo en razón de haberse
dispuesto en atención al interés de las partes, de ahí que sea susceptible de ser renunciada,
según se desprende de lo dispuesto por el artículo 25° del Código Procesal Civil," Exp. N°311-
2005.
. B M © “Las partes acordaron someterse a la jurisdicción de los jueces y Tribunales del Callao, y
habiendo la parte demandante interpuesto la demanda y la parte demandada contestado la
misma, se ha producido la prórroga de la competencia a que se refiere el artículo treintisiete del
Código Procesal Civil, pues ésta no ha cuestionado la competencia del Juzgado no como excepción dentro
del término previsto en el ordenamiento procesal, ni como inhibitoria. (...) En ese sentido habiendo ocurrido
la prórroga de la competencia, por la intervención de ambas partes al proceso, una ejerciendo su derecho de
acción y la otra el de contradicción, ha operado el sometimiento de las partes de la competencia territorial de
otra jurisdicción distinta a la pactada." Exp. N° 809-99.
b.- Algunas competencias son ¡mpYOYYogables, por disposición expresa de la ley procesal, como es
el caso de la competencia en materia sucesoria, asignada al Juez del últim o dom icilio del
causante.
"(...) En lo relativo a la competencia territorial, el único supuesto previsto por la ley para que el
órgano jurisdiccional declare su incompetencia de oficio es cuando ésta sea de carácter im
prorrogable, según se desprende de lo dispuesto en el artículo 35° del Código Procesal Civil, sin
perjuicio de que pueda ser invocada como excepción. A ello debe agregarse que la competencia
por razón de territorio tiene un carácter relativo en razón de haberse dispuesto en atención al
interés de las partes, de ahí que sea susceptible de ser renunciada." Exp. N° 331 -2 0 05 .
Competencia facultativa (Art. 24 C.P.C.).- Además del Juez del dom icilio del deman
dado, también es competente, a elección del demandante:
1. El Juez del lugar en que se encuentre el bien o bienes tratándose de pretensiones
sobre derechos reales. Igual regla rige en los procesos de retracto, título supletorio,
prescripción adquisitiva y rectificación o delimitación de áreas o linderos, expro
piación, desalojo e interdictos. Si la demanda versa sobre varios inmuebles situa
dos en diversos lugares será competente el Juez de cualquiera de ellos;
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 319 of 1506 --

