Cuestionan!iento de la competencia: El quebrantamiento del presupuesto procesal de la
competencia, conlleva a la incompetencia. La incompetencia por razón de la materia, la cuan-
tía y el territorio, esta últim a cuando es improrrogable (como en el caso de sucesiones; no en
los demás casos), se declara de oficio en cualquier estado y grado del proceso, sin perjuicio de
que pueda ser invocada como excepción de incompetencia.
Excepción de incompetencia: Recordemos que las excepciones son medios de defensa típicos
a través de los cuales el demandado, en ejercicio de su derecho de defensa, cuestiona la au
sencia o presencia defectuosa de un presupuesto procesal o una condición de la acción. Una
de las excepciones previstas en nuestro Código Procesal Civil es la excepción de incompetencia
(art. 446 inciso 1 del C.RC.). A través de este mecanismo, el demandado acude donde el juez
incompetente que está conociendo el proceso y cuestiona su propia competencia, esperando
un pronunciamiento de dicho juez sobre ella.
Contienda de competencia (Conflictos de competencia negativos y positivos)
Al conflicto positivo se puede llegar por:
1) Demanda inhibitoria estimada por el juez ante quien se presentay consiguiente negativa
del juez requerido por éste;
2) Reclamo oficioso del conocimiento de un asunto, de un juez a otro, por existir fuero de
atracción o conexidad de causas que exija que la sentencia que se dicte en una de ellas
deba producir en la otra los efectos del caso juzgado. La hipótesis supone que el juez re
clamado o requerido mantenga su competenciay resista el envío de las actuaciones que
tram itan ante él.
Al conflicto negativo se puede llegar por:
1) Estimación por un juez de una excepción de incompetencia (vía declinatoria) y consi
guiente denegación oficiosa de competencia por otro juez o, en su defecto, estimación de
una nueva excepción de incompetencia. El caso supone que los dos jueces intervinientes
se declaren incompetentes;
