constituye denegación de justicia.
Para que el conflicto pueda existir es menester que se cumplan los siguientes requisitos:
1) Deben coexistir dos resoluciones judiciales coincidentes en la afirmación de competencia o
de incompetencia;
2) Los jueces en conflicto— y que han emitido las resoluciones coincidentes— deben perte-
/ necera una misma jerarquía funcional.
En todos los casos, la solución al conflicto de competencia debe darla el superior común a
ambos jueces.
7. Recusación
Se pretende que un funcionario judicial no siga conociendo una controversia por estar incurso
en causa legal invocada por la parte.
Conforme al art. 307 del C.RC. son causales de recusación:
1. Es amigo íntimo o enemigo manifiesto de cualquiera de las partes, demostrado por he
chos inequívocos;
2. El o su cónyuge o concubino o su pariente en la línea directa o en la línea colateral hasta el
segundo grado, primero de afinidad o adoptado, tienen relaciones de crédito con alguna
de las partes; salvo que se trate de persona de derecho o de servicio público;
3. Él o su cónyuge o concubino, son donatarios, empleadores o presuntos herederos de al
guna de las partes;
4 . Haya intervenido en el proceso como apoderado, miembro del Ministerio Público, perito,
testigo o defensor;
5. Tiene interés directo o indirecto en el resultado del proceso; y,
6 . Exista proceso vigente entre él o su cónyuge o concubino con cualquiera de las partes,
siempre que no sea promovido con posterioridad al inicio del proceso.
8. Capacidad procesal
La capacidad procesal responde a la pregunta ¿cómo deben comparecer las partes, si directa
mente o a través de un representante? La capacidad procesal es un presupuesto procesal, al
igual que la competenciay los requisitos de la demanda.
Todos tienen capacidad para ser parte material en un proceso, que está ligada al titu la r de la
relación jurídica sustantiva, mas para realizar actos procesales válidos se requiere de capaci
dad procesal (artículos 5 7 y 58 del C.RC.). Ejemplo, lo constituyen las situaciones de un menor
de edad, una empresa.
Normalmente, la persona natural adquiere la capacidad procesal al cumplir los 18 años de
edad. También la adquiere a partir del nacimiento del hijo o hija únicamente para realizar
los siguientes actos: 1. Inscribir el nacimientoy reconocer a sus hijos e hijas. 2. Demandar por
gastos de embarazo y parto. 3. Demandary ser parte en los procesos detenencia, alimentos y
