procesal al obtener título oficial que los autorice ejercer profesión u oficio.
9. Curadoría procesal
Hinostroza Mínguez señala que el curador procesal es aquella persona designada por el Juez
para comparecer en un proceso en lugar de la parte o de su representante legal por no tener
éstos capacidad procesal o no poder hacerla efectiva. El nombramiento necesariamente re
caerá en un abogado.
El antecedente legislativo del curador procesal lo tenemos en el derogado Código de Procedi
mientos Civiles bajo la figura del Defensor de Ausentes.
El artículo 61o del Código Procesal Civil prescribe que el curador procesal es un abogado nom
brado por el Juez a pedido de interesado, que interviene en el proceso en los siguientes casos:
1. Cuando no sea posible emplazar válidamente al demandado por ser indeterminado, in
cierto o con domicilio o residencia ignorado, según lo dispuesto por el artículo 435°;
2. Cuando no se pueda establecer o se suspenda la relación procesal por restricción de la
capacidad de ejercicio de la parte o de su representante legal;
3. Cuando exista falta, ausencia o impedimento del representante de la persona con capa
cidad de ejercicio restringida, según lo dispuesto por el artículo 66°; o,
4. Cuando no comparece el sucesor procesal, en los casos que así corresponda, según lo dis
puesto por el artículo 108o.
Concluye la actuación del curador procesal si la parte o su representante legal comparecen al
haber adquirido o recuperado su capacidad procesal.
El artículo 6 6 ° del C.C. señala que en caso de falta, ausencia o impedimento del representante
de la persona con capacidad de ejercicio restringida, se aplican las siguientes reglas:
1. Cuando la persona con capacidad de ejercicio restringida no tenga representante legal o
éste estuviera ausente y surja la necesidad de comparecer en un proceso, lo expondrá así
al Juez para que le designe curador procesal o confirme al designado por él, si lo considera
idóneo.
2. Cuando la demanda se dirija contra una persona con capacidad de ejercicio restringida
que carece de representante o éste se halle ausente, el Juez le nombrará un curador pro
cesal o confirmará el propuesto por la persona con capacidad de ejercicio restringida, si lo
considera idóneo.
3. El Juez nombrará curador procesal para la persona con capacidad de ejercicio restringi
da que pretenda demandar a su representante legal, o que sea demandado por éste, o
confirmará el propuesto por la persona con capacidad de ejercicio restringida, si fuere
idóneo.
