4. También se procederá al nombramiento de curador procesal cuando el Juez advierta la
aparición de un conflicto de intereses entre la persona con capacidad de ejercicio restrin
gida y su representante legal, o confirmará el propuesto por la persona con capacidad de
ejercicio restringida.
El artículo 79 in fine del Código acotado señala que en caso de muerte o declaración de ausen
cia, determinación de restricción de la capacidad de ejercicio del representante o del apodera
do, remoción o cese de nombramiento del representante legal de una persona con capacidad
de ejercicio restringiday circunstancias análogas, se suspenderá el proceso por un plazo máxi
mo de 30 días, mientras se designa representante o curador procesal.
10. La lepresentación procesal
Líneas arriba hemos indicado que se puede comparecer al proceso directamente o a través de
un representante. A través de la representación procesal una persona llamada representante
efectúa actos procesales en nombre de otra, denominada representado. Los efectos de esos
actos procesales recaen en la esfera jurídica del representado.
Las clases de representación son las siguientes:
a) Legal. Se encuentra determinada en el ordenamiento jurídico, como es el caso de la re
presentación de los menores de edad, de una persona jurídica, del Estado en juicio, etc.
Aquí es necesario subrayar la representación legal de los patrimonios autónomos (artícu
lo 65 del C.RC.). Existe patrimonio autónomo cuando dos o más personas tienen un dere
cho respecto a un bien o un conjunto de bienes, tales como la sociedad de gananciales, la
copropiedad, la masa hereditaria. Si se actúa como parte demandante, cualquiera de sus
conformantes puede promover la demanda, sin requerir poder del otro; en cambio, en el
emplazamiento de los demandados es obligatorio comprender a todos ellos, pues se está
ante un Iitisconsorcio necesario.
b) Judicial. Estrictamente se refiere al curador procesal (artículo 61 del C.RC.); corresponde a
lo que antes se denominaba defensores de ausentey herencia.
A pedido del interesado el juez nombra como curador a un abogado, en supuestos tales
como: No sea posible emplazar válidamente al demandado por ser indeterminado, in
cierto o con domicilio ignorados, según lo previsto en el artículo 435 del Código adjetivo;
no se pueda establecer o se suspenda la relación procesal por restricción de la capacidad
de ejercicio de la parte o de su representante legal; exista falta, ausencia o impedimento
del representante de la persona con capacidad de ejercicio restringida, según lo dispuesto
por el artículo 66 C.RC; o no comparece el sucesor procesal, según lo dispuesto en el artí
culo 108 del Código adjetivo.
La actuación del curador procesal concluye si la parte o su representante legal compare
cen al haber adquirido o recuperado su capacidad procesal.
La resolución que declara el nombramiento de curador, y que es adversa a quien el cu
rador procesal representa, se eleva en consulta si aquél no apela (inc. z del Art. 408 del
C.RC.).
