c) Voluntaria. Este tipo de representación tiene como núcleo el poder, el mismo que por
naturaleza jurídica es unilateral. Se puede conferirá uno o varios apoderados.
Si son varios los apoderados podrán actuar indistintamente y cada uno de ellos asume la
responsabilidad por los actos procesales que realice; no es válida la designación o actua
ción de apoderados conjuntos, salvo para los actos de allanamiento, transacción o desis
tim iento (Art. 68 del C.RC.).
¿Cuáles son las formalidades del poder?
Para efectos procesales puede ser: Por acta o por escritura pública (Art. 72 del precitado Códi
go). En el primercaso, ahora previo abono de unatasa judicial, se confiere el poder acudiendo
directamente al juzgado; en el segundo caso, debe precisarse que no es necesaria su inscrip
ción registral.
¿Cuáles son facultades que emergen del poder?
Facultades generales y especiales.
Se requieren facultades especiales para todos los actos de disposición de derechos sustanti
vos y para demandar, reconvenir, contestar demandas y reconvenciones, desistírse del proceso
y de la pretensión, allanarse a la pretensión, conciliar, transigir, someter a arbitraje las pre
tensiones controvertidas en el proceso, sustituir o delegar la representación procesal y para
los demás actos que exprese la ley. Aquí rige el principio de literalidad del poder, según el cual
no se presume la existencia de facultades especiales no conferidas explícitamente (artículo
75C.RC.).
Las facultades generales (artículo 74 C.RC.) se aplican para todos aquellos actos procesales
que no requieran de las facultades especiales, como v. gr., deducir excepciones, absolverlas;,
interponer medios impúgnatenos; solicitar la ejecución de sentencia; cobrar las costas y cos
tos; etc.
Personas jurídicas y poder procesal: De acuerdo a la Ley 26789, el administrador, represen
tante legal o presidente del consejo directivo, según corresponda de las personas jurídicas re
guladas en la Sección Segunda del Libro I del Código Civil, gozan de las facultades generales
y especiales de representación procesal señaladas en los artículos 74 y 75 del C.RC., porel solo
mérito de su nombramiento inscrito en el registro correspondiente, salvo disposición esta
tutaria en contrario. Y, en cuanto a la formalidad, sólo debe presentarse copia notarialmente
certificada del documento donde conste el nombramiento inscrito.
Poder otorgado en el extranjero. Debidamente traducido de ser el caso, debe ser aceptado ex
presamente por el apoderado en el escrito que se apersona como tal (artículo 73 C.RC.).
Sustitución y delegación del poder. Son formas de sub apoderamiento; tienen que estar pre
vistas dentro del otorgamiento de las facultades especiales. La sustitución consiste en el cese
de la representación sin posibilidad de reasumirla; la delegación faculta al delegante para re
vocarla y reasumir la representación. Estas modalidades de sub apoderamiento tienen que
conferirse de la misma forma que se otorgó el poder originario (artículo 77 C.RC.).
Efectos del cese de la representación (artículo 79 C.RC.). Si tiene como causa la decisión del
representado, surtirá efectos desde que la parte comparece al proceso por sí o por medio de
