11. Interrupción y suspensión de proceso
Interrupción del proceso (Art 317C.P.C): La declaración de interrupción tiene por efecto cor
tar el plazo o diferir el término para realizar un acto procesal, produciendo la ineficacia de la
fracción del plazo o difiriendo el término transcurrido.
La interrupción será declarada por el Juez en resolución inimpugnable, de oficio o a pedido
de parte, sustentándola en la ocurrencia de un hecho imprevisto o que siendo previsible es
inevitable.
El plazo para solicitar la declaración de interrupción vence al tercer día de cesado el hecho
interruptivo.
Suspensión del proceso o del acto procesal (Art. 318CP.C): La suspensión es la inutilización
de un período de tiempo del proceso o de una parte del plazo concedido para la realización
de un acto procesal.
Suspensión convencional (Art. 319 C.P.C): La suspensión acordada por las partes requiere
aprobación judicial. Se concede sólo una vez por instanciay no puede ser mayor de dos meses
en cada caso.
Suspensión legal y judicial (Art. 320 C.RC): Se puede declarar la suspensión del proceso, de
oficio o a pedido de parte, en los casos previstos legalmente o cuando a criterio del Juez sea
necesario. El Juez a pedido de parte, suspende la expedición de la sentencia en un proceso
siempre que la pretensión planteada en él dependa directamente de lo que debe resolver
en otro proceso en el que se haya planteado otra pretensión cuya dilucidación sea esencial y
determinante para resolver la pretensión planteada por él. Para ello es necesario que las pre
tensiones sean conexas, a pesar de lo cual no puedan ser acumuladas, caso contrario, deberá
disponerse su acumulación.
12. Formas especiales de conclusión del proceso: allanamiento. Desistimiento. Abandono.
Transacción. Conciliación
Allanam iento y reconocimiento. Allanam iento es el acto procesal mediante el cual el deman
dado voluntariamente conviene expresamente con la demanda, legalizando su firm a ante el
auxiliar jurisdiccional. Procede el allanamiento respecto de alguna de las pretensiones. No
existe norma que prohíba que se produzca también el allanamiento respecto a la reconven
ción.
324 BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 325 of 1506 --

Tema 1: Temas com unes a la especialidad: Civil, Familia y Comercial
El reconocimiento es una modalidad del allanamiento, y se caracteriza porque el emplazado
además de aceptar la pretensión, admite la veracidad de los hechos expuestos en la demanda
y los fundamentos jurídicos de ésta.
El demandado puede allanarse a la demanda en cualquier estado del proceso, previo a la sen
tencia. Declarado el allanamiento, el juez debe expedir sentencia, salvo que éste no se refiera
a todas las pretensiones demandadas.
Es improcedente el allanamiento cuando: El demandado no tiene capacidad para disponer
el derecho en conflicto; el apoderado o representante del demandado carece de facultad para
allanarse; los hechos admitidos ser probados por otros medios, además de la declaración de
parte; el conflicto de intereses afecta el orden público o las buenas costumbres; el conflicto
de intereses comprende derechos indisponibles; habiendo litisconsorcio necesario, el allana
miento no proviene de todos los demandados; presume la existencia de dolo o fraude proce
sal; advierte que la sentencia a dictarse va a surtir efecto frente a tercero no emplazado; o el
demandado es el Estado u otra persona de derecho público, salvo que su representante tenga
autorización expresa.
Transacción judicial. Es aquel acto jurídico mediante el cual las partes, haciéndose concesio
nes recíprocas, ponen fin al litigio, teniendo efecto de cosa juzgada. Se aplican supletoriamen
te las normas del Código Civil.
Las concesiones recíprocas suponen el reconocimiento parcial de la pretensión del derecho
ajeno y la renuncia parcial de la pretensión o derecho propio. La doctrina precisa que no nece
sariamente las concesiones puedan ser equivalentes.
Con la transacción judicial no se puede crear, regular, modificar o extinguir relaciones jurídicas
sustantivas ajenas al proceso (artículo 337 in fine C.RC.).
La transacción judicial puede celebrarse en cualquier estado del proceso, incluso durante el
trámite del recurso de casación y aun cuando la causa esté al voto o en discordia.
La transacción judicial debe ser realizada únicamente por las partes o quienes en su nombre
tengan facultad expresa para hacerlo. Se presenta por escrito, precisando su contenido y lega
lizando sus firmas ante el secretario respectivo.
Transacción extrajudicial. Si habiendo proceso abierto las partes transigen fuera de éste, pre
sentarán el documento que contiene la transacción legalizando sus firmas ante el secretario
en el escrito que lo acompañan, requisito que no será necesario cuando la transacción conste
en escritura pública o documento con firma legalizada. Un requisito formal adicional es el
abono de latasa judicial.
El Estadoy otras personas de derecho público, sólo pueden transigir previa aprobación expre
sa de la autoridad o funcionario competente.
